function queryValue(url, key) {
  const query = String(url || "").split("?")[1] || "";
  for (const part of query.split("&")) {
    const index = part.indexOf("=");
    const name = index < 0 ? part : part.slice(0, index);
    if (name === key) return decodeURIComponent(index < 0 ? "" : part.slice(index + 1));
  }
  return "";
}
function nativePlaybackUrl(value) {
  return String(value || "").replace(/^https:\/\/play-edge-cdn\.itunes\.apple\.com/i, "https://play-edge.itunes.apple.com").replace(/^https:\/\/play-cdn\.itunes\.apple\.com/i, "https://play.itunes.apple.com");
}
function upstreamHeaders() {
  const output = {};
  const headers = $request.headers || {};
  for (const key of Object.keys(headers)) {
    if (/^(?:host|content-length|accept-encoding|range)$/i.test(key)) continue;
    output[key] = headers[key];
  }
  return output;
}
function fail(status, message) {
  $done({ response: { status, headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store" }, body: message } });
}
const movieAssetId = "6809916863";
const releaseBody = "WEBVTT\nX-TIMESTAMP-MAP=MPEGTS:900000,LOCAL:00:00:00.000\n\n9901803\n00:00:00.000 --> 00:00:02.080 align:middle line:10%,start position:50%,middle\nGitHub：rexchen1803\n\nsource-0001\n00:00:29.988 --> 00:00:32.448 align:middle line:100%,end position:50%,middle\n- 这次是什么花？\n<i>- 不知道</i>\n\nsource-0002\n00:00:32.616 --> 00:00:33.784 align:middle line:100%,end position:50%,middle\n白色的？\n\nsource-0003\n00:00:33.951 --> 00:00:35.619 align:middle line:100%,end position:50%,middle\n<i>裱框颜色？</i>\n\nsource-0004\n00:00:35.786 --> 00:00:38.539 align:middle line:100%,end position:50%,middle\n- 深色\n- 邮戳？\n\nsource-0005\n00:00:38.705 --> 00:00:40.791 align:middle line:100%,end position:50%,middle\n<i>跟上次一样</i>\n\nsource-0006\n00:00:41.250 --> 00:00:42.960 align:middle line:100%,end position:50%,middle\n没有字条\n\nsource-0007\n00:00:43.126 --> 00:00:44.545 align:middle line:100%,end position:50%,middle\n<i>什么都没有</i>\n\nsource-0008\n00:00:45.504 --> 00:00:47.881 align:middle line:100%,end position:50%,middle\n<i>亨利 我很抱歉</i>\n\nsource-0009\n00:03:22.494 --> 00:03:24.121 align:middle line:100%,end position:50%,middle\n会上诉吗？\n\nsource-0010\n00:03:24.288 --> 00:03:26.707 align:middle line:100%,end position:50%,middle\n这是今年最大的媒体事件？\n\nsource-0011\n00:03:26.874 --> 00:03:29.209 align:middle line:100%,end position:50%,middle\n别轻描淡写 麦可\n那招没用\n\nsource-0012\n00:03:29.376 --> 00:03:31.670 align:middle line:100%,end position:50%,middle\n你也别小题大做\n那招同样没用\n\nsource-0013\n00:03:31.837 --> 00:03:34.214 align:middle line:100%,end position:50%,middle\n麦可 说几句话吧\n\nsource-0014\n00:03:34.840 --> 00:03:37.134 align:middle line:100%,end position:50%,middle\n你会上诉吗？\n\nsource-0015\n00:03:37.467 --> 00:03:40.095 align:middle line:100%,end position:50%,middle\n会 跟你上诉\n\nsource-0016\n00:03:40.846 --> 00:03:43.640 align:middle line:100%,end position:50%,middle\n<i>布隆维斯特一直扮演受害者</i>\n\nsource-0017\n00:03:43.807 --> 00:03:46.268 align:middle line:100%,end position:50%,middle\n<i>勇敢对抗恶势力的记者</i>\n\nsource-0018\n00:03:46.435 --> 00:03:48.896 align:middle line:100%,end position:50%,middle\n<i>我不明白为何无法证明他有恶意</i>\n\nsource-0019\n00:03:49.062 --> 00:03:52.232 align:middle line:100%,end position:50%,middle\n<i>- 你说别人是罪犯…\n- 你要说这种话…</i>\n\nsource-0020\n00:03:52.399 --> 00:03:54.067 align:middle line:100%,end position:50%,middle\n<i>布隆维斯特最喜欢搞宣传</i>\n\nsource-0021\n00:03:54.234 --> 00:03:57.196 align:middle line:100%,end position:50%,middle\n<i>被控诽谤对记者来说是最糟的</i>\n\nsource-0022\n00:03:57.362 --> 00:04:00.532 align:middle line:100%,end position:50%,middle\n<i>十六项加重诽谤罪成立</i>\n\nsource-0023\n00:04:00.699 --> 00:04:04.328 align:middle line:100%,end position:50%,middle\n一份三明治和黑咖啡\n\nsource-0024\n00:04:04.494 --> 00:04:07.414 align:middle line:100%,end position:50%,middle\n<i>今年初布隆维斯特在报道中</i>\n\nsource-0025\n00:04:07.581 --> 00:04:10.751 align:middle line:100%,end position:50%,middle\n<i>指称温氏集团的温纳斯壮先生</i>\n\nsource-0026\n00:04:10.918 --> 00:04:14.588 align:middle line:100%,end position:50%,middle\n<i>挪用政府计划投资波兰的资金</i>\n\nsource-0027\n00:04:14.755 --> 00:04:17.673 align:middle line:100%,end position:50%,middle\n<i>与克罗地亚右翼乌斯塔沙组织\n进行武器交易</i>\n\nsource-0028\n00:04:17.841 --> 00:04:20.802 align:middle line:0%,start position:50%,middle\n<i>我不怪布隆维斯特先生\n他是位出色的记者</i>\n\nsource-0029\n00:04:20.969 --> 00:04:23.305 align:middle line:100%,end position:50%,middle\n<i>我认为他并无恶意</i>\n\nsource-0030\n00:04:23.472 --> 00:04:25.516 align:middle line:100%,end position:50%,middle\n<i>但报道完全不属实</i>\n\nsource-0031\n00:04:25.682 --> 00:04:28.310 align:middle line:100%,end position:50%,middle\n<i>所以我们必须作出回应</i>\n\nsource-0032\n00:04:28.477 --> 00:04:31.730 align:middle line:0%,start position:50%,middle\n<i>记者也得像其他人一样明白</i>\n\nsource-0033\n00:04:31.933 --> 00:04:34.692 align:middle line:0%,start position:50%,middle\n<i>自己的行为要承担后果</i>\n\nsource-0034\n00:04:35.009 --> 00:04:36.414 align:middle line:0%,start position:50%,middle\n<i>布隆维斯特被判损害赔偿\n六十万瑞典克朗</i>\n\nsource-0035\n00:04:36.610 --> 00:04:39.613 align:middle line:100%,end position:50%,middle\n<i>及支付双方诉讼费用</i>\n\nsource-0036\n00:04:39.780 --> 00:04:43.158 align:middle line:100%,end position:50%,middle\n一包红色万宝路和打火机\n\nsource-0037\n00:05:04.073 --> 00:05:06.869 align:middle line:100%,end position:50%,middle\n（《千禧年》杂志）\n\nsource-0038\n00:05:14.231 --> 00:05:15.274 align:middle line:100%,end position:50%,middle\n我知道\n\nsource-0039\n00:05:24.408 --> 00:05:26.994 align:middle line:100%,end position:50%,middle\n- 你去了哪里？\n- 闲晃、想事情\n\nsource-0040\n00:05:27.160 --> 00:05:28.620 align:middle line:100%,end position:50%,middle\n- 又抽烟？\n- 一根而已\n\nsource-0041\n00:05:35.752 --> 00:05:37.796 align:middle line:100%,end position:50%,middle\nTV4电视台打来\n\nsource-0042\n00:05:37.963 --> 00:05:40.257 align:middle line:100%,end position:50%,middle\n我说拿到判决书才会回应\n\nsource-0043\n00:05:40.424 --> 00:05:42.176 align:middle line:100%,end position:50%,middle\n我拿到判决书了 还有谁打来？\n\nsource-0044\n00:05:42.342 --> 00:05:44.761 align:middle line:100%,end position:50%,middle\n等着看你出丑的人\n\nsource-0045\n00:05:44.928 --> 00:05:47.431 align:middle line:100%,end position:50%,middle\n- 早上一直在接电话？\n- 这件事我也有责任\n\nsource-0046\n00:05:47.598 --> 00:05:49.766 align:middle line:100%,end position:50%,middle\n- 又不是你写的\n- 是我让报道刊出的\n\nsource-0047\n00:05:49.933 --> 00:05:52.102 align:middle line:100%,end position:50%,middle\n- 不一样\n- 杂志社的信用尚未破产\n\nsource-0048\n00:05:52.269 --> 00:05:53.896 align:middle line:100%,end position:50%,middle\n我的毁了\n\nsource-0049\n00:05:56.815 --> 00:05:58.567 align:middle line:100%,end position:50%,middle\n我累了\n\nsource-0050\n00:05:59.067 --> 00:06:02.362 align:middle line:100%,end position:50%,middle\n我要回家睡一个礼拜\n\nsource-0051\n00:06:06.366 --> 00:06:09.077 align:middle line:100%,end position:50%,middle\n我打给老公说今晚不回去\n\nsource-0052\n00:06:09.244 --> 00:06:10.537 align:middle line:100%,end position:50%,middle\n谢谢\n\nsource-0053\n00:06:10.725 --> 00:06:12.481 align:middle line:100%,end position:50%,middle\n（《千禧年》杂志）\n\nsource-0054\n00:06:14.124 --> 00:06:16.251 align:middle line:100%,end position:50%,middle\n她可能不会来\n\nsource-0055\n00:06:16.418 --> 00:06:20.214 align:middle line:100%,end position:50%,middle\n- 你不是已经亲自通知她？\n- 恐怕没用\n\nsource-0056\n00:06:23.842 --> 00:06:27.137 align:middle line:100%,end position:50%,middle\n<i>这里没几个人喜欢她</i>\n\nsource-0057\n00:06:27.304 --> 00:06:29.598 align:middle line:100%,end position:50%,middle\n她适合在家工作\n\nsource-0058\n00:06:30.098 --> 00:06:32.601 align:middle line:100%,end position:50%,middle\n但你有跟她说我想见她\n\nsource-0059\n00:06:32.768 --> 00:06:36.438 align:middle line:100%,end position:50%,middle\n我更常叫她不要和客户见面\n\nsource-0060\n00:06:36.605 --> 00:06:38.732 align:middle line:100%,end position:50%,middle\n<i>- 你喜欢她？\n- 非常</i>\n\nsource-0061\n00:06:38.899 --> 00:06:42.152 align:middle line:100%,end position:50%,middle\n<i>她是我最出色的调查员之一\n看她的报告就知道</i>\n\nsource-0062\n00:06:42.319 --> 00:06:46.156 align:middle line:100%,end position:50%,middle\n- 但是？\n- 你可能不会喜欢她\n\nsource-0063\n00:06:46.782 --> 00:06:49.201 align:middle line:100%,end position:50%,middle\n- 她很特别\n- 哪方面特别？\n\nsource-0064\n00:06:50.285 --> 00:06:51.328 align:middle line:100%,end position:50%,middle\n任何方面\n\nsource-0065\n00:06:57.543 --> 00:06:59.586 align:middle line:100%,end position:50%,middle\n<i>莎兰德来了</i>\n\nsource-0066\n00:07:05.384 --> 00:07:06.802 align:middle line:100%,end position:50%,middle\n莉丝\n\nsource-0067\n00:07:06.969 --> 00:07:09.221 align:middle line:100%,end position:50%,middle\n迪奇佛洛德先生\n\nsource-0068\n00:07:09.388 --> 00:07:11.348 align:middle line:100%,end position:50%,middle\n你好吗？\n\nsource-0069\n00:07:22.355 --> 00:07:23.978 align:middle line:100%,end position:50%,middle\n报告有问题吗？\n\nsource-0070\n00:07:24.203 --> 00:07:25.862 align:middle line:100%,end position:50%,middle\n报告很完整\n\nsource-0071\n00:07:26.029 --> 00:07:28.991 align:middle line:100%,end position:50%,middle\n但我还想知道报告里没写的事\n\nsource-0072\n00:07:29.157 --> 00:07:32.077 align:middle line:100%,end position:50%,middle\n- 所有东西都在报告里\n- 你对他的看法呢？\n\nsource-0073\n00:07:32.578 --> 00:07:36.081 align:middle line:100%,end position:50%,middle\n- 那不在我职责范围\n- 所以你没任何看法？\n\nsource-0074\n00:07:39.710 --> 00:07:41.253 align:middle line:100%,end position:50%,middle\n依我看 他很“干净”\n\nsource-0075\n00:07:41.420 --> 00:07:43.964 align:middle line:100%,end position:50%,middle\n你说个人卫生？\n\nsource-0076\n00:07:44.423 --> 00:07:48.177 align:middle line:100%,end position:50%,middle\n他表里如一\n在他的行业里，这就是优势\n\nsource-0077\n00:07:48.343 --> 00:07:51.430 align:middle line:100%,end position:50%,middle\n经过今天的判决\n他的资产应该所剩无几\n\nsource-0078\n00:07:51.615 --> 00:07:53.441 align:middle line:100%,end position:50%,middle\n没错 他糗大了\n\nsource-0079\n00:07:53.649 --> 00:07:55.139 align:middle line:100%,end position:50%,middle\n如果真是那样\n\nsource-0080\n00:07:55.309 --> 00:07:58.061 align:middle line:100%,end position:50%,middle\n你是说他被陷害？\n\nsource-0081\n00:07:58.228 --> 00:08:00.022 align:middle line:100%,end position:50%,middle\n那不在我调查范围\n\nsource-0082\n00:08:00.189 --> 00:08:01.815 align:middle line:100%,end position:50%,middle\n但你说对了\n\nsource-0083\n00:08:01.982 --> 00:08:04.610 align:middle line:100%,end position:50%,middle\n他作为记者确实出了大丑\n\nsource-0084\n00:08:04.776 --> 00:08:08.113 align:middle line:100%,end position:50%,middle\n判决后 他财务状况如何？\n\nsource-0085\n00:08:08.280 --> 00:08:11.033 align:middle line:100%,end position:50%,middle\n判决几乎赔光他的积蓄\n\nsource-0086\n00:08:11.200 --> 00:08:13.035 align:middle line:100%,end position:50%,middle\n- 我可以走了吗？\n- 等一下\n\nsource-0087\n00:08:13.202 --> 00:08:15.662 align:middle line:100%,end position:50%,middle\n报告里少了另一部分细节\n\nsource-0088\n00:08:15.870 --> 00:08:17.508 align:middle line:100%,end position:50%,middle\n他的私人生活\n\nsource-0089\n00:08:17.713 --> 00:08:19.499 align:middle line:100%,end position:50%,middle\n你有隐匿任何事没报吗？\n\nsource-0090\n00:08:20.682 --> 00:08:22.231 align:middle line:100%,end position:50%,middle\n没什么值得写进报告的\n\nsource-0091\n00:08:22.452 --> 00:08:24.180 align:middle line:100%,end position:50%,middle\n所以有还是没有？\n\nsource-0092\n00:08:24.379 --> 00:08:28.425 align:middle line:100%,end position:50%,middle\n莎兰德的意思是\n每个人都有隐私权\n\nsource-0093\n00:08:28.592 --> 00:08:31.970 align:middle line:100%,end position:50%,middle\n即使是调查对象\n\nsource-0094\n00:08:32.136 --> 00:08:34.681 align:middle line:100%,end position:50%,middle\n我的案子不适用\n我必须知道他所有的事\n\nsource-0095\n00:08:34.847 --> 00:08:38.434 align:middle line:100%,end position:50%,middle\n任何不对劲的事\n就算她觉得没什么\n\nsource-0096\n00:08:42.022 --> 00:08:44.274 align:middle line:100%,end position:50%,middle\n他和总编辑长期保持性关系\n\nsource-0097\n00:08:44.441 --> 00:08:48.570 align:middle line:100%,end position:50%,middle\n他因此离婚 她却没事\n\nsource-0098\n00:08:48.759 --> 00:08:50.478 align:middle line:100%,end position:50%,middle\n他有时会帮她口交\n\nsource-0099\n00:08:50.636 --> 00:08:52.407 align:middle line:100%,end position:50%,middle\n但依我看还不够\n\nsource-0100\n00:08:54.318 --> 00:08:56.205 align:middle line:100%,end position:50%,middle\n你没列入报告是对的\n\nsource-0101\n00:08:56.406 --> 00:08:57.746 align:middle line:100%,end position:50%,middle\n我知道\n\nsource-0102\n00:09:18.313 --> 00:09:19.974 align:middle line:100%,end position:50%,middle\n（迪奇·佛洛德\n范耶尔企业法务主管，1972年起）\n\nsource-0103\n00:09:20.615 --> 00:09:22.138 align:middle line:100%,end position:50%,middle\n（欢迎您 麦可布隆维斯特！）\n\nsource-0104\n00:09:24.718 --> 00:09:26.208 align:middle line:100%,end position:50%,middle\n（新邮件）\n\nsource-0105\n00:09:31.491 --> 00:09:34.016 align:middle line:100%,end position:50%,middle\n（你能来面试吗？\n回复：温纳斯壮判决？）\n\nsource-0106\n00:09:38.997 --> 00:09:40.089 align:middle line:100%,end position:50%,middle\n（汉斯艾瑞克温纳斯壮）\n\nsource-0107\n00:09:43.035 --> 00:09:44.502 align:middle line:100%,end position:50%,middle\n（温纳斯壮“范耶尔企业”）\n\nsource-0108\n00:09:47.338 --> 00:09:48.327 align:middle line:100%,end position:50%,middle\n（汉斯艾瑞克温纳斯壮）\n\nsource-0109\n00:09:48.539 --> 00:09:50.666 align:middle line:100%,end position:50%,middle\n（范耶尔企业财务部\n1971至1972年）\n\nsource-0110\n00:09:53.719 --> 00:09:56.805 align:middle line:100%,end position:50%,middle\n你该换个律师\n找你老妹\n\nsource-0111\n00:09:56.972 --> 00:09:58.348 align:middle line:100%,end position:50%,middle\n- 她是提过\n- 他拒绝了\n\nsource-0112\n00:09:58.515 --> 00:10:00.100 align:middle line:100%,end position:50%,middle\n- 她也希望他拒绝\n- 公私混在一起\n\nsource-0113\n00:10:00.267 --> 00:10:02.728 align:middle line:100%,end position:50%,middle\n- 从来就不是好主意\n- 我还是会输\n\nsource-0114\n00:10:02.895 --> 00:10:06.273 align:middle line:100%,end position:50%,middle\n温纳斯壮的目标不是麦可\n他是杀鸡儆猴\n\nsource-0115\n00:10:06.440 --> 00:10:09.651 align:middle line:100%,end position:50%,middle\n让媒体和金融监管局\n别再追查\n\nsource-0116\n00:10:09.818 --> 00:10:10.861 align:middle line:100%,end position:50%,middle\n你要振作\n\nsource-0117\n00:10:15.115 --> 00:10:16.158 align:middle line:100%,end position:50%,middle\n爹地\n\nsource-0118\n00:10:16.325 --> 00:10:18.827 align:middle line:100%,end position:50%,middle\n不要担心我\n\nsource-0119\n00:10:18.994 --> 00:10:20.746 align:middle line:100%,end position:50%,middle\n- 妈咪很担心\n- 担心我？\n\nsource-0120\n00:10:21.705 --> 00:10:22.915 align:middle line:100%,end position:50%,middle\n你的钱\n\nsource-0121\n00:11:03.179 --> 00:11:04.306 align:middle line:100%,end position:50%,middle\n（温纳斯壮）\n\nsource-0122\n00:11:28.772 --> 00:11:30.065 align:middle line:100%,end position:50%,middle\n晚安\n\nsource-0123\n00:11:33.110 --> 00:11:35.529 align:middle line:100%,end position:50%,middle\n妮拉？\n你在干嘛？\n\nsource-0124\n00:11:35.696 --> 00:11:36.822 align:middle line:100%,end position:50%,middle\n没有\n\nsource-0125\n00:11:36.989 --> 00:11:38.156 align:middle line:100%,end position:50%,middle\n你是认真的？\n\nsource-0126\n00:11:38.323 --> 00:11:41.910 align:middle line:100%,end position:50%,middle\n我不想谈 我知道你不准\n\nsource-0127\n00:11:42.077 --> 00:11:43.120 align:middle line:100%,end position:50%,middle\n不准什么？\n\nsource-0128\n00:11:43.662 --> 00:11:44.997 align:middle line:100%,end position:50%,middle\n- 妮拉\n- 我加入“生命之光”教会\n\nsource-0129\n00:11:45.163 --> 00:11:46.540 align:middle line:100%,end position:50%,middle\n什么之光？\n\nsource-0130\n00:11:55.549 --> 00:11:56.925 align:middle line:100%,end position:50%,middle\n- 喂？\n<i>- 布隆维斯特先生</i>\n\nsource-0131\n00:11:57.092 --> 00:11:59.219 align:middle line:100%,end position:50%,middle\n- 我是\n<i>- 抱歉圣诞节打扰你</i>\n\nsource-0132\n00:11:59.386 --> 00:12:00.762 align:middle line:100%,end position:50%,middle\n<i>我是佛洛德</i>\n\nsource-0133\n00:12:00.943 --> 00:12:04.887 align:middle line:100%,end position:50%,middle\n亨利范耶尔的律师 你听过他吗？\n\nsource-0134\n00:12:05.088 --> 00:12:06.182 align:middle line:100%,end position:50%,middle\n当然听过\n\nsource-0135\n00:12:06.351 --> 00:12:08.770 align:middle line:100%,end position:50%,middle\n<i>他有事想和你谈</i>\n\nsource-0136\n00:12:08.937 --> 00:12:11.982 align:middle line:100%,end position:50%,middle\n现在不行\n\nsource-0137\n00:12:12.149 --> 00:12:15.235 align:middle line:100%,end position:50%,middle\n<i>我知道 我也该上餐桌了</i>\n\nsource-0138\n00:12:15.402 --> 00:12:17.529 align:middle line:100%,end position:50%,middle\n我指的不是这个\n\nsource-0139\n00:12:17.696 --> 00:12:19.990 align:middle line:100%,end position:50%,middle\n你是说你和温纳斯壮的官司\n\nsource-0140\n00:12:20.157 --> 00:12:22.075 align:middle line:100%,end position:50%,middle\n我们看得津津有味\n\nsource-0141\n00:12:22.242 --> 00:12:23.285 align:middle line:100%,end position:50%,middle\n什么意思？\n\nsource-0142\n00:12:23.452 --> 00:12:26.079 align:middle line:100%,end position:50%,middle\n<i>范耶尔先生也不欣赏他</i>\n\nsource-0143\n00:12:26.246 --> 00:12:28.874 align:middle line:100%,end position:50%,middle\n- 请他打电话给我\n- 他想和你当面谈\n\nsource-0144\n00:12:29.041 --> 00:12:31.543 align:middle line:100%,end position:50%,middle\n如果可以\n\nsource-0145\n00:12:31.710 --> 00:12:33.462 align:middle line:100%,end position:50%,middle\n<i>- 在北部的赫德史塔</i>\n- 我去不了\n\nsource-0146\n00:12:33.629 --> 00:12:36.673 align:middle line:100%,end position:50%,middle\n<i>但范耶尔先生年事已高\n没办法到斯德哥尔摩</i>\n\nsource-0147\n00:12:36.840 --> 00:12:39.092 align:middle line:100%,end position:50%,middle\n请你考虑\n\nsource-0148\n00:12:39.259 --> 00:12:42.012 align:middle line:100%,end position:50%,middle\n<i>这里冬天很美</i>\n\nsource-0149\n00:12:42.179 --> 00:12:46.183 align:middle line:100%,end position:50%,middle\n我再回你电话\n\nsource-0150\n00:12:59.571 --> 00:13:02.282 align:middle line:100%,end position:50%,middle\n我在冰冷的床上醒来\n通常是在自己家\n\nsource-0151\n00:13:02.449 --> 00:13:04.159 align:middle line:100%,end position:50%,middle\n- 抱歉\n- 你在做什么？\n\nsource-0152\n00:13:04.326 --> 00:13:07.287 align:middle line:100%,end position:50%,middle\n- 写新闻稿\n- 关于？\n\nsource-0153\n00:13:10.541 --> 00:13:13.001 align:middle line:100%,end position:50%,middle\n你将接管《千禧年》杂志社\n\nsource-0154\n00:13:13.168 --> 00:13:15.462 align:middle line:100%,end position:50%,middle\n对温纳斯壮带来的困扰\n深表遗憾\n\nsource-0155\n00:13:15.629 --> 00:13:18.632 align:middle line:100%,end position:50%,middle\n- 目前无法联络上我\n- 你要放弃？\n\nsource-0156\n00:13:18.799 --> 00:13:20.092 align:middle line:100%,end position:50%,middle\n是请辞\n\nsource-0157\n00:13:20.259 --> 00:13:22.177 align:middle line:100%,end position:50%,middle\n我讨厌这样\n\nsource-0158\n00:13:38.108 --> 00:13:39.633 align:middle line:100%,end position:50%,middle\n（赫德史塔）\n\nsource-0159\n00:13:58.422 --> 00:14:00.674 align:middle line:100%,end position:50%,middle\n- 第一次来赫德史塔？\n- 也是最后一次\n\nsource-0160\n00:14:00.841 --> 00:14:03.343 align:middle line:100%,end position:50%,middle\n别这么说 这里春天很美\n\nsource-0161\n00:14:03.510 --> 00:14:06.263 align:middle line:100%,end position:50%,middle\n我以为你说冬天\n\nsource-0162\n00:14:06.430 --> 00:14:08.390 align:middle line:100%,end position:50%,middle\n但这天气实在反常\n\nsource-0163\n00:14:08.557 --> 00:14:11.101 align:middle line:100%,end position:50%,middle\n我搭四点半的火车回去\n\nsource-0164\n00:14:11.268 --> 00:14:13.312 align:middle line:100%,end position:50%,middle\n如果没下大雪\n\nsource-0165\n00:14:13.478 --> 00:14:14.563 align:middle line:100%,end position:50%,middle\n开玩笑的\n\nsource-0166\n00:14:14.730 --> 00:14:17.566 align:middle line:100%,end position:50%,middle\n你随时都可以走\n\nsource-0167\n00:14:57.481 --> 00:14:58.565 align:middle line:100%,end position:50%,middle\n欢迎\n\nsource-0168\n00:14:58.732 --> 00:14:59.775 align:middle line:100%,end position:50%,middle\n进屋里来\n\nsource-0169\n00:15:00.776 --> 00:15:02.528 align:middle line:100%,end position:50%,middle\n里面很温暖\n\nsource-0170\n00:15:02.694 --> 00:15:04.279 align:middle line:100%,end position:50%,middle\n您好\n\nsource-0171\n00:15:10.452 --> 00:15:11.954 align:middle line:100%,end position:50%,middle\n所以…\n\nsource-0172\n00:15:13.247 --> 00:15:14.623 align:middle line:100%,end position:50%,middle\n你知道我吗？\n\nsource-0173\n00:15:15.207 --> 00:15:18.335 align:middle line:100%,end position:50%,middle\n您曾掌管国内最大的企业之一\n\nsource-0174\n00:15:18.502 --> 00:15:20.921 align:middle line:100%,end position:50%,middle\n- 对 “曾经”\n- 我不是那个意思\n\nsource-0175\n00:15:21.088 --> 00:15:22.881 align:middle line:100%,end position:50%,middle\n- 我需要留下吗？\n- 不用\n\nsource-0176\n00:15:23.376 --> 00:15:26.555 align:middle line:100%,end position:50%,middle\n我祖父锻造铁轨\n\nsource-0177\n00:15:26.763 --> 00:15:28.929 align:middle line:100%,end position:50%,middle\n你才能坐四点半的火车回家\n\nsource-0178\n00:15:29.555 --> 00:15:31.557 align:middle line:100%,end position:50%,middle\n我们的家族连起整个国家\n\nsource-0179\n00:15:31.723 --> 00:15:36.436 align:middle line:100%,end position:50%,middle\n我们的制钢和伐木事业\n让瑞典现代化\n\nsource-0180\n00:15:36.603 --> 00:15:39.857 align:middle line:100%,end position:50%,middle\n你猜我们现在最赚钱的是什么？\n\nsource-0181\n00:15:40.023 --> 00:15:41.316 align:middle line:100%,end position:50%,middle\n肥料\n\nsource-0182\n00:15:41.483 --> 00:15:44.194 align:middle line:100%,end position:50%,middle\n我不是请你来讨论公司的衰退\n\nsource-0183\n00:15:44.361 --> 00:15:46.864 align:middle line:100%,end position:50%,middle\n但我对清算旧账念念不忘\n\nsource-0184\n00:15:47.030 --> 00:15:49.533 align:middle line:100%,end position:50%,middle\n我来日不多 需要你帮忙\n\nsource-0185\n00:15:49.700 --> 00:15:51.076 align:middle line:100%,end position:50%,middle\n帮什么？\n\nsource-0186\n00:15:51.243 --> 00:15:53.745 align:middle line:100%,end position:50%,middle\n对外说是帮我写回忆录\n\nsource-0187\n00:15:53.912 --> 00:15:58.458 align:middle line:100%,end position:50%,middle\n但你真正要做的\n\nsource-0188\n00:15:58.625 --> 00:16:02.713 align:middle line:100%,end position:50%,middle\n是你擅长的调查工作\n\nsource-0189\n00:16:02.880 --> 00:16:05.257 align:middle line:100%,end position:50%,middle\n虽然你最近的案子失利\n\nsource-0190\n00:16:05.424 --> 00:16:09.803 align:middle line:100%,end position:50%,middle\n你将调查窃贼、守财奴和恶霸\n\nsource-0191\n00:16:09.970 --> 00:16:15.559 align:middle line:100%,end position:50%,middle\n一群你见过最可憎的恶人\n\nsource-0192\n00:16:15.726 --> 00:16:17.186 align:middle line:100%,end position:50%,middle\n我的家族\n\nsource-0193\n00:16:24.193 --> 00:16:27.571 align:middle line:100%,end position:50%,middle\n要坐吗？我可以清出个地方\n\nsource-0194\n00:16:27.738 --> 00:16:29.865 align:middle line:100%,end position:50%,middle\n- 这你做的？\n- 钱呢？\n\nsource-0195\n00:16:33.452 --> 00:16:37.789 align:middle line:100%,end position:50%,middle\n我领救济，不做慈善\n这些钱不够\n\nsource-0196\n00:16:49.134 --> 00:16:50.469 align:middle line:100%,end position:50%,middle\n你忘了说谢谢\n\nsource-0197\n00:16:53.639 --> 00:16:54.932 align:middle line:100%,end position:50%,middle\n<i>这是海莉</i>\n\nsource-0198\n00:16:56.517 --> 00:16:59.311 align:middle line:100%,end position:50%,middle\n我哥哥理查的孙女\n\nsource-0199\n00:16:59.853 --> 00:17:02.814 align:middle line:100%,end position:50%,middle\n理查是纳粹狂热份子\n\nsource-0200\n00:17:03.190 --> 00:17:08.487 align:middle line:100%,end position:50%,middle\n十七岁就加入\n国家社会主义自由联盟\n\nsource-0201\n00:17:08.654 --> 00:17:13.242 align:middle line:100%,end position:50%,middle\n好笑吧？\n法西斯喜欢滥用“自由”一词\n\nsource-0202\n00:17:16.161 --> 00:17:19.122 align:middle line:100%,end position:50%,middle\n四点半的火车 我知道\n\nsource-0203\n00:17:19.289 --> 00:17:24.127 align:middle line:100%,end position:50%,middle\n理查1940年为纳粹事业殉身\n\nsource-0204\n00:17:24.294 --> 00:17:26.922 align:middle line:100%,end position:50%,middle\n他错过二次大战\n\nsource-0205\n00:17:27.297 --> 00:17:31.468 align:middle line:100%,end position:50%,middle\n但可没错过经常殴打妻子\n玛格丽塔的机会\n\nsource-0206\n00:17:31.635 --> 00:17:33.303 align:middle line:100%,end position:50%,middle\n还有他们的儿子 戈弗里\n\nsource-0207\n00:17:33.470 --> 00:17:35.264 align:middle line:100%,end position:50%,middle\n戈弗里是海莉的父亲\n\nsource-0208\n00:17:35.430 --> 00:17:38.141 align:middle line:100%,end position:50%,middle\n人称“风流浪子”\n\nsource-0209\n00:17:38.308 --> 00:17:40.811 align:middle line:100%,end position:50%,middle\n- 现在还是\n- 是吗？\n\nsource-0210\n00:17:40.978 --> 00:17:43.438 align:middle line:100%,end position:50%,middle\n他有魅力 女人缘好 是个酒鬼\n\nsource-0211\n00:17:43.605 --> 00:17:46.608 align:middle line:100%,end position:50%,middle\n天生的业务员\n\nsource-0212\n00:17:46.775 --> 00:17:49.444 align:middle line:100%,end position:50%,middle\n他负责到处旅行\n吃喝玩乐应酬客户\n\nsource-0213\n00:17:49.611 --> 00:17:51.947 align:middle line:100%,end position:50%,middle\n- 总得有人做这事\n- 是的\n\nsource-0214\n00:17:52.114 --> 00:17:55.033 align:middle line:100%,end position:50%,middle\n他1965年去世\n\nsource-0215\n00:17:55.200 --> 00:17:57.286 align:middle line:100%,end position:50%,middle\n酒醉 意外溺死在这里\n\nsource-0216\n00:17:57.452 --> 00:18:01.874 align:middle line:100%,end position:50%,middle\n他太太伊莎贝拉不是个尽责母亲\n\nsource-0217\n00:18:02.040 --> 00:18:04.418 align:middle line:100%,end position:50%,middle\n在他死后 更不管孩子\n\nsource-0218\n00:18:04.585 --> 00:18:07.254 align:middle line:100%,end position:50%,middle\n我从那时开始照顾这两个孩子\n\nsource-0219\n00:18:07.421 --> 00:18:10.424 align:middle line:100%,end position:50%,middle\n马丁在我退休后接管范耶尔企业\n\nsource-0220\n00:18:10.633 --> 00:18:12.179 align:middle line:100%,end position:50%,middle\n没错 我上网查过他\n\nsource-0221\n00:18:12.383 --> 00:18:13.476 align:middle line:100%,end position:50%,middle\n还有海莉\n\nsource-0222\n00:18:16.180 --> 00:18:18.724 align:middle line:100%,end position:50%,middle\n她聪明又有求知欲\n\nsource-0223\n00:18:19.266 --> 00:18:22.311 align:middle line:100%,end position:50%,middle\n这两点让人前途无量\n\nsource-0224\n00:18:22.811 --> 00:18:25.772 align:middle line:100%,end position:50%,middle\n- 还很漂亮\n- 是的\n\nsource-0225\n00:18:26.773 --> 00:18:28.817 align:middle line:100%,end position:50%,middle\n她后来怎么了？\n\nsource-0226\n00:18:28.984 --> 00:18:31.361 align:middle line:100%,end position:50%,middle\n家族里有人谋杀海莉\n\nsource-0227\n00:18:32.070 --> 00:18:34.031 align:middle line:100%,end position:50%,middle\n并在过去四十年来\n\nsource-0228\n00:18:34.198 --> 00:18:37.284 align:middle line:100%,end position:50%,middle\n企图把我逼疯\n\nsource-0229\n00:18:38.660 --> 00:18:41.788 align:middle line:100%,end position:50%,middle\n<i>事情发生在1966年9月24日</i>\n\nsource-0230\n00:18:41.955 --> 00:18:43.707 align:middle line:100%,end position:50%,middle\n星期六\n\nsource-0231\n00:18:43.874 --> 00:18:45.626 align:middle line:100%,end position:50%,middle\n海莉当时十六岁\n\nsource-0232\n00:18:45.792 --> 00:18:46.877 align:middle line:100%,end position:50%,middle\n我的哥哥们\n\nsource-0233\n00:18:47.044 --> 00:18:49.755 align:middle line:100%,end position:50%,middle\n<i>和他们的太太、孩子、孙辈</i>\n\nsource-0234\n00:18:49.922 --> 00:18:51.256 align:middle line:100%,end position:50%,middle\n<i>都齐聚在此</i>\n\nsource-0235\n00:18:51.423 --> 00:18:54.510 align:middle line:100%,end position:50%,middle\n<i>参加烦人的家族年度会议和聚餐</i>\n\nsource-0236\n00:18:54.676 --> 00:18:58.597 align:middle line:100%,end position:50%,middle\n<i>那天游艇俱乐部\n也举办秋季游行活动</i>\n\nsource-0237\n00:18:58.764 --> 00:19:01.934 align:middle line:100%,end position:50%,middle\n<i>海莉和一两个朋友进城看游行</i>\n\nsource-0238\n00:19:02.100 --> 00:19:05.229 align:middle line:100%,end position:50%,middle\n两点刚过回到岛上\n\nsource-0239\n00:19:05.395 --> 00:19:09.274 align:middle line:100%,end position:50%,middle\n<i>她来找我 有话跟我说</i>\n\nsource-0240\n00:19:09.441 --> 00:19:11.652 align:middle line:100%,end position:50%,middle\n我真的不记得当时在做什么\n\nsource-0241\n00:19:11.818 --> 00:19:13.695 align:middle line:100%,end position:50%,middle\n竟会觉得比海莉重要\n\nsource-0242\n00:19:13.862 --> 00:19:16.281 align:middle line:100%,end position:50%,middle\n<i>我请她等我几分钟</i>\n\nsource-0243\n00:19:18.075 --> 00:19:22.871 align:middle line:100%,end position:50%,middle\n就在那几分钟发生了一件意外\n\nsource-0244\n00:19:25.666 --> 00:19:29.127 align:middle line:100%,end position:50%,middle\n<i>这起意外和海莉毫无关系</i>\n\nsource-0245\n00:19:29.294 --> 00:19:31.088 align:middle line:100%,end position:50%,middle\n却扮演关键角色\n\nsource-0246\n00:19:31.880 --> 00:19:34.591 align:middle line:100%,end position:50%,middle\n<i>当时一片混乱 大家都赶到现场</i>\n\nsource-0247\n00:19:34.758 --> 00:19:37.094 align:middle line:100%,end position:50%,middle\n<i>警察、救护车、消防队</i>\n\nsource-0248\n00:19:37.261 --> 00:19:41.223 align:middle line:100%,end position:50%,middle\n<i>城里的记者、摄影师、看热闹的</i>\n\nsource-0249\n00:19:41.390 --> 00:19:45.853 align:middle line:100%,end position:50%,middle\n<i>岛上的家人也都赶到桥边</i>\n\nsource-0250\n00:19:46.019 --> 00:19:47.437 align:middle line:100%,end position:50%,middle\n<i>那辆车的司机</i>\n\nsource-0251\n00:19:47.604 --> 00:19:49.231 align:middle line:100%,end position:50%,middle\n名叫阿朗松\n\nsource-0252\n00:19:49.398 --> 00:19:51.692 align:middle line:100%,end position:50%,middle\n<i>他被困在车里伤得很重</i>\n\nsource-0253\n00:19:51.859 --> 00:19:54.778 align:middle line:100%,end position:50%,middle\n<i>我们拼命徒手把他救出来</i>\n\nsource-0254\n00:19:54.945 --> 00:19:57.281 align:middle line:100%,end position:50%,middle\n<i>因为金属工具可能引起火花</i>\n\nsource-0255\n00:19:58.240 --> 00:20:02.452 align:middle line:100%,end position:50%,middle\n<i>意外发生后一小时\n海莉那时人在厨房</i>\n\nsource-0256\n00:20:02.619 --> 00:20:04.705 align:middle line:100%,end position:50%,middle\n安娜亲眼看见的\n\nsource-0257\n00:20:08.876 --> 00:20:13.714 align:middle line:100%,end position:50%,middle\n<i>终于把阿朗松从车里救出\n送到了医院</i>\n\nsource-0258\n00:20:14.298 --> 00:20:17.509 align:middle line:100%,end position:50%,middle\n<i>我们才从桥的这边</i>\n\nsource-0259\n00:20:17.676 --> 00:20:20.637 align:middle line:100%,end position:50%,middle\n<i>慢慢走回屋子</i>\n\nsource-0260\n00:20:22.556 --> 00:20:24.808 align:middle line:100%,end position:50%,middle\n<i>太阳落山，混乱也平息了</i>\n\nsource-0261\n00:20:25.225 --> 00:20:27.394 align:middle line:100%,end position:50%,middle\n<i>我们坐下吃晚饭</i>\n\nsource-0262\n00:20:27.561 --> 00:20:29.104 align:middle line:100%,end position:50%,middle\n<i>我才发现</i>\n\nsource-0263\n00:20:29.646 --> 00:20:31.064 align:middle line:100%,end position:50%,middle\n<i>海莉不见了</i>\n\nsource-0264\n00:20:32.357 --> 00:20:34.985 align:middle line:100%,end position:50%,middle\n<i>隔天早上也不见踪影</i>\n\nsource-0265\n00:20:35.152 --> 00:20:36.195 align:middle line:100%,end position:50%,middle\n<i>第三天也是</i>\n\nsource-0266\n00:20:36.987 --> 00:20:38.322 align:middle line:100%,end position:50%,middle\n人间蒸发了四十年\n\nsource-0267\n00:20:42.034 --> 00:20:43.827 align:middle line:100%,end position:50%,middle\n<i>她那时到底想说什么？</i>\n\nsource-0268\n00:20:43.994 --> 00:20:47.247 align:middle line:100%,end position:50%,middle\n我为什么不听她说？\n\nsource-0269\n00:20:47.414 --> 00:20:50.792 align:middle line:100%,end position:50%,middle\n- 她有可能离家出走吗？\n- 不可能 一定会被发现\n\nsource-0270\n00:20:50.962 --> 00:20:52.477 align:middle line:100%,end position:50%,middle\n消防员整晚都在桥上\n\nsource-0271\n00:20:52.702 --> 00:20:54.471 align:middle line:100%,end position:50%,middle\n试图抽光车子的汽油\n\nsource-0272\n00:20:54.671 --> 00:20:57.799 align:middle line:100%,end position:50%,middle\n<i>没人游泳或搭船到对岸</i>\n\nsource-0273\n00:20:57.966 --> 00:21:00.636 align:middle line:100%,end position:50%,middle\n所有船到星期天都没动过\n\nsource-0274\n00:21:00.802 --> 00:21:03.430 align:middle line:100%,end position:50%,middle\n相信我 我检查过了\n\nsource-0275\n00:21:05.432 --> 00:21:07.392 align:middle line:100%,end position:50%,middle\n落水淹死？\n\nsource-0276\n00:21:07.559 --> 00:21:12.314 align:middle line:100%,end position:50%,middle\n这里水流不强\n任何人掉落水中都会被发现\n\nsource-0277\n00:21:12.481 --> 00:21:13.774 align:middle line:100%,end position:50%,middle\n就像她父亲那次\n\nNATIVE-001\n00:21:13.941 --> 00:21:18.904 align:middle line:100%,end position:50%,middle\n他在前一年溺水时\n尸体漂出不超过10米就被找到了\n\nsource-0280\n00:21:19.071 --> 00:21:22.199 align:middle line:100%,end position:50%,middle\n海莉是被谋杀的\n\nsource-0281\n00:21:22.366 --> 00:21:24.993 align:middle line:100%,end position:50%,middle\n那天在岛上的人\n\nsource-0282\n00:21:25.160 --> 00:21:27.162 align:middle line:100%,end position:50%,middle\n因为他知道\n\nsource-0283\n00:21:27.329 --> 00:21:31.750 align:middle line:100%,end position:50%,middle\n海莉每年送我压花当生日礼物\n\nsource-0284\n00:21:33.752 --> 00:21:35.838 align:middle line:100%,end position:50%,middle\n那些是海莉送的\n\nsource-0285\n00:21:36.338 --> 00:21:39.675 align:middle line:100%,end position:50%,middle\n其他都是凶手寄来的\n\nsource-0286\n00:21:52.741 --> 00:21:53.991 align:middle line:100%,end position:50%,middle\n谁知道你还收到压花？\n\nsource-0287\n00:21:54.196 --> 00:21:57.622 align:middle line:100%,end position:50%,middle\n我、警察还有那个凶手\n\nsource-0288\n00:21:57.985 --> 00:21:59.027 align:middle line:100%,end position:50%,middle\n还有你\n\nsource-0289\n00:22:04.999 --> 00:22:07.364 align:middle line:100%,end position:50%,middle\n（赫德史塔）\n\nsource-0290\n00:22:07.995 --> 00:22:10.539 align:middle line:100%,end position:50%,middle\n<i>警方停止调查后</i>\n\nsource-0291\n00:22:10.706 --> 00:22:13.500 align:middle line:100%,end position:50%,middle\n<i>我继续追查及研究所有资料</i>\n\nsource-0292\n00:22:14.001 --> 00:22:17.880 align:middle line:100%,end position:50%,middle\n花了半辈子思索那一天发生的事\n\nsource-0293\n00:22:18.046 --> 00:22:20.215 align:middle line:100%,end position:50%,middle\n我了解你的心情\n\nsource-0294\n00:22:20.382 --> 00:22:23.218 align:middle line:100%,end position:50%,middle\n但你要我帮的忙\n根本是浪费钱\n\nsource-0295\n00:22:23.385 --> 00:22:26.513 align:middle line:100%,end position:50%,middle\n- 我们还没谈到报酬\n- 不需要谈\n\nsource-0296\n00:22:26.680 --> 00:22:28.140 align:middle line:100%,end position:50%,middle\n谢谢\n\nsource-0297\n00:22:28.307 --> 00:22:31.935 align:middle line:100%,end position:50%,middle\n我不可能解开四十年的无解谜团\n\nsource-0298\n00:22:32.102 --> 00:22:35.898 align:middle line:100%,end position:50%,middle\n很难说\n你有锲而不舍的调查精神\n\nsource-0299\n00:22:36.643 --> 00:22:38.013 align:middle line:100%,end position:50%,middle\n这是我的提议\n\nsource-0300\n00:22:38.217 --> 00:22:39.943 align:middle line:100%,end position:50%,middle\n你来岛上住一段时间\n\nsource-0301\n00:22:40.110 --> 00:22:43.280 align:middle line:100%,end position:50%,middle\n我在岸边有一间舒适小屋\n\nsource-0302\n00:22:43.447 --> 00:22:45.157 align:middle line:100%,end position:50%,middle\n你研究我给你的资料\n\nsource-0303\n00:22:45.324 --> 00:22:47.868 align:middle line:100%,end position:50%,middle\n看能不能找到我漏掉的线索\n\nsource-0304\n00:22:48.035 --> 00:22:51.079 align:middle line:100%,end position:50%,middle\n你要我放下自己的生活和工作\n\nsource-0305\n00:22:51.246 --> 00:22:53.332 align:middle line:100%,end position:50%,middle\n当作是放长假吧\n\nsource-0306\n00:22:53.498 --> 00:22:58.003 align:middle line:100%,end position:50%,middle\n正好可以避开风头和敌人\n\nsource-0307\n00:22:58.170 --> 00:23:00.714 align:middle line:100%,end position:50%,middle\n酬劳是你现在薪水的双倍\n\nsource-0308\n00:23:00.881 --> 00:23:02.591 align:middle line:100%,end position:50%,middle\n直到你完成为止\n\nsource-0309\n00:23:02.758 --> 00:23:05.594 align:middle line:100%,end position:50%,middle\n- 如果解开谜底再加倍\n- 范耶尔先生\n\nsource-0310\n00:23:05.761 --> 00:23:07.930 align:middle line:100%,end position:50%,middle\n我还没讲完 还有个好处要给你\n\nsource-0311\n00:23:08.096 --> 00:23:10.224 align:middle line:100%,end position:50%,middle\n虽然你的议价能力很差\n\nsource-0312\n00:23:10.390 --> 00:23:12.976 align:middle line:100%,end position:50%,middle\n这却是你最想要的东西\n\nsource-0313\n00:23:13.143 --> 00:23:16.563 align:middle line:100%,end position:50%,middle\n多少钱也买不到，我可以给你\n\nsource-0314\n00:23:17.189 --> 00:23:20.150 align:middle line:100%,end position:50%,middle\n汉斯·艾瑞克·温纳斯壮\n\nsource-0315\n00:23:21.026 --> 00:23:23.237 align:middle line:100%,end position:50%,middle\n他以前替我工作\n\nsource-0316\n00:23:23.403 --> 00:23:27.241 align:middle line:100%,end position:50%,middle\n我从一开始就很“注意”他\n\nsource-0317\n00:23:30.118 --> 00:23:31.620 align:middle line:100%,end position:50%,middle\n你的指控是对的\n\nsource-0318\n00:23:32.412 --> 00:23:34.623 align:middle line:100%,end position:50%,middle\n只是无法证明\n\nsource-0319\n00:24:05.070 --> 00:24:08.699 align:middle line:100%,end position:50%,middle\n《千禧年》都快倒了\n你居然去写回忆录\n\nsource-0320\n00:24:08.866 --> 00:24:12.494 align:middle line:100%,end position:50%,middle\n- 你炒我鱿鱼 我得找事做\n- 是你炒了自己\n\nsource-0321\n00:24:14.654 --> 00:24:16.690 align:middle line:100%,end position:50%,middle\n你到北极去怎么帮得了我？\n\nsource-0322\n00:24:16.898 --> 00:24:19.238 align:middle line:100%,end position:50%,middle\n你知道别人会怎么想吗？\n\nsource-0323\n00:24:19.418 --> 00:24:21.545 align:middle line:100%,end position:50%,middle\n我输了所以逃走\n\nsource-0324\n00:24:21.712 --> 00:24:24.590 align:middle line:100%,end position:50%,middle\n这就是温纳斯壮要的\n\nsource-0325\n00:24:24.756 --> 00:24:27.968 align:middle line:100%,end position:50%,middle\n只要让他以为我们闹翻了\n他就会满意\n\nsource-0326\n00:24:28.135 --> 00:24:29.553 align:middle line:100%,end position:50%,middle\n我们确实闹翻了\n\nsource-0327\n00:24:29.720 --> 00:24:32.389 align:middle line:100%,end position:50%,middle\n杂志社倒闭前 他不会收手\n\nsource-0328\n00:24:32.848 --> 00:24:36.852 align:middle line:100%,end position:50%,middle\n- 你丢下我独自作战\n- 火车四个小时就到了\n\nsource-0329\n00:24:41.940 --> 00:24:44.443 align:middle line:100%,end position:50%,middle\n不是北极\n\nsource-0330\n00:24:52.677 --> 00:24:54.200 align:middle line:100%,end position:50%,middle\n（巴比费雪\n我六十个难忘的游戏）\n\nsource-0331\n00:25:25.859 --> 00:25:27.444 align:middle line:100%,end position:50%,middle\n嘿\n\nsource-0332\n00:26:24.835 --> 00:26:28.297 align:middle line:100%,end position:50%,middle\n<i>线路忙线中 请稍后再试</i>\n\nsource-0333\n00:26:38.640 --> 00:26:42.102 align:middle line:100%,end position:50%,middle\n<i>线路忙线中 请稍后再试</i>\n\nsource-0334\n00:26:48.233 --> 00:26:49.776 align:middle line:100%,end position:50%,middle\n干嘛？\n\nsource-0335\n00:26:50.152 --> 00:26:51.445 align:middle line:100%,end position:50%,middle\n要牛奶？\n\nsource-0336\n00:27:10.297 --> 00:27:13.842 align:middle line:100%,end position:50%,middle\n<i>线路忙线中 请稍后再试</i>\n\nsource-0337\n00:27:15.802 --> 00:27:18.347 align:middle line:100%,end position:50%,middle\n还有这些\n\nsource-0338\n00:27:47.502 --> 00:27:48.934 align:middle line:100%,end position:50%,middle\n（克特冯内果）\n\nsource-0339\n00:27:55.968 --> 00:27:59.304 align:middle line:100%,end position:50%,middle\n- 你是帕姆格伦先生的女儿？\n- 我是受监护人，他没有女儿\n\nsource-0340\n00:28:01.265 --> 00:28:02.891 align:middle line:100%,end position:50%,middle\n拜托\n\nsource-0341\n00:28:04.142 --> 00:28:06.812 align:middle line:100%,end position:50%,middle\n<i>他的脑部严重出血</i>\n\nsource-0342\n00:28:06.979 --> 00:28:10.524 align:middle line:100%,end position:50%,middle\n<i>可能是跌倒所致\n或是中风导致他摔倒</i>\n\nsource-0343\n00:28:10.691 --> 00:28:12.651 align:middle line:100%,end position:50%,middle\n<i>血压还是太高</i>\n\nsource-0344\n00:28:12.818 --> 00:28:15.779 align:middle line:100%,end position:50%,middle\n<i>有可能恢复意识但不敢保证</i>\n\nsource-0345\n00:28:15.946 --> 00:28:18.240 align:middle line:100%,end position:50%,middle\n<i>就算恢复意识</i>\n\nsource-0346\n00:28:18.407 --> 00:28:21.201 align:middle line:100%,end position:50%,middle\n<i>也可能有神经损害</i>\n\nsource-0347\n00:28:42.688 --> 00:28:44.449 align:middle line:100%,end position:50%,middle\n天啊\n\nsource-0348\n00:28:49.813 --> 00:28:51.523 align:middle line:100%,end position:50%,middle\n我是根纳\n\nsource-0349\n00:28:52.733 --> 00:28:53.734 align:middle line:100%,end position:50%,middle\n管理员\n\nsource-0350\n00:28:53.901 --> 00:28:56.195 align:middle line:100%,end position:50%,middle\n- 请进\n- 好\n\nsource-0351\n00:29:00.824 --> 00:29:03.452 align:middle line:100%,end position:50%,middle\n- 放那里吗？\n- 好\n\nsource-0352\n00:29:11.543 --> 00:29:13.253 align:middle line:100%,end position:50%,middle\n你是个作家\n\nsource-0353\n00:29:13.420 --> 00:29:17.508 align:middle line:100%,end position:50%,middle\n我在帮范耶尔先生写传记\n\nsource-0354\n00:29:19.384 --> 00:29:22.596 align:middle line:100%,end position:50%,middle\n- 我在电视上看过你\n- 真不幸\n\nsource-0355\n00:29:22.763 --> 00:29:24.640 align:middle line:100%,end position:50%,middle\n你惹上麻烦\n\nsource-0356\n00:29:25.474 --> 00:29:28.018 align:middle line:100%,end position:50%,middle\n- 还好不用坐牢\n- 幸好\n\nsource-0357\n00:29:28.769 --> 00:29:31.188 align:middle line:100%,end position:50%,middle\n赔了很多钱吧？\n\nsource-0358\n00:29:32.981 --> 00:29:34.525 align:middle line:100%,end position:50%,middle\n搞定\n\nsource-0359\n00:29:37.653 --> 00:29:42.282 align:middle line:100%,end position:50%,middle\n岛上的土地是我们家族所有\n\nsource-0360\n00:29:43.742 --> 00:29:48.956 align:middle line:100%,end position:50%,middle\n离你小屋最近的是我哥哈洛德\n\nsource-0361\n00:29:49.873 --> 00:29:52.209 align:middle line:100%,end position:50%,middle\n又一个纳粹 你相信吗？\n\nsource-0362\n00:29:52.376 --> 00:29:53.919 align:middle line:100%,end position:50%,middle\n一家出两个纳粹\n\nsource-0363\n00:29:54.086 --> 00:29:58.257 align:middle line:100%,end position:50%,middle\n说好听点 他相当讨人厌\n\nsource-0364\n00:29:58.423 --> 00:30:01.844 align:middle line:100%,end position:50%,middle\n但你大概不会见到他\n他很孤僻\n\nsource-0365\n00:30:02.010 --> 00:30:04.805 align:middle line:100%,end position:50%,middle\n- 那天他也在场？\n- 没错 他在\n\nsource-0366\n00:30:04.972 --> 00:30:08.475 align:middle line:100%,end position:50%,middle\n他女儿西西莉亚住在那里\n\nsource-0367\n00:30:08.976 --> 00:30:10.352 align:middle line:100%,end position:50%,middle\n他们彼此不说话\n\nsource-0368\n00:30:10.519 --> 00:30:13.105 align:middle line:100%,end position:50%,middle\n这岛上有人互相说话吗？\n\nsource-0369\n00:30:13.272 --> 00:30:15.899 align:middle line:100%,end position:50%,middle\n海莉的母亲伊莎贝拉住在那里\n\nsource-0370\n00:30:16.066 --> 00:30:19.945 align:middle line:100%,end position:50%,middle\n她会跟哈洛德说话\n这也是我不理她的原因之一\n\nsource-0371\n00:30:20.112 --> 00:30:21.196 align:middle line:100%,end position:50%,middle\n了解\n\nsource-0372\n00:30:21.363 --> 00:30:24.533 align:middle line:100%,end position:50%,middle\n西西莉亚的哥哥毕耶住在那里\n\nsource-0373\n00:30:25.100 --> 00:30:26.357 align:middle line:100%,end position:50%,middle\n他不跟谁说话？\n\nsource-0374\n00:30:26.568 --> 00:30:27.687 align:middle line:100%,end position:50%,middle\n大概是你\n\nsource-0375\n00:30:27.870 --> 00:30:31.415 align:middle line:100%,end position:50%,middle\n你也不会想理他\n他跟他父亲一样讨人厌\n\nsource-0376\n00:30:31.582 --> 00:30:34.001 align:middle line:100%,end position:50%,middle\n我已经记不得谁是谁了\n\nsource-0377\n00:30:34.168 --> 00:30:36.461 align:middle line:100%,end position:50%,middle\n你会宁可一个也不认识\n\nsource-0378\n00:30:36.628 --> 00:30:40.591 align:middle line:100%,end position:50%,middle\n你很快就会认清我们\n为此我先致歉\n\nsource-0379\n00:30:40.757 --> 00:30:45.929 align:middle line:100%,end position:50%,middle\n马丁住那 他是海莉的哥哥\n\nsource-0380\n00:30:46.096 --> 00:30:48.849 align:middle line:100%,end position:50%,middle\n- 谁跟他说话？\n- 我\n\nsource-0381\n00:30:49.016 --> 00:30:52.269 align:middle line:100%,end position:50%,middle\n他现在负责整个企业\n\nsource-0382\n00:30:53.896 --> 00:30:56.899 align:middle line:100%,end position:50%,middle\n大概是根纳在猎晚餐\n\nsource-0383\n00:30:57.093 --> 00:30:58.349 align:middle line:100%,end position:50%,middle\n我刚见过他\n\nsource-0384\n00:30:58.546 --> 00:31:01.994 align:middle line:100%,end position:50%,middle\n海莉失踪时 根纳十九岁\n\nsource-0385\n00:31:02.696 --> 00:31:04.448 align:middle line:100%,end position:50%,middle\n他住在那里\n\nsource-0386\n00:31:06.450 --> 00:31:08.160 align:middle line:100%,end position:50%,middle\n- 你就住那边\n- 抱歉？\n\nsource-0387\n00:31:08.327 --> 00:31:09.995 align:middle line:100%,end position:50%,middle\n你的房子\n\nsource-0388\n00:31:12.080 --> 00:31:14.208 align:middle line:100%,end position:50%,middle\n是的\n\nsource-0389\n00:31:14.833 --> 00:31:16.585 align:middle line:100%,end position:50%,middle\n没错 我住这\n\nsource-0390\n00:31:16.752 --> 00:31:18.378 align:middle line:100%,end position:50%,middle\n雇用侦探的人\n\nsource-0391\n00:31:18.545 --> 00:31:21.798 align:middle line:100%,end position:50%,middle\n也该一直留在嫌疑人名单上\n\nsource-0392\n00:31:26.185 --> 00:31:28.178 align:middle line:100%,end position:50%,middle\n（马丁 范耶尔企业现任总裁）\n\nsource-0393\n00:31:29.158 --> 00:31:30.820 align:middle line:100%,end position:50%,middle\n（亨利 范耶尔企业前任总裁）\n\nsource-0394\n00:31:31.027 --> 00:31:32.017 align:middle line:100%,end position:50%,middle\n（生意上的敌人？）\n\nsource-0395\n00:31:35.602 --> 00:31:37.697 align:middle line:100%,end position:50%,middle\n（游行街道）\n\nsource-0396\n00:31:37.907 --> 00:31:40.036 align:middle line:100%,end position:50%,middle\n（意外、桥）\n\nsource-0397\n00:31:51.499 --> 00:31:54.494 align:middle line:100%,end position:50%,middle\n（晚上9点45分\n莫瑞尔警探由电话得知状况）\n\nsource-0398\n00:32:06.761 --> 00:32:10.427 align:middle line:100%,end position:50%,middle\n（莫瑞尔警探搭巡逻艇至事发地点\n晚上10点19分 海德比岛）\n\nsource-0399\n00:32:14.476 --> 00:32:16.103 align:middle line:100%,end position:50%,middle\n海莉母亲\n\nsource-0400\n00:32:17.177 --> 00:32:18.699 align:middle line:100%,end position:50%,middle\n（母亲酒醉）\n\nsource-0401\n00:32:19.843 --> 00:32:22.569 align:middle line:100%,end position:50%,middle\n（晚上10点20分\n莫瑞尔检查海莉房间）\n\nsource-0402\n00:32:30.274 --> 00:32:31.706 align:middle line:100%,end position:50%,middle\n（个人物品 包括梳子\n\nsource-0403\n00:32:31.908 --> 00:32:34.100 align:middle line:100%,end position:50%,middle\n镜子、手帕、钱包、电话簿都在）\n\nsource-0404\n00:32:38.406 --> 00:32:41.530 align:middle line:100%,end position:50%,middle\n（约十点半时 莫瑞尔\n开始面谈范耶尔家族成员）\n\nsource-0405\n00:32:44.923 --> 00:32:47.217 align:middle line:100%,end position:50%,middle\n可搜寻怎么办？求你了\n\nsource-0406\n00:32:48.302 --> 00:32:51.305 align:middle line:100%,end position:50%,middle\n拜托你\n我求你 拜托\n\nsource-0407\n00:32:52.428 --> 00:32:56.029 align:middle line:100%,end position:50%,middle\n（晚上11点15分 莫瑞尔指示巡逻艇\n和两队自愿搜索队开始搜寻）\n\nsource-0408\n00:33:03.524 --> 00:33:07.226 align:middle line:100%,end position:50%,middle\n（早上6点40分\n巡逻小队与自愿搜索队集合）\n\nsource-0409\n00:33:22.586 --> 00:33:26.089 align:middle line:100%,end position:50%,middle\n<i>没找到尸体 我并不意外</i>\n\nsource-0410\n00:33:26.256 --> 00:33:29.176 align:middle line:100%,end position:50%,middle\n<i>不可能把整座岛翻个遍</i>\n\nsource-0411\n00:33:30.427 --> 00:33:32.679 align:middle line:100%,end position:50%,middle\n但我也找不到动机\n\nsource-0412\n00:33:32.846 --> 00:33:35.516 align:middle line:100%,end position:50%,middle\n临时起意？还是预谋？\n\nsource-0413\n00:33:35.682 --> 00:33:38.018 align:middle line:100%,end position:50%,middle\n也许她知道了不该知道的事\n\nsource-0414\n00:33:38.185 --> 00:33:41.772 align:middle line:100%,end position:50%,middle\n- 企业机密？\n- 企业机密？她才十六岁\n\nsource-0415\n00:33:41.939 --> 00:33:43.649 align:middle line:100%,end position:50%,middle\n她可非常聪明\n\nsource-0416\n00:33:43.815 --> 00:33:46.527 align:middle line:100%,end position:50%,middle\n当时亨利总说\n海莉将来\n\nsource-0417\n00:33:46.693 --> 00:33:48.320 align:middle line:100%,end position:50%,middle\n一定会接掌范耶尔企业\n\nsource-0418\n00:33:48.946 --> 00:33:51.657 align:middle line:100%,end position:50%,middle\n当天她跟朋友去看游行\n\nsource-0419\n00:33:51.823 --> 00:33:55.494 align:middle line:100%,end position:50%,middle\n她说身体不舒服先离开\n\nsource-0420\n00:33:55.661 --> 00:33:59.164 align:middle line:100%,end position:50%,middle\n但朋友说她也有事瞒着她们\n\nsource-0421\n00:33:59.331 --> 00:34:02.960 align:middle line:100%,end position:50%,middle\n我只知道少女的心思非常复杂\n\nsource-0422\n00:34:03.126 --> 00:34:05.504 align:middle line:100%,end position:50%,middle\n- 我也有个女儿\n- 那你就懂\n\nsource-0423\n00:34:05.671 --> 00:34:07.631 align:middle line:100%,end position:50%,middle\n我想问你\n\nsource-0424\n00:34:08.882 --> 00:34:10.717 align:middle line:100%,end position:50%,middle\n这个\n\nsource-0425\n00:34:13.428 --> 00:34:15.973 align:middle line:100%,end position:50%,middle\n她失踪前一年亨利送的圣诞礼物\n\nsource-0426\n00:34:18.475 --> 00:34:21.395 align:middle line:100%,end position:50%,middle\n我不知看过多少次\n\nsource-0427\n00:34:22.813 --> 00:34:24.147 align:middle line:100%,end position:50%,middle\n我记得每一页\n\nsource-0428\n00:34:24.313 --> 00:34:26.692 align:middle line:100%,end position:50%,middle\n- 我想问最后一页\n- 我也是\n\nsource-0429\n00:34:26.859 --> 00:34:30.821 align:middle line:100%,end position:50%,middle\n这人名和数字一定有意义\n\nsource-0430\n00:34:30.987 --> 00:34:32.447 align:middle line:100%,end position:50%,middle\n是本地的电话号码\n\nsource-0431\n00:34:32.614 --> 00:34:34.867 align:middle line:100%,end position:50%,middle\n第一组是玛歌的电话\n\nsource-0432\n00:34:35.033 --> 00:34:37.953 align:middle line:0%,start position:50%,middle\n她母亲叫玛妲\n她否认认识海莉\n\nsource-0433\n00:34:38.120 --> 00:34:41.164 align:middle line:0%,start position:50%,middle\n第四组RL\n是萝丝玛丽·拉尔森的缩写\n\nsource-0434\n00:34:41.331 --> 00:34:45.210 align:middle line:100%,end position:50%,middle\n一位老女人 几年前死了\n\nsource-0435\n00:34:45.377 --> 00:34:49.755 align:middle line:100%,end position:50%,middle\n其余三组，我找不到任何关联\n\nsource-0436\n00:34:50.382 --> 00:34:53.635 align:middle line:100%,end position:50%,middle\n抱歉让你又想起这件案子\n\nsource-0437\n00:34:53.802 --> 00:34:55.804 align:middle line:100%,end position:50%,middle\n我根本忘不掉\n\nsource-0438\n00:34:57.222 --> 00:34:58.932 align:middle line:100%,end position:50%,middle\n这是我的蕾贝卡案\n\nsource-0439\n00:34:59.600 --> 00:35:01.143 align:middle line:100%,end position:50%,middle\n我不懂\n\nsource-0440\n00:35:01.852 --> 00:35:06.815 align:middle line:100%,end position:50%,middle\n每个警察至少都有一桩\n放不下的悬案\n\nsource-0441\n00:35:07.357 --> 00:35:09.818 align:middle line:100%,end position:50%,middle\n以前有个同事叫托腾森\n\nsource-0442\n00:35:09.985 --> 00:35:12.821 align:middle line:100%,end position:50%,middle\n他花好几年研究蕾贝卡的案子\n\nsource-0443\n00:35:12.988 --> 00:35:16.241 align:middle line:100%,end position:50%,middle\n重新查看档案 反复研究\n\nsource-0444\n00:35:16.408 --> 00:35:18.410 align:middle line:100%,end position:50%,middle\n那时我们还年轻 都在笑他\n\nsource-0445\n00:35:18.577 --> 00:35:20.579 align:middle line:100%,end position:50%,middle\n那也是失踪女孩案件？\n\nsource-0446\n00:35:20.746 --> 00:35:23.498 align:middle line:100%,end position:50%,middle\n我不是因为这样才提起\n\nsource-0447\n00:35:23.665 --> 00:35:26.585 align:middle line:100%,end position:50%,middle\n我要讲的是警察的“灵魂”\n\nsource-0448\n00:35:27.127 --> 00:35:30.005 align:middle line:100%,end position:50%,middle\n<i>可怜的托腾森始终没有侦破</i>\n\nsource-0449\n00:35:30.172 --> 00:35:32.508 align:middle line:100%,end position:50%,middle\n<i>一直放不下</i>\n\nsource-0450\n00:35:33.880 --> 00:35:35.075 align:middle line:100%,end position:50%,middle\n（玛妲、莎拉、RJ、RL、玛丽）\n\nsource-0451\n00:35:39.681 --> 00:35:41.600 align:middle line:100%,end position:50%,middle\n你的前监护人还好吗？\n\nsource-0452\n00:35:42.142 --> 00:35:44.978 align:middle line:100%,end position:50%,middle\n我听说他中风了\n\nsource-0453\n00:35:45.145 --> 00:35:46.188 align:middle line:100%,end position:50%,middle\n真糟\n\nsource-0454\n00:35:47.481 --> 00:35:50.400 align:middle line:100%,end position:50%,middle\n你在安保公司做什么？\n\nsource-0455\n00:35:50.567 --> 00:35:52.361 align:middle line:100%,end position:50%,middle\n倒咖啡、整理信件\n\nsource-0456\n00:35:52.528 --> 00:35:54.446 align:middle line:100%,end position:50%,middle\n不是全职\n\nsource-0457\n00:35:54.613 --> 00:35:56.365 align:middle line:100%,end position:50%,middle\n也不是固定兼职\n\nsource-0458\n00:35:56.532 --> 00:36:01.495 align:middle line:100%,end position:50%,middle\n七、八月就不用倒咖啡和送信？\n\nsource-0459\n00:36:06.166 --> 00:36:08.335 align:middle line:100%,end position:50%,middle\n- 你薪水多少？\n- 够我生活\n\nNATIVE-002\n00:36:10.170 --> 00:36:12.840 align:middle line:100%,end position:50%,middle\n- 房租多少？\n- 我付得起房租\n\nNATIVE-003\n00:36:16.552 --> 00:36:19.471 align:middle line:100%,end position:50%,middle\n- 上次迟交房租是什么时候？\n- 从来没有\n\nsource-0464\n00:36:20.722 --> 00:36:24.434 align:middle line:100%,end position:50%,middle\n你认为眉毛打洞很吸引人？\n\nsource-0465\n00:36:26.520 --> 00:36:27.688 align:middle line:100%,end position:50%,middle\n这就是问题所在\n\nsource-0466\n00:36:29.398 --> 00:36:32.359 align:middle line:100%,end position:50%,middle\n帕姆格伦先生的监护职责\n\nsource-0467\n00:36:32.526 --> 00:36:36.655 align:middle line:100%,end position:50%,middle\n和你管理财务的情况有出入\n\nsource-0468\n00:36:36.822 --> 00:36:40.075 align:middle line:100%,end position:50%,middle\n没有出入\n他明确认定我能管理自己的钱\n\nsource-0469\n00:36:40.242 --> 00:36:41.326 align:middle line:100%,end position:50%,middle\n我看不出来\n\nsource-0470\n00:36:41.493 --> 00:36:43.745 align:middle line:100%,end position:50%,middle\n- 我不是小孩子\n- 现在不是 但以前是\n\nsource-0471\n00:36:43.912 --> 00:36:46.081 align:middle line:100%,end position:50%,middle\n从那时到现在，你被送进\n\nsource-0472\n00:36:46.248 --> 00:36:49.042 align:middle line:100%,end position:50%,middle\n圣斯特凡医院的封闭病房\n\nsource-0473\n00:36:49.209 --> 00:36:51.378 align:middle line:100%,end position:50%,middle\n持续有暴力行为\n\nsource-0474\n00:36:51.879 --> 00:36:54.756 align:middle line:100%,end position:50%,middle\n换了四个寄养家庭\n\nsource-0475\n00:36:54.923 --> 00:36:58.218 align:middle line:100%,end position:50%,middle\n因酗酒和吸毒各被逮捕两次\n\nsource-0476\n00:36:58.385 --> 00:37:02.472 align:middle line:100%,end position:50%,middle\n还有攻击\n把酒瓶砸到一个男人脸上\n\nsource-0477\n00:37:02.639 --> 00:37:04.933 align:middle line:100%,end position:50%,middle\n这才刚发生\n\nsource-0478\n00:37:05.100 --> 00:37:09.313 align:middle line:100%,end position:50%,middle\n你或许骗帕姆格伦先生\n相信你已经改过自新\n\nsource-0479\n00:37:09.479 --> 00:37:11.481 align:middle line:100%,end position:50%,middle\n但从你的档案\n\nsource-0480\n00:37:11.648 --> 00:37:15.527 align:middle line:100%,end position:50%,middle\n更别提你现在看我的眼神\n\nsource-0481\n00:37:15.694 --> 00:37:17.446 align:middle line:100%,end position:50%,middle\n我觉得你并没有改变\n\nsource-0482\n00:37:17.946 --> 00:37:20.657 align:middle line:100%,end position:50%,middle\n好日子结束了\n\nsource-0483\n00:37:20.824 --> 00:37:23.869 align:middle line:100%,end position:50%,middle\n从现在起\n我每个月给你零用钱\n\nsource-0484\n00:37:24.036 --> 00:37:26.121 align:middle line:100%,end position:50%,middle\n所有收据都要交给我\n\nsource-0485\n00:37:26.288 --> 00:37:29.666 align:middle line:100%,end position:50%,middle\n如果钱少了我就知道你去买毒品\n\nNATIVE-004\n00:37:29.833 --> 00:37:33.378 align:middle line:100%,end position:50%,middle\n- 我从十岁起就照顾自己\n- 是国家在照顾你\n\nsource-0488\n00:37:33.545 --> 00:37:36.173 align:middle line:100%,end position:50%,middle\n看着我 这很重要\n\nsource-0489\n00:37:36.340 --> 00:37:39.718 align:middle line:100%,end position:50%,middle\n你的行为在档案里记得一清二楚\n\nsource-0490\n00:37:39.885 --> 00:37:42.429 align:middle line:100%,end position:50%,middle\n就算我选择另一种安排\n\nsource-0491\n00:37:42.596 --> 00:37:46.266 align:middle line:100%,end position:50%,middle\n取代刚才那种宽松待遇\n也不会有人吃惊\n\nsource-0492\n00:37:48.435 --> 00:37:52.564 align:middle line:100%,end position:50%,middle\n还是把你关到精神病院？\n\nsource-0493\n00:38:13.585 --> 00:38:14.628 align:middle line:100%,end position:50%,middle\n- 麦可？\n- 是\n\nsource-0494\n00:38:14.795 --> 00:38:16.380 align:middle line:100%,end position:50%,middle\n- 我是小丽\n- 嗨\n\nNATIVE-005\n00:38:16.547 --> 00:38:19.716 align:middle line:100%,end position:50%,middle\n- 我们去同一个地方，上车吧\n- 太好了，谢谢\n\nsource-0497\n00:38:28.016 --> 00:38:31.270 align:middle line:100%,end position:50%,middle\n我在上山的半路上救了他\n\nsource-0498\n00:38:31.436 --> 00:38:34.439 align:middle line:100%,end position:50%,middle\n- 我有点缺乏锻炼\n- 这坡对谁都难爬\n\nsource-0499\n00:38:34.606 --> 00:38:37.067 align:middle line:100%,end position:50%,middle\n- 我该先提醒你，请进\n- 谢谢，马丁\n\nsource-0500\n00:38:37.234 --> 00:38:39.069 align:middle line:100%,end position:50%,middle\n亨利很赞许你\n\nsource-0501\n00:38:39.236 --> 00:38:43.115 align:middle line:100%,end position:50%,middle\n- 不用脱 鞋子穿着就好\n- 马丁 这好香\n\nsource-0502\n00:38:43.699 --> 00:38:46.326 align:middle line:100%,end position:50%,middle\n- 今晚喝什么？\n- 这里太棒了 看看这景色\n\nsource-0503\n00:38:46.493 --> 00:38:50.122 align:middle line:100%,end position:50%,middle\n我曾在公司哥德堡的\n石化部门工作\n\nNATIVE-006\n00:38:50.289 --> 00:38:53.333 align:middle line:100%,end position:50%,middle\n- 部门卖掉后，我也跟着走了\n- 糟糕的一天\n\nsource-0506\n00:38:53.834 --> 00:38:56.962 align:middle line:100%,end position:50%,middle\n我现在住香港\n回斯德哥尔摩参加家庭活动\n\nsource-0507\n00:38:57.129 --> 00:38:59.590 align:middle line:100%,end position:50%,middle\n也会顺便来找马丁几天\n\nsource-0508\n00:38:59.756 --> 00:39:03.719 align:middle line:100%,end position:50%,middle\n- 她指定的麋鹿排\n- 谁能抗拒？这真好吃\n\nsource-0509\n00:39:05.470 --> 00:39:08.390 align:middle line:100%,end position:50%,middle\n门好像没关好\n酒还可以吗？\n\nsource-0510\n00:39:08.557 --> 00:39:12.227 align:middle line:100%,end position:50%,middle\n- 还是要换别支？\n- 这很好喝\n\nsource-0511\n00:39:16.773 --> 00:39:18.859 align:middle line:100%,end position:50%,middle\n马丁说你正在写一本书\n\nsource-0512\n00:39:19.026 --> 00:39:21.653 align:middle line:100%,end position:50%,middle\n- 亨利的传记\n- 我喜欢亨利，他很迷人\n\nsource-0513\n00:39:21.820 --> 00:39:23.113 align:middle line:100%,end position:50%,middle\n马丁也是\n\nsource-0514\n00:39:23.280 --> 00:39:26.491 align:middle line:100%,end position:50%,middle\n他们代表了瑞典的过去和现在\n\nsource-0515\n00:39:26.658 --> 00:39:27.910 align:middle line:100%,end position:50%,middle\n正是\n\nsource-0516\n00:39:29.703 --> 00:39:32.039 align:middle line:100%,end position:50%,middle\n你知道海莉的事吧？\n\nsource-0517\n00:39:32.789 --> 00:39:34.750 align:middle line:100%,end position:50%,middle\n- 你不知道？\n- 我知道\n\nsource-0518\n00:39:35.876 --> 00:39:39.713 align:middle line:100%,end position:50%,middle\n他们不想谈 但不可能当没发生\n\nsource-0519\n00:39:39.880 --> 00:39:41.840 align:middle line:100%,end position:50%,middle\n- 没发生什么？\n- 海莉\n\nsource-0520\n00:39:42.007 --> 00:39:44.301 align:middle line:100%,end position:50%,middle\n我们可以晚点聊\n\nsource-0521\n00:39:44.801 --> 00:39:46.386 align:middle line:100%,end position:50%,middle\n现在就可以聊\n\nsource-0522\n00:39:46.553 --> 00:39:48.889 align:middle line:100%,end position:50%,middle\n小丽知道我家族所有疯狂事\n\nsource-0523\n00:39:49.056 --> 00:39:51.391 align:middle line:100%,end position:50%,middle\n- 所以她永远不会嫁给我\n- 原因之一\n\nsource-0524\n00:39:51.558 --> 00:39:53.602 align:middle line:100%,end position:50%,middle\n这可不要写进书里\n\nsource-0525\n00:39:53.769 --> 00:39:56.063 align:middle line:100%,end position:50%,middle\n其他都可以写，海莉当然也可以\n\nsource-0526\n00:39:56.230 --> 00:40:00.108 align:middle line:100%,end position:50%,middle\n你知道\n她走后一切都不同了\n\nsource-0527\n00:40:00.275 --> 00:40:02.653 align:middle line:100%,end position:50%,middle\n不只是整个家族 公司也是\n\nsource-0528\n00:40:02.819 --> 00:40:04.863 align:middle line:100%,end position:50%,middle\n- 怎么说？\n- 我们虽然不是爱立信或北欧银行\n\nsource-0529\n00:40:05.030 --> 00:40:08.534 align:middle line:100%,end position:50%,middle\n但仍是瑞典最大的家族企业\n\nsource-0530\n00:40:08.700 --> 00:40:10.953 align:middle line:100%,end position:50%,middle\n全盛时期有四万名员工\n\nsource-0531\n00:40:11.119 --> 00:40:12.329 align:middle line:100%,end position:50%,middle\n现在只剩一半\n\nsource-0532\n00:40:12.496 --> 00:40:16.375 align:middle line:100%,end position:50%,middle\n我妹死后公司就开始走下坡\n\nsource-0533\n00:40:20.170 --> 00:40:23.257 align:middle line:100%,end position:50%,middle\n它毁了亨利的雄心壮志\n\nsource-0534\n00:40:23.590 --> 00:40:24.633 align:middle line:100%,end position:50%,middle\n他心都碎了\n\nsource-0535\n00:40:26.093 --> 00:40:28.303 align:middle line:100%,end position:50%,middle\n- 那天你也在这儿？\n- 我晚些时候才到\n\nsource-0536\n00:40:28.470 --> 00:40:31.181 align:middle line:100%,end position:50%,middle\n桥上出事后\n坐四点半的火车来的\n\nsource-0537\n00:40:31.412 --> 00:40:34.753 align:middle line:100%,end position:50%,middle\n- 那班车我很熟\n- 恐怖的一天\n\nsource-0538\n00:40:36.061 --> 00:40:38.063 align:middle line:100%,end position:50%,middle\n还有之后那些日子，你知道吧\n\nsource-0539\n00:40:38.230 --> 00:40:42.484 align:middle line:100%,end position:50%,middle\n不断搜寻，毫无结果，更糟了\n\nsource-0540\n00:40:43.277 --> 00:40:47.281 align:middle line:100%,end position:50%,middle\n这件事得在书里好好描述\n\nsource-0541\n00:41:10.012 --> 00:41:12.890 align:middle line:100%,end position:50%,middle\n社福署打电话来\n\nsource-0542\n00:41:13.348 --> 00:41:15.767 align:middle line:100%,end position:50%,middle\n我被派给新监护人\n\nsource-0543\n00:42:18.705 --> 00:42:20.040 align:middle line:100%,end position:50%,middle\n- 嗨\n- 哈啰\n\nsource-0544\n00:42:20.207 --> 00:42:22.668 align:middle line:100%,end position:50%,middle\n我过来打声招呼\n\nsource-0545\n00:42:22.835 --> 00:42:26.338 align:middle line:100%,end position:50%,middle\n- 我是西西莉亚\n- 你好 请进\n\nsource-0546\n00:42:29.675 --> 00:42:31.718 align:middle line:100%,end position:50%,middle\n要喝咖啡吗？\n\nsource-0547\n00:42:31.885 --> 00:42:34.054 align:middle line:100%,end position:50%,middle\n不用 谢谢\n\nsource-0548\n00:42:43.564 --> 00:42:48.151 align:middle line:100%,end position:50%,middle\n我们对家族传记这件事都不太舒服\n\nsource-0549\n00:42:48.318 --> 00:42:51.154 align:middle line:100%,end position:50%,middle\n跟家族无关 我是写亨利和公司\n\nsource-0550\n00:42:51.321 --> 00:42:52.489 align:middle line:100%,end position:50%,middle\n我刚才说了\n\nsource-0551\n00:42:52.691 --> 00:42:53.839 align:middle line:100%,end position:50%,middle\n（西西莉亚\n近期照片？）\n\nsource-0552\n00:42:54.032 --> 00:42:57.119 align:middle line:100%,end position:50%,middle\n我不会在书里故意丑化家族成员\n\nNATIVE-007\n00:42:57.286 --> 00:43:02.291 align:middle line:100%,end position:50%,middle\n- 不像让你吃官司的那篇报道\n- 对，不像那篇\n\nsource-0555\n00:43:02.457 --> 00:43:05.794 align:middle line:100%,end position:50%,middle\n所以你不是为了调查海莉的事？\n\nsource-0556\n00:43:05.961 --> 00:43:09.715 align:middle line:100%,end position:50%,middle\n我会写海莉 但那不是我的重点\n\nsource-0557\n00:43:09.882 --> 00:43:11.884 align:middle line:100%,end position:50%,middle\n贡纳尔搬来的那几箱资料\n\nsource-0558\n00:43:12.050 --> 00:43:16.471 align:middle line:100%,end position:50%,middle\n现在放在壁橱里？\n那不是亨利的调查资料吗？\n\nsource-0559\n00:43:16.638 --> 00:43:20.767 align:middle line:100%,end position:50%,middle\n有时我怀疑谁比较疯狂\n是纳粹父亲还是着魔的叔父\n\nsource-0560\n00:43:20.910 --> 00:43:22.021 align:middle line:100%,end position:50%,middle\n（哈洛德）\n\nsource-0561\n00:43:22.352 --> 00:43:23.937 align:middle line:100%,end position:50%,middle\n既然你提起\n\nsource-0562\n00:43:24.104 --> 00:43:26.273 align:middle line:100%,end position:50%,middle\n海莉是怎样的人？\n\nsource-0563\n00:43:26.440 --> 00:43:27.608 align:middle line:100%,end position:50%,middle\n她是怎样的人？\n\nsource-0564\n00:43:27.774 --> 00:43:30.444 align:middle line:100%,end position:50%,middle\n- 亨利肯定告诉过你\n- 他当时和我一样大\n\nsource-0565\n00:43:30.611 --> 00:43:33.780 align:middle line:100%,end position:50%,middle\n他不可能懂一个少女的心思\n\nNATIVE-008\n00:43:33.947 --> 00:43:37.242 align:middle line:100%,end position:50%,middle\n- 你们同龄\n- 我妹阿妮塔和她年龄更接近\n\nsource-0568\n00:43:37.409 --> 00:43:39.786 align:middle line:100%,end position:50%,middle\n她最了解海莉，你该去问她\n\nsource-0569\n00:43:39.953 --> 00:43:43.373 align:middle line:100%,end position:50%,middle\n- 我很乐意 她住哪里？\n- 我猜在伦敦\n\nsource-0570\n00:43:43.540 --> 00:43:45.417 align:middle line:100%,end position:50%,middle\n你不知道自己妹妹住哪？\n\nsource-0571\n00:43:45.584 --> 00:43:48.837 align:middle line:100%,end position:50%,middle\n我们多年没见，一直合不来\n\nsource-0572\n00:43:49.004 --> 00:43:52.466 align:middle line:100%,end position:50%,middle\n- 我听惯这话了\n- 她比我更讨厌这里\n\nsource-0573\n00:43:52.633 --> 00:43:55.552 align:middle line:100%,end position:50%,middle\n所以离家搬到伦敦 就这样\n\nsource-0574\n00:43:55.719 --> 00:43:58.680 align:middle line:100%,end position:50%,middle\n连圣诞卡都没寄过 更别说回来\n\nsource-0575\n00:43:58.847 --> 00:44:00.641 align:middle line:100%,end position:50%,middle\n我会帮你找到她\n\nsource-0576\n00:44:00.807 --> 00:44:03.977 align:middle line:100%,end position:50%,middle\n如果你找到她 并且谈起我们\n\nsource-0577\n00:44:04.144 --> 00:44:07.648 align:middle line:100%,end position:50%,middle\n她应该会叫你滚蛋\n\nsource-0578\n00:44:14.029 --> 00:44:15.989 align:middle line:100%,end position:50%,middle\n有备份吧？\n\nsource-0579\n00:44:17.491 --> 00:44:18.992 align:middle line:100%,end position:50%,middle\n有 在硬盘里\n\nsource-0580\n00:44:19.159 --> 00:44:21.954 align:middle line:100%,end position:50%,middle\n很好 因为这台报销了\n\nsource-0581\n00:44:27.084 --> 00:44:30.087 align:middle line:100%,end position:50%,middle\n<i>你感染过性病吗？</i>\n\nsource-0582\n00:44:33.715 --> 00:44:37.636 align:middle line:100%,end position:50%,middle\n<i>上次接受艾滋检测是何时？</i>\n\nsource-0583\n00:44:39.805 --> 00:44:42.182 align:middle line:100%,end position:50%,middle\n<i>上个月你有过几个性伴侣？</i>\n\nsource-0584\n00:44:43.684 --> 00:44:46.019 align:middle line:100%,end position:50%,middle\n其中有几个男人？\n\nsource-0585\n00:44:49.439 --> 00:44:52.526 align:middle line:100%,end position:50%,middle\n这是例行问题 与你健康有关\n\nsource-0586\n00:44:52.693 --> 00:44:53.902 align:middle line:100%,end position:50%,middle\n随便你想写什么\n\nsource-0587\n00:44:54.069 --> 00:44:56.446 align:middle line:100%,end position:50%,middle\n为什么要买这么贵的电脑？\n\nsource-0588\n00:44:56.613 --> 00:44:58.824 align:middle line:100%,end position:50%,middle\n- 工作需要\n- 倒咖啡和整理信件？\n\nsource-0589\n00:44:58.991 --> 00:45:01.994 align:middle line:100%,end position:50%,middle\n- 我的钱该由我支配\n- 你会的\n\nsource-0590\n00:45:02.160 --> 00:45:04.872 align:middle line:100%,end position:50%,middle\n只要你学会合群\n\nsource-0591\n00:45:05.038 --> 00:45:06.832 align:middle line:100%,end position:50%,middle\n你做得到吗？\n\nsource-0592\n00:45:09.209 --> 00:45:13.380 align:middle line:100%,end position:50%,middle\n不如我们现在就来试试\n\nsource-0593\n00:45:15.424 --> 00:45:19.094 align:middle line:100%,end position:50%,middle\n何不先和我试\n\nsource-0594\n00:45:25.851 --> 00:45:28.979 align:middle line:100%,end position:50%,middle\n你为我做点事 我也会帮你\n\nsource-0595\n00:45:30.189 --> 00:45:32.191 align:middle line:100%,end position:50%,middle\n这是正常人的社交\n\nsource-0596\n00:45:46.914 --> 00:45:49.249 align:middle line:100%,end position:50%,middle\n我希望你能买到那台电脑\n\nsource-0597\n00:46:06.225 --> 00:46:07.601 align:middle line:100%,end position:50%,middle\n感觉它\n\nsource-0598\n00:46:08.519 --> 00:46:10.103 align:middle line:100%,end position:50%,middle\n这是斜纹呢\n\nsource-0599\n00:46:16.568 --> 00:46:18.278 align:middle line:100%,end position:50%,middle\n拉下拉链\n\nsource-0600\n00:46:27.037 --> 00:46:28.705 align:middle line:100%,end position:50%,middle\n然后呢…\n\nsource-0601\n00:46:30.207 --> 00:46:32.000 align:middle line:100%,end position:50%,middle\n再…\n\nsource-0602\n00:46:45.389 --> 00:46:47.599 align:middle line:100%,end position:50%,middle\n我喜欢你不情愿的样子\n\nsource-0603\n00:46:49.142 --> 00:46:50.644 align:middle line:100%,end position:50%,middle\n差点就让人相信了\n\nsource-0604\n00:48:25.614 --> 00:48:26.949 align:middle line:100%,end position:50%,middle\n<i>我找阿妮塔范耶尔</i>\n\nsource-0605\n00:48:27.115 --> 00:48:29.618 align:middle line:100%,end position:50%,middle\n- 在那里\n- 谢谢\n\nsource-0606\n00:48:32.379 --> 00:48:33.296 align:middle line:100%,end position:50%,middle\n打扰一下\n\nsource-0607\n00:48:34.020 --> 00:48:35.782 align:middle line:100%,end position:50%,middle\n也许我该预约\n\nsource-0608\n00:48:36.542 --> 00:48:38.627 align:middle line:100%,end position:50%,middle\n没关系\n\nsource-0609\n00:48:38.794 --> 00:48:41.088 align:middle line:100%,end position:50%,middle\n- 请坐\n- 谢谢\n\nsource-0610\n00:48:41.255 --> 00:48:44.258 align:middle line:100%,end position:50%,middle\n- 我是麦可\n- 麦可 你好\n\nsource-0611\n00:48:44.424 --> 00:48:45.926 align:middle line:100%,end position:50%,middle\n你好吗？\n\nsource-0612\n00:48:46.093 --> 00:48:48.595 align:middle line:100%,end position:50%,middle\n需要投资咨询？\n\nsource-0613\n00:48:48.762 --> 00:48:50.556 align:middle line:100%,end position:50%,middle\n如果我还有钱的话\n\nsource-0614\n00:48:51.014 --> 00:48:52.558 align:middle line:100%,end position:50%,middle\n我不太懂你的意思\n\nNATIVE-026\n00:48:53.183 --> 00:48:58.647 align:middle line:100%,end position:50%,middle\n我在帮你叔父亨利写传记\n所以才来这里\n\nsource-0616\n00:48:59.231 --> 00:49:01.400 align:middle line:100%,end position:50%,middle\n我二十年没见过他\n\nsource-0617\n00:49:01.567 --> 00:49:03.819 align:middle line:100%,end position:50%,middle\n其实更久\n\nsource-0618\n00:49:03.986 --> 00:49:07.030 align:middle line:100%,end position:50%,middle\n也没见过我姐姐或家族其他人\n\nsource-0619\n00:49:07.197 --> 00:49:10.242 align:middle line:100%,end position:50%,middle\n我在写更早以前\n\nsource-0620\n00:49:10.409 --> 00:49:12.494 align:middle line:100%,end position:50%,middle\n你的回忆很重要\n\nsource-0621\n00:49:12.661 --> 00:49:15.539 align:middle line:100%,end position:50%,middle\n我不知要从哪说起\n\nsource-0622\n00:49:15.732 --> 00:49:18.662 align:middle line:100%,end position:50%,middle\n那我缩小范围，我写到六十年代\n\nsource-0623\n00:49:18.863 --> 00:49:22.418 align:middle line:100%,end position:50%,middle\n那件改变亨利一生的事\n\nsource-0624\n00:49:22.588 --> 00:49:24.047 align:middle line:100%,end position:50%,middle\n海莉\n\nsource-0625\n00:49:26.508 --> 00:49:31.221 align:middle line:100%,end position:50%,middle\n我知道的都告诉那位警探了\n\nNATIVE-009\n00:49:31.388 --> 00:49:34.516 align:middle line:100%,end position:50%,middle\n- 莫瑞尔\n- 我当时的记忆好多了\n\nsource-0628\n00:49:34.683 --> 00:49:37.477 align:middle line:100%,end position:50%,middle\n我其实不是问那件事本身\n\nsource-0629\n00:49:37.644 --> 00:49:41.148 align:middle line:100%,end position:50%,middle\n海莉是个怎样的孩子？\n\nsource-0630\n00:49:42.024 --> 00:49:45.235 align:middle line:100%,end position:50%,middle\n她情绪非常不稳定\n\nsource-0631\n00:49:47.154 --> 00:49:50.365 align:middle line:100%,end position:50%,middle\n就像所有范耶尔家的小孩\n\nsource-0632\n00:49:50.532 --> 00:49:52.534 align:middle line:100%,end position:50%,middle\n她有个疯狂母亲\n\nNATIVE-010\n00:49:52.701 --> 00:49:56.538 align:middle line:100%,end position:50%,middle\n酒鬼父亲\n不过至少她父亲不是纳粹\n\nsource-0635\n00:49:56.705 --> 00:49:58.415 align:middle line:100%,end position:50%,middle\n- 他会打小孩吗？\n- 我父亲？\n\nsource-0636\n00:49:58.582 --> 00:49:59.917 align:middle line:100%,end position:50%,middle\n不 海莉的\n\nsource-0637\n00:50:00.083 --> 00:50:04.755 align:middle line:100%,end position:50%,middle\n我没看过 但的确有些不对劲\n\nsource-0638\n00:50:06.215 --> 00:50:09.927 align:middle line:100%,end position:50%,middle\n有时她内向、沉默寡言\n\nsource-0639\n00:50:10.093 --> 00:50:13.222 align:middle line:100%,end position:50%,middle\n但不一会儿 她又打扮艳丽\n\nsource-0640\n00:50:13.388 --> 00:50:17.142 align:middle line:100%,end position:50%,middle\n穿着紧身毛衣来学校\n\nsource-0641\n00:50:17.309 --> 00:50:20.729 align:middle line:100%,end position:50%,middle\n接着又像修女一样虔诚研读《圣经》\n\nsource-0642\n00:50:20.896 --> 00:50:24.274 align:middle line:100%,end position:50%,middle\n范耶尔家族没有宗教信仰\n你能想像吗？\n\nsource-0643\n00:50:24.441 --> 00:50:27.027 align:middle line:100%,end position:50%,middle\n她显然非常不快乐\n\nsource-0644\n00:50:28.445 --> 00:50:32.115 align:middle line:100%,end position:50%,middle\n- 你觉得她发生了什么事？\n- 每个人都知道发生了什么事\n\nsource-0645\n00:50:32.574 --> 00:50:35.536 align:middle line:100%,end position:50%,middle\n你想过凶手是谁或动机吗？\n\nsource-0646\n00:50:35.702 --> 00:50:38.830 align:middle line:100%,end position:50%,middle\n我只觉得非常难过\n\nsource-0647\n00:50:39.665 --> 00:50:43.210 align:middle line:100%,end position:50%,middle\n我十八岁就离家 再也没回去过\n\nsource-0648\n00:50:43.377 --> 00:50:45.712 align:middle line:100%,end position:50%,middle\n海莉也会选择离家\n\nsource-0649\n00:50:46.255 --> 00:50:48.298 align:middle line:100%,end position:50%,middle\n只是她没有活到十八岁\n\nsource-0650\n00:50:48.465 --> 00:50:51.051 align:middle line:100%,end position:50%,middle\n<i>请找毕尔曼先生 我是莎兰德</i>\n\nsource-0651\n00:50:51.218 --> 00:50:53.303 align:middle line:100%,end position:50%,middle\n<i>请稍等</i>\n\nsource-0652\n00:50:53.470 --> 00:50:55.514 align:middle line:100%,end position:50%,middle\n<i>莉丝，好久没见你，还好吗？</i>\n\nsource-0653\n00:50:55.681 --> 00:50:58.892 align:middle line:100%,end position:50%,middle\n我没事，抱歉失约了\n最近工作很多\n\nNATIVE-011\n00:50:59.059 --> 00:51:02.896 align:middle line:100%,end position:50%,middle\n<i>- 出什么事了？</i>\n- 没什么好担心的\n\nsource-0656\n00:51:03.063 --> 00:51:06.149 align:middle line:100%,end position:50%,middle\n我需要预支零用钱\n\nsource-0657\n00:51:06.316 --> 00:51:08.694 align:middle line:100%,end position:50%,middle\n今晚可以去你办公室吗？\n\nsource-0658\n00:51:09.111 --> 00:51:10.946 align:middle line:100%,end position:50%,middle\n<i>我晚上不工作</i>\n\nsource-0659\n00:51:11.113 --> 00:51:13.907 align:middle line:100%,end position:50%,middle\n<i>来我家好了 你有笔吗？</i>\n\nNATIVE-012\n00:51:14.074 --> 00:51:17.536 align:middle line:100%,end position:50%,middle\n- 不用笔，地址是什么？\n<i>- 是…</i>\n\nsource-0662\n00:51:34.136 --> 00:51:36.680 align:middle line:100%,end position:50%,middle\n<i>- 谁？</i>\n- 是我\n\nsource-0663\n00:51:45.448 --> 00:51:47.185 align:middle line:100%,end position:50%,middle\n莉丝\n\nsource-0664\n00:51:47.383 --> 00:51:48.670 align:middle line:100%,end position:50%,middle\n进来\n\nsource-0665\n00:51:57.868 --> 00:51:59.494 align:middle line:100%,end position:50%,middle\n- 喜欢吗？\n- 还可以\n\nsource-0666\n00:51:59.953 --> 00:52:00.996 align:middle line:100%,end position:50%,middle\n这是我家\n\nNATIVE-013\n00:52:02.873 --> 00:52:05.792 align:middle line:100%,end position:50%,middle\n- 这次要钱做什么？\n- 买食物\n\nsource-0669\n00:52:10.088 --> 00:52:11.507 align:middle line:100%,end position:50%,middle\n你还好吗？\n\nsource-0670\n00:52:17.638 --> 00:52:20.516 align:middle line:100%,end position:50%,middle\n我很高兴你决定来找我\n\nsource-0671\n00:52:21.058 --> 00:52:22.768 align:middle line:100%,end position:50%,middle\n我只想拿钱走人\n\nsource-0672\n00:52:22.935 --> 00:52:25.521 align:middle line:100%,end position:50%,middle\n看看我们能不能帮你解决\n\nsource-0673\n00:52:36.657 --> 00:52:38.283 align:middle line:100%,end position:50%,middle\n等等\n\nsource-0674\n00:52:38.659 --> 00:52:40.953 align:middle line:100%,end position:50%,middle\n有什么问题？\n\nsource-0675\n00:52:41.119 --> 00:52:43.080 align:middle line:100%,end position:50%,middle\n我想知道…\n\nsource-0676\n00:52:43.247 --> 00:52:46.250 align:middle line:100%,end position:50%,middle\n是不是每次都得“做”\n才有钱吃饭？\n\nsource-0677\n00:52:46.416 --> 00:52:49.211 align:middle line:100%,end position:50%,middle\n你板起脸来真可爱\n\nsource-0678\n00:54:33.148 --> 00:54:35.150 align:middle line:100%,end position:50%,middle\n我忘了问你\n\nsource-0679\n00:54:36.109 --> 00:54:37.194 align:middle line:100%,end position:50%,middle\n你喜欢肛交吗？\n\nsource-0680\n00:55:33.166 --> 00:55:36.336 align:middle line:100%,end position:50%,middle\n<i>信就是所望之事的实底</i>\n\nNATIVE-050\n00:55:36.503 --> 00:55:40.716 align:middle line:100%,end position:50%,middle\n<i>是未见之事的确据\n我们因着信</i>\n\nNATIVE-051\n00:55:40.883 --> 00:55:44.553 align:middle line:100%,end position:50%,middle\n<i>知道世界是由神的话造的</i>\n\nsource-0683\n00:56:32.434 --> 00:56:35.229 align:middle line:100%,end position:50%,middle\n- 我开车送你回去\n- 我可以自己回家\n\nsource-0684\n00:56:35.812 --> 00:56:37.397 align:middle line:100%,end position:50%,middle\n你确定？\n\nsource-0685\n00:57:07.502 --> 00:57:10.563 align:middle line:100%,end position:50%,middle\n（一万块\n莉丝莎兰德）\n\nsource-0686\n00:57:10.773 --> 00:57:13.174 align:middle line:100%,end position:50%,middle\n（艾瑞克毕尔曼\n买食物）\n\nsource-0687\n00:57:43.714 --> 00:57:46.216 align:middle line:100%,end position:50%,middle\n- 屋里比较暖吧？\n- 一样冷\n\nsource-0688\n00:57:47.593 --> 00:57:50.804 align:middle line:100%,end position:50%,middle\n麦可不在杂志社这段时间\n\nsource-0689\n00:57:50.971 --> 00:57:53.182 align:middle line:100%,end position:50%,middle\n如果让你们财务吃紧，我很抱歉\n\nsource-0690\n00:57:53.348 --> 00:57:55.475 align:middle line:100%,end position:50%,middle\n- 我们会撑过去的\n- 你确定？\n\nsource-0691\n00:57:55.642 --> 00:57:57.394 align:middle line:100%,end position:50%,middle\n能撑多久？\n\nsource-0692\n00:57:58.687 --> 00:57:59.730 align:middle line:100%,end position:50%,middle\n六个月？\n\nNATIVE-014\n00:58:00.689 --> 00:58:03.901 align:middle line:100%,end position:50%,middle\n- 差不多\n- 我以前办过报纸\n\nsource-0695\n00:58:04.067 --> 00:58:06.987 align:middle line:100%,end position:50%,middle\n- 我们在五零年代有六份报纸\n- 现在只剩一份\n\nsource-0696\n00:58:07.154 --> 00:58:10.282 align:middle line:100%,end position:50%,middle\n- 《赫德史塔新报》\n- 我让我侄子毕耶打理\n\nsource-0697\n00:58:10.449 --> 00:58:12.868 align:middle line:100%,end position:50%,middle\n因为他也做不了别的\n\nsource-0698\n00:58:13.035 --> 00:58:15.454 align:middle line:100%,end position:50%,middle\n你对合资有什么看法？\n\nsource-0699\n00:58:16.955 --> 00:58:20.209 align:middle line:100%,end position:50%,middle\n以前绝不会考虑\n\nsource-0700\n00:58:21.376 --> 00:58:23.003 align:middle line:100%,end position:50%,middle\n我们很重视独立报道权\n\nsource-0701\n00:58:23.170 --> 00:58:25.714 align:middle line:100%,end position:50%,middle\n说穿了那还是由广告决定\n\nsource-0702\n00:58:25.881 --> 00:58:29.301 align:middle line:100%,end position:50%,middle\n你维持独立报道 我们不会干涉\n\nNATIVE-015\n00:58:29.468 --> 00:58:34.389 align:middle line:100%,end position:50%,middle\n- 抱歉，我漏听了什么？\n- 在谈投资这本杂志\n\nsource-0705\n00:58:34.556 --> 00:58:38.519 align:middle line:100%,end position:50%,middle\n- 我知道 但为什么？\n- 绝不会是为了赚钱\n\nsource-0706\n00:58:38.685 --> 00:58:42.898 align:middle line:100%,end position:50%,middle\n我很抱歉在你们最困难时\n把麦可带走了\n\nsource-0707\n00:58:43.065 --> 00:58:48.028 align:middle line:100%,end position:50%,middle\n但现在我相信这是正确的事\n也是道义上该做的事\n\nsource-0708\n00:58:48.529 --> 00:58:50.239 align:middle line:100%,end position:50%,middle\n这是一个原因，还有…\n\nsource-0709\n00:58:52.115 --> 00:58:53.325 align:middle line:100%,end position:50%,middle\n是？\n\nsource-0710\n00:58:53.825 --> 00:58:56.453 align:middle line:100%,end position:50%,middle\n朋友的敌人就是我的敌人\n\nsource-0711\n00:58:56.954 --> 00:58:59.248 align:middle line:100%,end position:50%,middle\n你和他们讨论多久了？\n\nsource-0712\n00:58:59.414 --> 00:59:02.084 align:middle line:100%,end position:50%,middle\n没谈过，他们昨天打来\n请我过来一趟\n\nsource-0713\n00:59:02.251 --> 00:59:04.503 align:middle line:100%,end position:50%,middle\n- 你为什么没告诉我？\n- 你现在住在荒郊野外\n\nsource-0714\n00:59:04.670 --> 00:59:09.216 align:middle line:100%,end position:50%,middle\n- 所以活该被当白痴耍？\n- 我只是想听听他们怎么说\n\nsource-0715\n00:59:09.716 --> 00:59:11.593 align:middle line:100%,end position:50%,middle\n你会不等他们开口就拒绝\n\nsource-0716\n00:59:11.760 --> 00:59:13.720 align:middle line:100%,end position:50%,middle\n我现在说 这主意很糟\n\nsource-0717\n00:59:13.887 --> 00:59:17.307 align:middle line:100%,end position:50%,middle\n刚刚说六个月其实是撒谎\n\nsource-0718\n00:59:17.474 --> 00:59:19.393 align:middle line:100%,end position:50%,middle\n我们撑不过三个月\n\nsource-0719\n00:59:19.560 --> 00:59:22.271 align:middle line:100%,end position:50%,middle\n你不了解他们 一家都是疯子\n\nsource-0720\n00:59:22.437 --> 00:59:23.730 align:middle line:100%,end position:50%,middle\n又不是要嫁给他们\n\nsource-0721\n00:59:23.897 --> 00:59:27.025 align:middle line:100%,end position:50%,middle\n要是答应，就等于嫁进去了\n\nsource-0722\n00:59:27.192 --> 00:59:29.528 align:middle line:100%,end position:50%,middle\n你想拒绝就去说啊\n\nsource-0723\n00:59:29.695 --> 00:59:33.866 align:middle line:100%,end position:50%,middle\n与其持有一半股份\n不如全部归我们，结果一无所有\n\nsource-0724\n00:59:38.787 --> 00:59:40.289 align:middle line:100%,end position:50%,middle\n- 麦可\n- 干嘛？\n\nsource-0725\n00:59:40.455 --> 00:59:42.833 align:middle line:100%,end position:50%,middle\n我明天一早就要离开这个荒岛\n\nsource-0726\n00:59:43.000 --> 00:59:45.878 align:middle line:100%,end position:50%,middle\n- 所以？\n- 所以你到底上不上床？\n\nsource-0727\n00:59:53.093 --> 00:59:54.720 align:middle line:100%,end position:50%,middle\n那支多少？\n\nsource-0728\n00:59:56.346 --> 00:59:58.640 align:middle line:100%,end position:50%,middle\n将近三千\n\nsource-0729\n01:00:00.225 --> 01:00:02.227 align:middle line:100%,end position:50%,middle\n会很痛\n\nsource-0730\n01:00:04.938 --> 01:00:05.981 align:middle line:100%,end position:50%,middle\n是你要刺的\n\nsource-0731\n01:00:10.121 --> 01:00:14.239 align:middle line:0%,start position:50%,middle\n<i>范耶尔企业入股</i>《千禧年》\n<i>成为最大股东</i>\n\nsource-0732\n01:00:14.446 --> 01:00:17.463 align:middle line:100%,end position:50%,middle\n<i>该杂志一直陷于财务困境</i>\n\nsource-0733\n01:00:17.674 --> 01:00:20.997 align:middle line:100%,end position:50%,middle\n<i>这是一本很出色的杂志\n它市值被低估</i>\n\nsource-0734\n01:00:21.205 --> 01:00:22.664 align:middle line:100%,end position:50%,middle\n<i>这是笔好交易</i>\n\nsource-0735\n01:00:22.831 --> 01:00:25.000 align:middle line:100%,end position:50%,middle\n另一个原因是我不喜欢恶霸\n\nsource-0736\n01:00:25.167 --> 01:00:26.960 align:middle line:100%,end position:50%,middle\n你指温纳斯壮？\n\nsource-0737\n01:00:27.127 --> 01:00:30.964 align:middle line:100%,end position:50%,middle\n我指用官司逼敌人屈服的人\n\nsource-0738\n01:00:31.131 --> 01:00:33.550 align:middle line:0%,start position:50%,middle\n<i>如果温纳斯壮再找上门</i>\n\nsource-0739\n01:00:33.717 --> 01:00:37.137 align:middle line:0%,start position:50%,middle\n<i>他会碰上一家\n有钱还击的公司</i>\n\nsource-0740\n01:00:37.304 --> 01:00:41.016 align:middle line:100%,end position:50%,middle\n<i>我一直敬佩亨利·范耶尔\n他是商界巨擘，也是绅士</i>\n\nsource-0741\n01:00:41.183 --> 01:00:43.101 align:middle line:100%,end position:50%,middle\n<i>他究竟年纪大了</i>\n\nsource-0742\n01:00:43.268 --> 01:00:46.855 align:middle line:100%,end position:50%,middle\n<i>所以才会被一个\n已判罪的骗子蒙蔽</i>\n\nsource-0743\n01:00:47.022 --> 01:00:48.774 align:middle line:100%,end position:50%,middle\n3块2角\n\nsource-0744\n01:00:56.249 --> 01:00:58.883 align:middle line:100%,end position:50%,middle\n（主旨 范耶尔/布隆维斯特）\n\nsource-0745\n01:01:01.073 --> 01:01:02.306 align:middle line:100%,end position:50%,middle\n（有谁可以跟我解释…）\n\nsource-0746\n01:01:02.507 --> 01:01:04.029 align:middle line:100%,end position:50%,middle\n（那两个混蛋在搞啥吗？）\n\nsource-0747\n01:01:06.416 --> 01:01:08.210 align:middle line:100%,end position:50%,middle\n妈的\n\nsource-0748\n01:01:36.441 --> 01:01:38.000 align:middle line:100%,end position:50%,middle\n（海莉）\n\nsource-0749\n01:01:39.279 --> 01:01:40.439 align:middle line:100%,end position:50%,middle\n（阿妮塔）\n\nsource-0750\n01:02:06.318 --> 01:02:07.809 align:middle line:100%,end position:50%,middle\n（《赫德史塔新报》）\n\nsource-0751\n01:02:49.311 --> 01:02:51.480 align:middle line:100%,end position:50%,middle\n<i>现在的照片都存在光盘</i>\n\nsource-0752\n01:02:51.647 --> 01:02:54.066 align:middle line:100%,end position:50%,middle\n<i>旧照片则保存底片</i>\n\nsource-0753\n01:02:54.233 --> 01:02:56.527 align:middle line:100%,end position:50%,middle\n你想看哪个年代？\n\nsource-0754\n01:02:56.693 --> 01:02:58.278 align:middle line:100%,end position:50%,middle\n1966年9月\n\nsource-0755\n01:03:01.114 --> 01:03:02.616 align:middle line:100%,end position:50%,middle\n谢谢\n\nsource-0756\n01:03:08.372 --> 01:03:09.748 align:middle line:100%,end position:50%,middle\n跟海莉范耶尔有关？\n\nsource-0757\n01:03:10.541 --> 01:03:12.251 align:middle line:100%,end position:50%,middle\n你那时还没出生吧？\n\nsource-0758\n01:03:12.417 --> 01:03:15.295 align:middle line:100%,end position:50%,middle\n在这里长大的都知道海莉的事\n\nsource-0759\n01:03:16.964 --> 01:03:19.216 align:middle line:100%,end position:50%,middle\n大人教我们“要小心陌生人”\n\nsource-0760\n01:03:26.682 --> 01:03:29.476 align:middle line:100%,end position:50%,middle\n- 莉丝\n- 我要付房租\n\nsource-0761\n01:03:30.477 --> 01:03:31.728 align:middle line:100%,end position:50%,middle\n我需要钱\n\nsource-0762\n01:03:32.813 --> 01:03:34.898 align:middle line:100%,end position:50%,middle\n进来吧\n\nsource-0763\n01:03:41.613 --> 01:03:45.200 align:middle line:100%,end position:50%,middle\n上次不欢而散，我有点过意不去\n\nsource-0764\n01:03:45.367 --> 01:03:46.660 align:middle line:100%,end position:50%,middle\n我也觉得\n\nsource-0765\n01:04:34.208 --> 01:04:36.293 align:middle line:100%,end position:50%,middle\n很好 你还活着\n\nsource-0766\n01:04:40.088 --> 01:04:43.467 align:middle line:100%,end position:50%,middle\n认得这袋子吗？上次我把它放这\n\nsource-0767\n01:04:44.343 --> 01:04:46.720 align:middle line:100%,end position:50%,middle\n这其实不是钮扣\n\nsource-0768\n01:04:46.887 --> 01:04:49.765 align:middle line:100%,end position:50%,middle\n是广角光纤镜头\n\nsource-0769\n01:05:08.325 --> 01:05:10.577 align:middle line:100%,end position:50%,middle\n本以为你又要我吹喇叭\n\nsource-0770\n01:05:10.744 --> 01:05:12.955 align:middle line:100%,end position:50%,middle\n那已经够恶心了\n\nsource-0771\n01:05:13.121 --> 01:05:15.916 align:middle line:100%,end position:50%,middle\n但我低估了你有多变态\n\nsource-0772\n01:05:17.723 --> 01:05:18.707 align:middle line:100%,end position:50%,middle\n（消音）\n\nsource-0773\n01:05:26.635 --> 01:05:29.721 align:middle line:100%,end position:50%,middle\n计划是这样的\n\nsource-0774\n01:05:51.994 --> 01:05:54.037 align:middle line:100%,end position:50%,middle\n仔细听好\n\nsource-0775\n01:05:54.204 --> 01:05:55.414 align:middle line:100%,end position:50%,middle\n看着我\n\nsource-0776\n01:05:57.666 --> 01:05:59.293 align:middle line:100%,end position:50%,middle\n等你可以坐\n\nsource-0777\n01:05:59.459 --> 01:06:02.588 align:middle line:100%,end position:50%,middle\n不过可能要等一阵子\n我们去我的银行\n\nsource-0778\n01:06:02.754 --> 01:06:05.382 align:middle line:100%,end position:50%,middle\n告诉他们，只有我能动用我的钱\n\nsource-0779\n01:06:05.549 --> 01:06:08.760 align:middle line:100%,end position:50%,middle\n点头\n以后别再找我\n\nsource-0780\n01:06:09.178 --> 01:06:12.890 align:middle line:100%,end position:50%,middle\n每个月写份会面报告\n虽然我们根本不会见面\n\nsource-0781\n01:06:13.974 --> 01:06:16.101 align:middle line:100%,end position:50%,middle\n说明我一切正常、行为良好\n\nsource-0782\n01:06:16.268 --> 01:06:20.105 align:middle line:100%,end position:50%,middle\n我变得多“合群”\n然后你去跟法院协商\n\nsource-0783\n01:06:20.272 --> 01:06:22.774 align:middle line:100%,end position:50%,middle\n撤销我无行为能力的认定\n\nsource-0784\n01:06:22.941 --> 01:06:26.945 align:middle line:0%,start position:50%,middle\n否则这段视频\n会像病毒一样在网上传播\n\nsource-0785\n01:06:27.112 --> 01:06:28.572 align:middle line:100%,end position:50%,middle\n点头\n\nsource-0786\n01:06:29.698 --> 01:06:33.243 align:middle line:100%,end position:50%,middle\n万一我出意外\n像是被车撞\n\nsource-0787\n01:06:33.410 --> 01:06:37.080 align:middle line:100%,end position:50%,middle\n要是你开车撞我\n视频就会自动上传\n\nsource-0788\n01:06:37.497 --> 01:06:39.625 align:middle line:100%,end position:50%,middle\n懂就点头\n\nsource-0789\n01:06:43.086 --> 01:06:44.922 align:middle line:100%,end position:50%,middle\n喔 又是斜纹呢\n\nsource-0790\n01:06:45.339 --> 01:06:49.092 align:middle line:100%,end position:50%,middle\n钥匙我带走 因为我会盯着你\n\nsource-0791\n01:06:49.259 --> 01:06:54.181 align:middle line:100%,end position:50%,middle\n只要有其他女孩来这 就算自愿…\n\nsource-0792\n01:06:56.225 --> 01:06:58.101 align:middle line:100%,end position:50%,middle\n不 不是影片\n\nsource-0793\n01:07:06.777 --> 01:07:08.320 align:middle line:100%,end position:50%,middle\n我会杀了你\n\nsource-0794\n01:07:10.030 --> 01:07:11.949 align:middle line:100%,end position:50%,middle\n你怀疑我说的话吗？\n\nsource-0795\n01:07:12.658 --> 01:07:16.620 align:middle line:100%,end position:50%,middle\n不相信那些伴随我一生的报告？\n\nsource-0796\n01:07:16.787 --> 01:07:20.165 align:middle line:100%,end position:50%,middle\n报告上怎么说的？\n用一句话概括\n\nsource-0797\n01:07:20.332 --> 01:07:21.542 align:middle line:100%,end position:50%,middle\n他们说我是疯子\n\nsource-0798\n01:07:23.126 --> 01:07:26.421 align:middle line:100%,end position:50%,middle\n点头没关系 因为这是真的\n\nsource-0799\n01:07:27.339 --> 01:07:28.882 align:middle line:100%,end position:50%,middle\n我的确是疯子\n\nsource-0800\n01:07:30.843 --> 01:07:32.302 align:middle line:100%,end position:50%,middle\n点头！\n\nsource-0801\n01:07:34.221 --> 01:07:37.599 align:middle line:100%,end position:50%,middle\n我知道要你遵守我的规矩有点难\n\nsource-0802\n01:07:37.766 --> 01:07:39.685 align:middle line:100%,end position:50%,middle\n尤其是禁欲那条\n\nsource-0803\n01:07:42.104 --> 01:07:44.189 align:middle line:100%,end position:50%,middle\n所以让我来帮你\n\nsource-0804\n01:07:56.743 --> 01:07:57.786 align:middle line:100%,end position:50%,middle\n躺好！\n\nsource-0805\n01:07:57.953 --> 01:07:59.913 align:middle line:100%,end position:50%,middle\n这是我第一次做\n\nsource-0806\n01:08:00.080 --> 01:08:02.165 align:middle line:100%,end position:50%,middle\n会流血\n\nsource-0807\n01:09:14.461 --> 01:09:17.328 align:middle line:100%,end position:50%,middle\n（我是强奸犯 猪猡）\n\nsource-0808\n01:09:27.626 --> 01:09:29.377 align:middle line:100%,end position:50%,middle\n- 嗨\n- 嗨\n\nsource-0809\n01:09:29.877 --> 01:09:31.046 align:middle line:100%,end position:50%,middle\n你怎么来了？\n\nsource-0810\n01:09:31.212 --> 01:09:34.633 align:middle line:100%,end position:50%,middle\n我要去谢莱夫特奥\n只能待两个小时\n\nsource-0811\n01:09:36.468 --> 01:09:38.386 align:middle line:100%,end position:50%,middle\n去那做什么？\n\nsource-0812\n01:09:39.304 --> 01:09:40.346 align:middle line:100%,end position:50%,middle\n参加圣经夏令营\n\nsource-0813\n01:09:42.140 --> 01:09:43.725 align:middle line:100%,end position:50%,middle\n是吗？\n\nsource-0814\n01:10:04.204 --> 01:10:05.330 align:middle line:100%,end position:50%,middle\n我不危险\n\nsource-0815\n01:10:05.497 --> 01:10:09.501 align:middle line:100%,end position:50%,middle\n没关系，妮拉\n你想做什么都可以\n\nsource-0816\n01:10:09.668 --> 01:10:11.378 align:middle line:100%,end position:50%,middle\n每个人都有需要\n\nNATIVE-016\n01:10:11.545 --> 01:10:14.923 align:middle line:100%,end position:50%,middle\n- 只要不是上帝\n- 我可没这么说\n\nsource-0819\n01:10:18.510 --> 01:10:21.722 align:middle line:100%,end position:50%,middle\n我陪你的时间不够\n不是很了解你\n\nsource-0820\n01:10:24.433 --> 01:10:28.896 align:middle line:100%,end position:50%,middle\n我觉得抱歉\n但我不希望你对我有所隐瞒\n\nsource-0821\n01:10:29.062 --> 01:10:31.398 align:middle line:100%,end position:50%,middle\n只因为你认为\n我会不想听\n\nsource-0822\n01:10:32.399 --> 01:10:34.193 align:middle line:100%,end position:50%,middle\n我正是这样\n\nsource-0823\n01:10:35.360 --> 01:10:36.987 align:middle line:100%,end position:50%,middle\n<i>应该我去看你才对</i>\n\nsource-0824\n01:10:37.154 --> 01:10:39.031 align:middle line:100%,end position:50%,middle\n- 我很抱歉\n- 没关系\n\nsource-0825\n01:10:39.198 --> 01:10:41.283 align:middle line:100%,end position:50%,middle\n很高兴见到你\n\nsource-0826\n01:10:41.658 --> 01:10:43.118 align:middle line:100%,end position:50%,middle\n拜拜\n\nsource-0827\n01:10:43.535 --> 01:10:45.120 align:middle line:100%,end position:50%,middle\n- 再见\n- 嗯\n\nsource-0828\n01:10:45.287 --> 01:10:46.413 align:middle line:100%,end position:50%,middle\n谢谢\n\nsource-0829\n01:10:49.333 --> 01:10:51.251 align:middle line:100%,end position:50%,middle\n对了 别对天主教徒太严厉\n\nsource-0830\n01:10:51.418 --> 01:10:53.420 align:middle line:100%,end position:50%,middle\n- 什么？\n- 你正在写的文章\n\nsource-0831\n01:10:53.587 --> 01:10:55.714 align:middle line:100%,end position:50%,middle\n我没有在写天主教徒的文章\n\nsource-0832\n01:10:55.881 --> 01:10:58.717 align:middle line:100%,end position:50%,middle\n你桌旁那段《圣经》的节录\n\nsource-0833\n01:10:59.092 --> 01:11:00.385 align:middle line:100%,end position:50%,middle\n<i>我爱你</i>\n\nsource-0834\n01:11:25.838 --> 01:11:27.834 align:middle line:100%,end position:50%,middle\n（《利未记》 第三、四章）\n\nsource-0835\n01:11:37.965 --> 01:11:40.676 align:middle line:100%,end position:50%,middle\n<i>女人若是灵媒或女巫</i>\n\nsource-0836\n01:11:40.843 --> 01:11:43.846 align:middle line:100%,end position:50%,middle\n<i>必用石头把她打死</i>\n\nsource-0837\n01:11:44.429 --> 01:11:46.890 align:middle line:100%,end position:50%,middle\n<i>若以鸽为燔祭</i>\n\nsource-0838\n01:11:47.057 --> 01:11:50.602 align:middle line:100%,end position:50%,middle\n<i>祭司要扭下它的头\n剖开它的翅膀</i>\n\nsource-0839\n01:11:50.769 --> 01:11:52.896 align:middle line:100%,end position:50%,middle\n<i>再放到祭坛上焚烧</i>\n\nsource-0840\n01:11:55.482 --> 01:11:58.318 align:middle line:100%,end position:50%,middle\n<i>- 喂？</i>\n- 莫瑞尔警探，我是麦可·布隆维斯特\n\nsource-0841\n01:11:58.485 --> 01:11:59.862 align:middle line:100%,end position:50%,middle\n<i>最近好吗？</i>\n\nsource-0842\n01:12:00.028 --> 01:12:02.656 align:middle line:100%,end position:50%,middle\n<i>希望赫德史塔没那么冷了</i>\n\nsource-0843\n01:12:02.823 --> 01:12:05.826 align:middle line:100%,end position:50%,middle\n上次你提到蕾贝卡的案子\n\nsource-0844\n01:12:05.993 --> 01:12:07.578 align:middle line:100%,end position:50%,middle\n<i>能想起她的姓吗？</i>\n\nsource-0845\n01:12:07.744 --> 01:12:10.330 align:middle line:100%,end position:50%,middle\n当然，不过这跟那件事有什么关系？\n\nsource-0846\n01:12:10.497 --> 01:12:13.083 align:middle line:100%,end position:50%,middle\n- 可能没有吧\n<i>- 蕾贝卡雅各松</i>\n\nsource-0847\n01:12:13.250 --> 01:12:14.386 align:middle line:100%,end position:50%,middle\n（RJ 30114）\n\nsource-0848\n01:12:15.961 --> 01:12:17.629 align:middle line:100%,end position:50%,middle\n<i>她怎么死的？</i>\n\nsource-0849\n01:12:17.796 --> 01:12:19.756 align:middle line:100%,end position:50%,middle\n头被人砍掉\n\nsource-0850\n01:12:19.923 --> 01:12:22.342 align:middle line:100%,end position:50%,middle\n<i>手臂被砍掉，尸体被烧毁</i>\n\nsource-0851\n01:12:22.509 --> 01:12:26.138 align:middle line:100%,end position:50%,middle\n<i>但都是1940年代的事</i>\n\nsource-0852\n01:12:27.431 --> 01:12:29.600 align:middle line:100%,end position:50%,middle\n<i>- 你发现了什么？</i>\n- 我再回你电话\n\nsource-0853\n01:12:29.766 --> 01:12:30.809 align:middle line:100%,end position:50%,middle\n<i>怎么了？</i>\n\nsource-0854\n01:12:44.156 --> 01:12:45.657 align:middle line:100%,end position:50%,middle\n- 亨利吗？\n- 我们正在聊天\n\nF783\n01:12:45.824 --> 01:12:48.452 align:middle line:100%,end position:50%,middle\n- 他揉了揉胳膊就倒下了\n- 他会没事吗？\n\nF784\n01:12:48.619 --> 01:12:50.245 align:middle line:100%,end position:50%,middle\n老实说，我不知道\n\nsource-0857\n01:12:50.551 --> 01:12:52.311 align:middle line:100%,end position:50%,middle\n- 你快去吧 晚点再联络\n- 抱歉\n\nsource-0858\n01:13:04.051 --> 01:13:05.093 align:middle line:100%,end position:50%,middle\n晚安\n\nsource-0859\n01:13:07.471 --> 01:13:09.556 align:middle line:100%,end position:50%,middle\n亨利怎么样？\n\nsource-0860\n01:13:09.723 --> 01:13:12.267 align:middle line:100%,end position:50%,middle\n好消息是他还活着\n\nsource-0861\n01:13:12.434 --> 01:13:14.311 align:middle line:100%,end position:50%,middle\n不过状况如何要再观察\n\nsource-0862\n01:13:15.062 --> 01:13:17.856 align:middle line:100%,end position:50%,middle\n- 他在重症监护室\n- 好\n\nsource-0863\n01:13:20.025 --> 01:13:22.361 align:middle line:100%,end position:50%,middle\n- 我可以来一些吗？\n- 三明治？\n\nsource-0864\n01:13:22.528 --> 01:13:25.447 align:middle line:100%,end position:50%,middle\n- 威士忌\n- 没问题\n\nsource-0865\n01:13:29.576 --> 01:13:31.245 align:middle line:100%,end position:50%,middle\n谢谢\n\nsource-0866\n01:13:31.703 --> 01:13:35.082 align:middle line:100%,end position:50%,middle\n我不想失礼，但亨利答应过我\n\nsource-0867\n01:13:35.249 --> 01:13:37.459 align:middle line:100%,end position:50%,middle\n- 就在我答应接手这事时\n- 温纳斯壮\n\nsource-0868\n01:13:37.626 --> 01:13:40.587 align:middle line:100%,end position:50%,middle\n我得知道他有什么把柄\n现在就要，万一…\n\nsource-0869\n01:13:40.754 --> 01:13:42.214 align:middle line:100%,end position:50%,middle\n他死了？\n\nsource-0870\n01:13:42.381 --> 01:13:45.217 align:middle line:100%,end position:50%,middle\n- 确实不是时候\n- 抱歉\n\nsource-0871\n01:13:45.384 --> 01:13:47.928 align:middle line:100%,end position:50%,middle\n我不知道他掌握了什么\n\nsource-0872\n01:13:48.095 --> 01:13:52.349 align:middle line:100%,end position:50%,middle\n但他现在没办法说话 所以…\n\nsource-0873\n01:13:53.100 --> 01:13:57.020 align:middle line:100%,end position:50%,middle\n我们也没谈过如果他出事\n我该向谁报告\n\nsource-0874\n01:13:57.187 --> 01:13:59.106 align:middle line:100%,end position:50%,middle\n向我报告\n\nsource-0875\n01:13:59.940 --> 01:14:03.193 align:middle line:100%,end position:50%,middle\n我们都知道不会有结果 对吧？\n\nsource-0876\n01:14:04.111 --> 01:14:07.531 align:middle line:100%,end position:50%,middle\n- 还很难说\n- 什么意思？\n\nsource-0877\n01:14:08.657 --> 01:14:11.201 align:middle line:100%,end position:50%,middle\n- 我可能找到了某样新证据\n- 你在开玩笑\n\nsource-0878\n01:14:11.743 --> 01:14:12.953 align:middle line:100%,end position:50%,middle\n你发现了什么？\n\nsource-0879\n01:14:13.996 --> 01:14:17.499 align:middle line:100%,end position:50%,middle\n上次报道未百分百确认的事\n\nsource-0880\n01:14:17.666 --> 01:14:19.835 align:middle line:100%,end position:50%,middle\n让我老本都丢了\n\nsource-0881\n01:14:20.002 --> 01:14:22.629 align:middle line:100%,end position:50%,middle\n我需要调查助理 你能作主吗？\n\nsource-0882\n01:14:22.796 --> 01:14:26.049 align:middle line:100%,end position:50%,middle\n可以 有人选吗？\n\nsource-0883\n01:14:26.216 --> 01:14:28.218 align:middle line:100%,end position:50%,middle\n- 我可以找找\n- 我知道一位绝佳人选\n\nNATIVE-017\n01:14:28.385 --> 01:14:31.388 align:middle line:100%,end position:50%,middle\n- 她替你做过背景调查\n- 什么？\n\nsource-0886\n01:14:31.555 --> 01:14:34.057 align:middle line:100%,end position:50%,middle\n我们得先调查身家\n\nsource-0887\n01:14:34.224 --> 01:14:36.727 align:middle line:100%,end position:50%,middle\n才敢请你\n\nsource-0888\n01:14:37.102 --> 01:14:38.395 align:middle line:100%,end position:50%,middle\n我要看报告\n\nsource-0889\n01:14:39.021 --> 01:14:42.149 align:middle line:100%,end position:50%,middle\n佛洛德先生很好心\n把那份报告给我看了\n\nsource-0890\n01:14:42.316 --> 01:14:44.526 align:middle line:100%,end position:50%,middle\n这是调查员名字 对吧？\n\nsource-0891\n01:14:45.611 --> 01:14:49.489 align:middle line:100%,end position:50%,middle\n我查不到她任何纪录\n而我通常还蛮行的\n\nsource-0892\n01:14:49.990 --> 01:14:53.243 align:middle line:100%,end position:50%,middle\n- 她叫什么有关系吗？\n- 我想跟她谈谈，当然有\n\nsource-0893\n01:14:53.410 --> 01:14:55.412 align:middle line:100%,end position:50%,middle\n- 这违反公司规定\n- 是吗？\n\nNATIVE-018\n01:14:55.579 --> 01:14:58.790 align:middle line:100%,end position:50%,middle\n- 就像你得保护消息来源，你懂的\n- 好吧\n\nsource-0896\n01:14:59.875 --> 01:15:02.252 align:middle line:100%,end position:50%,middle\n给你一个名字\n\nsource-0897\n01:15:02.419 --> 01:15:03.545 align:middle line:100%,end position:50%,middle\n我妹妹\n\nsource-0898\n01:15:03.712 --> 01:15:05.339 align:middle line:100%,end position:50%,middle\n也是我律师\n\nsource-0899\n01:15:05.506 --> 01:15:07.007 align:middle line:100%,end position:50%,middle\n她会和你联络\n\nsource-0900\n01:15:07.174 --> 01:15:10.969 align:middle line:100%,end position:50%,middle\n这份报告有些内容\n只可能来自同一个地方\n\nsource-0901\n01:15:14.014 --> 01:15:18.018 align:middle line:100%,end position:50%,middle\n你查不到是因为她资料受到保护\n\nsource-0902\n01:15:18.185 --> 01:15:21.772 align:middle line:100%,end position:50%,middle\n- 她现在受政府监护\n- 那和我见她有什么关系？\n\nsource-0903\n01:15:22.648 --> 01:15:24.191 align:middle line:100%,end position:50%,middle\n她的人生已经够惨了\n\nsource-0904\n01:15:25.609 --> 01:15:28.862 align:middle line:100%,end position:50%,middle\n希望你别为难她\n\nsource-0905\n01:16:39.558 --> 01:16:41.310 align:middle line:100%,end position:50%,middle\n谁？\n\nsource-0906\n01:16:41.476 --> 01:16:43.312 align:middle line:100%,end position:50%,middle\n麦可布隆维斯特\n\nNATIVE-019\n01:16:47.816 --> 01:16:51.612 align:middle line:100%,end position:50%,middle\n- 我其实还没起床\n- 我可以进来吗？拜托\n\nsource-0909\n01:16:58.160 --> 01:17:01.788 align:middle line:100%,end position:50%,middle\n嗨，我们得谈谈\n我买了早…\n\nsource-0910\n01:17:01.955 --> 01:17:04.416 align:middle line:100%,end position:50%,middle\n抱歉 我不知道还有别人\n\nsource-0911\n01:17:04.583 --> 01:17:06.502 align:middle line:100%,end position:50%,middle\n你以为你是谁？\n\nsource-0912\n01:17:06.668 --> 01:17:09.463 align:middle line:100%,end position:50%,middle\n你比我最亲近的朋友\n还了解我\n\nsource-0913\n01:17:11.340 --> 01:17:15.344 align:middle line:100%,end position:50%,middle\n何不先穿好衣服 请你女友闪人\n\nsource-0914\n01:17:15.511 --> 01:17:17.429 align:middle line:100%,end position:50%,middle\n我们得谈谈\n\nsource-0915\n01:17:26.480 --> 01:17:28.524 align:middle line:100%,end position:50%,middle\n抱歉，你得先走了\n\nsource-0916\n01:17:28.690 --> 01:17:30.400 align:middle line:100%,end position:50%,middle\n好吧\n\nsource-0917\n01:17:45.457 --> 01:17:47.501 align:middle line:100%,end position:50%,middle\n要我留下吗？\n\nsource-0918\n01:17:48.126 --> 01:17:49.169 align:middle line:100%,end position:50%,middle\n不用\n\nsource-0919\n01:17:56.510 --> 01:17:58.595 align:middle line:100%,end position:50%,middle\n- 掰\n- 掰\n\nsource-0920\n01:18:05.310 --> 01:18:06.353 align:middle line:100%,end position:50%,middle\n再见\n\nsource-0921\n01:18:06.520 --> 01:18:07.604 align:middle line:100%,end position:50%,middle\n- 不好意思\n- 没关系\n\nsource-0922\n01:18:14.278 --> 01:18:16.780 align:middle line:100%,end position:50%,middle\n突然出现吓到你了吧？\n\nsource-0923\n01:18:16.947 --> 01:18:19.241 align:middle line:100%,end position:50%,middle\n如果你碰我 我会让你好看\n\nsource-0924\n01:18:19.408 --> 01:18:20.909 align:middle line:100%,end position:50%,middle\n没这个必要\n\nsource-0925\n01:18:22.035 --> 01:18:24.913 align:middle line:100%,end position:50%,middle\n你的调查报告非常详尽\n\nsource-0926\n01:18:25.080 --> 01:18:28.125 align:middle line:100%,end position:50%,middle\n- 对我来说，读起来不太有趣\n- 本来就不是为了有趣\n\nsource-0927\n01:18:28.292 --> 01:18:30.919 align:middle line:100%,end position:50%,middle\n我作报道会试着娱乐读者\n\nsource-0928\n01:18:31.086 --> 01:18:33.005 align:middle line:100%,end position:50%,middle\n温纳斯壮不觉得\n\nsource-0929\n01:18:37.217 --> 01:18:40.470 align:middle line:100%,end position:50%,middle\n你老板阿曼斯基\n\nsource-0930\n01:18:40.637 --> 01:18:44.057 align:middle line:100%,end position:50%,middle\n说你只接感兴趣的案子\n\nsource-0931\n01:18:44.224 --> 01:18:46.727 align:middle line:100%,end position:50%,middle\n所以我想我该感到荣幸\n\nsource-0932\n01:18:47.477 --> 01:18:49.229 align:middle line:100%,end position:50%,middle\n你不坐？\n\nsource-0933\n01:18:50.063 --> 01:18:55.861 align:middle line:100%,end position:50%,middle\n他还说你负责“敏感”的案子\n\nsource-0934\n01:18:56.028 --> 01:18:59.948 align:middle line:100%,end position:50%,middle\n他用的字是“敏感”\n我会说是“非法”\n\nsource-0935\n01:19:00.115 --> 01:19:03.243 align:middle line:100%,end position:50%,middle\n因为你侵入我的电脑\n就是违法行为\n\nsource-0936\n01:19:03.410 --> 01:19:06.371 align:middle line:100%,end position:50%,middle\n但我不会采取任何行动\n我可以 但我不会\n\nsource-0937\n01:19:06.538 --> 01:19:09.166 align:middle line:100%,end position:50%,middle\n我跟你说个故事\n\nsource-0938\n01:19:09.333 --> 01:19:13.086 align:middle line:100%,end position:50%,middle\n如果你感兴趣\n也许会协助我深入调查\n\nsource-0939\n01:19:13.253 --> 01:19:16.381 align:middle line:100%,end position:50%,middle\n如果没有\n我会把碗盘洗干净 然后消失\n\nsource-0940\n01:19:17.424 --> 01:19:19.468 align:middle line:100%,end position:50%,middle\n吃吧\n\nsource-0941\n01:19:20.219 --> 01:19:21.678 align:middle line:100%,end position:50%,middle\n什么样的调查？\n\nsource-0942\n01:19:22.262 --> 01:19:24.348 align:middle line:100%,end position:50%,middle\n莉丝，我能叫你莉丝吗？\n\nsource-0943\n01:19:26.266 --> 01:19:28.435 align:middle line:100%,end position:50%,middle\n帮我找出这个专杀女性的凶手\n\nsource-0944\n01:19:30.229 --> 01:19:31.313 align:middle line:100%,end position:50%,middle\n<i>已确认死者RJ</i>\n\nsource-0945\n01:19:31.480 --> 01:19:33.899 align:middle line:100%,end position:50%,middle\n蕾贝卡·雅各松\n其他人我毫无头绪\n\nsource-0946\n01:19:34.066 --> 01:19:36.693 align:middle line:100%,end position:50%,middle\n不知道她们是谁，彼此有什么关联\n\nsource-0947\n01:19:36.860 --> 01:19:39.863 align:middle line:100%,end position:50%,middle\n和一个16岁女孩的死有何关系\n但一定有关联\n\nsource-0948\n01:19:40.030 --> 01:19:43.283 align:middle line:100%,end position:50%,middle\n所以我们得查出她们是谁\n遭遇了什么\n\nsource-0949\n01:19:43.450 --> 01:19:47.913 align:middle line:100%,end position:50%,middle\n还有这些《利未记》经文\n与这一切有什么关系\n\nsource-0950\n01:19:49.873 --> 01:19:51.625 align:middle line:100%,end position:50%,middle\n- 你在做什么？\n- 开始调查\n\nsource-0951\n01:19:51.792 --> 01:19:55.420 align:middle line:100%,end position:50%,middle\n- 你可以继续讲\n- 你不先看这些资料？\n\nsource-0952\n01:19:55.587 --> 01:19:57.214 align:middle line:100%,end position:50%,middle\n我都记得\n\nsource-0953\n01:20:11.658 --> 01:20:13.923 align:middle line:100%,end position:50%,middle\n（强暴、砍头、肢解）\n\nsource-0954\n01:20:14.128 --> 01:20:16.596 align:middle line:100%,end position:50%,middle\n（焚烧、祭坛、祭司、妓女）\n\nsource-0955\n01:20:25.676 --> 01:20:27.871 align:middle line:100%,end position:50%,middle\n（状态悬案\n玛丽、玛妲）\n\nsource-0956\n01:20:32.317 --> 01:20:34.013 align:middle line:100%,end position:50%,middle\n（警方原始报告无电子文件）\n\nsource-0957\n01:20:42.509 --> 01:20:44.178 align:middle line:100%,end position:50%,middle\n猫咪！\n\nsource-0958\n01:21:13.832 --> 01:21:15.751 align:middle line:100%,end position:50%,middle\n你怎么进来的？\n\nsource-0959\n01:21:24.843 --> 01:21:27.179 align:middle line:100%,end position:50%,middle\n四十几年都没有人问起玛妲\n\nsource-0960\n01:21:27.367 --> 01:21:28.683 align:middle line:100%,end position:50%,middle\n（推荐信\n米尔顿安保公司）\n\nsource-0961\n01:21:28.847 --> 01:21:31.725 align:middle line:100%,end position:50%,middle\n为何要知道\n这么可怕的谋杀案？\n\nsource-0962\n01:21:31.892 --> 01:21:34.353 align:middle line:100%,end position:50%,middle\n- 我觉得很有意思\n- 有意思？\n\nsource-0963\n01:21:37.523 --> 01:21:39.566 align:middle line:100%,end position:50%,middle\n<i>她丈夫是第一个嫌疑人</i>\n\nsource-0964\n01:21:39.733 --> 01:21:42.986 align:middle line:100%,end position:50%,middle\n<i>丈夫都是第一个被怀疑的\n通常也就是凶手</i>\n\nsource-0965\n01:21:43.153 --> 01:21:46.573 align:middle line:100%,end position:50%,middle\n不过这次不是\n我们转而怀疑邻居\n\nsource-0966\n01:21:46.740 --> 01:21:48.575 align:middle line:100%,end position:50%,middle\n然后无业游民\n\nsource-0967\n01:21:48.742 --> 01:21:51.370 align:middle line:100%,end position:50%,middle\n当开始怀疑陌生人之后\n\nsource-0968\n01:21:51.537 --> 01:21:55.040 align:middle line:100%,end position:50%,middle\n下一个怀疑的就是吉普赛人\n接着你就知道永远不会有结果\n\nsource-0969\n01:21:55.207 --> 01:21:57.501 align:middle line:100%,end position:50%,middle\n她确切死因是？\n\nsource-0970\n01:21:58.374 --> 01:21:59.416 align:middle line:100%,end position:50%,middle\n- 莎…莎兰德小姐\n- 莎兰德\n\nsource-0971\n01:21:59.623 --> 01:22:03.364 align:middle line:100%,end position:50%,middle\n你上次吃东西是什么时候？\n\nsource-0972\n01:22:03.549 --> 01:22:06.134 align:middle line:100%,end position:50%,middle\n我代谢很好 吃不胖\n\nsource-0973\n01:22:06.301 --> 01:22:10.889 align:middle line:100%,end position:50%,middle\n因为我接下来要给你看的东西\n\nsource-0974\n01:22:11.056 --> 01:22:12.432 align:middle line:100%,end position:50%,middle\n胃最好是空的\n\nsource-0975\n01:22:15.727 --> 01:22:20.399 align:middle line:100%,end position:50%,middle\n<i>若献一只羊羔为供物\n必用没有残疾的母羊</i>\n\nsource-0976\n01:22:20.566 --> 01:22:22.609 align:middle line:100%,end position:50%,middle\n<i>并将手按在供物头上</i>\n\nsource-0977\n01:22:22.776 --> 01:22:26.029 align:middle line:100%,end position:50%,middle\n<i>屠宰它 任血流干于祭坛</i>\n\nsource-0978\n01:22:26.196 --> 01:22:28.198 align:middle line:100%,end position:50%,middle\n<i>然后此人便能得到救赎</i>\n\nsource-0979\n01:22:33.161 --> 01:22:35.080 align:middle line:100%,end position:50%,middle\n- 他状况怎么样？\n- 得动手术\n\nsource-0980\n01:22:35.247 --> 01:22:38.959 align:middle line:100%,end position:50%,middle\n但他没有拒绝心肺复苏的指示\n所以得由家人决定\n\nsource-0981\n01:22:39.126 --> 01:22:41.962 align:middle line:100%,end position:50%,middle\n到时依家人意思决定要不要急救\n\nsource-0982\n01:22:42.504 --> 01:22:45.299 align:middle line:100%,end position:50%,middle\n但他们不擅于做决定\n\nsource-0983\n01:22:45.465 --> 01:22:47.092 align:middle line:100%,end position:50%,middle\n莎兰德那边怎么样？\n\nsource-0984\n01:22:47.259 --> 01:22:50.220 align:middle line:100%,end position:50%,middle\n她答应了\n你认为我可以见他吗？\n\nsource-0985\n01:22:50.387 --> 01:22:53.348 align:middle line:100%,end position:50%,middle\n上次看他时他在睡觉\n我再去看看\n\nsource-0986\n01:22:53.515 --> 01:22:54.975 align:middle line:100%,end position:50%,middle\n- 谢谢\n- 不用去看了\n\nsource-0987\n01:22:55.392 --> 01:22:57.477 align:middle line:100%,end position:50%,middle\n叫他东西收一收离开\n\nsource-0988\n01:22:57.644 --> 01:23:00.063 align:middle line:100%,end position:50%,middle\n- 妈 别这样！\n- 别用那种口气对我说话\n\nsource-0989\n01:23:00.230 --> 01:23:02.858 align:middle line:100%,end position:50%,middle\n布隆维斯特先生替亨利工作\n\nsource-0990\n01:23:03.057 --> 01:23:05.647 align:middle line:100%,end position:50%,middle\n- 应该投票表决\n- 别犯傻了，毕耶\n\nsource-0991\n01:23:05.852 --> 01:23:08.113 align:middle line:100%,end position:50%,middle\n大家都知道亨利想要什么\n就照他的意思，好吗？\n\nsource-0992\n01:23:08.280 --> 01:23:11.783 align:middle line:100%,end position:50%,middle\n他正在和死神对抗 别去打扰他\n\nsource-0993\n01:23:11.950 --> 01:23:14.578 align:middle line:100%,end position:50%,middle\n不好意思 这里不能抽烟\n\nsource-0994\n01:23:17.289 --> 01:23:18.665 align:middle line:100%,end position:50%,middle\n回你的斯德哥尔摩\n\nsource-0995\n01:23:18.832 --> 01:23:22.878 align:middle line:100%,end position:50%,middle\n如果需要诽谤者替我们写家族史\n\nsource-0996\n01:23:23.420 --> 01:23:25.214 align:middle line:100%,end position:50%,middle\n我们知道该找谁\n\nsource-0997\n01:23:31.094 --> 01:23:33.514 align:middle line:100%,end position:50%,middle\n好的 谢谢\n\nsource-0998\n01:23:34.056 --> 01:23:36.183 align:middle line:100%,end position:50%,middle\n这里\n\nsource-0999\n01:23:40.020 --> 01:23:42.397 align:middle line:100%,end position:50%,middle\n<i>女人若与兽亲近</i>\n\nsource-1000\n01:23:42.564 --> 01:23:46.068 align:middle line:100%,end position:50%,middle\n<i>与它淫合 应当杀那女人与兽</i>\n\nsource-1001\n01:23:46.235 --> 01:23:48.362 align:middle line:100%,end position:50%,middle\n<i>罪要归到他们身上</i>\n\nsource-1002\n01:23:57.387 --> 01:23:59.940 align:middle line:100%,end position:50%,middle\n（毕耶范耶尔\n哈洛德之子）\n\nsource-1003\n01:24:01.792 --> 01:24:03.794 align:middle line:100%,end position:50%,middle\n<i>我家人真令人难以忍受</i>\n\nsource-1004\n01:24:03.961 --> 01:24:06.171 align:middle line:100%,end position:50%,middle\n这就是公司一团乱的原因\n\nsource-1005\n01:24:06.839 --> 01:24:09.383 align:middle line:100%,end position:50%,middle\n我为我母亲的行为道歉\n\nsource-1006\n01:24:09.550 --> 01:24:10.592 align:middle line:100%,end position:50%,middle\n我习惯了\n\nsource-1007\n01:24:10.759 --> 01:24:13.554 align:middle line:100%,end position:50%,middle\n和你无关 是她和亨利之间的事\n\nsource-1008\n01:24:13.720 --> 01:24:17.558 align:middle line:100%,end position:50%,middle\n父亲去世后，她失控了\n开始酗酒，还有她…\n\nsource-1009\n01:24:18.517 --> 01:24:22.354 align:middle line:100%,end position:50%,middle\n情况越来越糟\n于是亨利将我和妹妹带走\n\nsource-1010\n01:24:22.521 --> 01:24:26.024 align:middle line:100%,end position:50%,middle\n留她孤独一人在那间旧房子\n\nNATIVE-020\n01:24:26.191 --> 01:24:29.528 align:middle line:100%,end position:50%,middle\n在岛的另一端\n她一直没原谅过他\n\nsource-1013\n01:24:31.864 --> 01:24:33.448 align:middle line:100%,end position:50%,middle\n你一定得留下\n\nsource-1014\n01:24:34.032 --> 01:24:37.744 align:middle line:100%,end position:50%,middle\n你是完成亨利心愿的最后机会\n\nNATIVE-021\n01:24:37.911 --> 01:24:41.331 align:middle line:100%,end position:50%,middle\n总得让这件事了结\n我会让母亲别来干扰\n\nsource-1017\n01:24:41.498 --> 01:24:43.792 align:middle line:100%,end position:50%,middle\n但请你快一点\n\nsource-1018\n01:24:44.251 --> 01:24:45.335 align:middle line:100%,end position:50%,middle\n当然\n\nsource-1019\n01:24:58.140 --> 01:24:59.558 align:middle line:100%,end position:50%,middle\n莉丝\n\nsource-1020\n01:24:59.725 --> 01:25:01.435 align:middle line:100%,end position:50%,middle\n- 我来拿\n- 没关系\n\nsource-1021\n01:25:02.019 --> 01:25:03.687 align:middle line:100%,end position:50%,middle\n- 这是马丁范耶尔\n- 你好吗？\n\nsource-1022\n01:25:03.854 --> 01:25:05.480 align:middle line:100%,end position:50%,middle\n不错\n\nsource-1023\n01:25:10.068 --> 01:25:12.613 align:middle line:100%,end position:50%,middle\n- 你女友？\n- 助理\n\nsource-1024\n01:25:13.197 --> 01:25:14.364 align:middle line:100%,end position:50%,middle\n非常谢谢你\n\nsource-1025\n01:25:15.032 --> 01:25:17.284 align:middle line:100%,end position:50%,middle\n- 晚安\n- 晚安\n\nsource-1026\n01:25:21.580 --> 01:25:22.915 align:middle line:100%,end position:50%,middle\n还好找吗？\n\nsource-1027\n01:25:23.081 --> 01:25:25.167 align:middle line:100%,end position:50%,middle\n全镇都知道你是谁、住在哪\n\nsource-1028\n01:25:25.334 --> 01:25:28.253 align:middle line:100%,end position:50%,middle\n真令人感到欣慰\n饿了吗？帮你做个三明治\n\nsource-1029\n01:25:28.420 --> 01:25:29.588 align:middle line:100%,end position:50%,middle\n不用\n\nNATIVE-022\n01:25:31.298 --> 01:25:34.801 align:middle line:100%,end position:50%,middle\n- 我以前有辆凯旋摩托车\n- 我知道\n\nsource-1032\n01:25:34.968 --> 01:25:37.179 align:middle line:100%,end position:50%,middle\n海莉名单上的五件谋杀案\n\nsource-1033\n01:25:37.346 --> 01:25:39.890 align:middle line:100%,end position:50%,middle\n我还找到另外五件\n其中三件确定\n\nsource-1034\n01:25:40.641 --> 01:25:43.143 align:middle line:100%,end position:50%,middle\n蕾贝卡是第一个 如同你想的\n\nsource-1035\n01:25:43.310 --> 01:25:46.647 align:middle line:100%,end position:50%,middle\n第二个MH是玛丽·霍姆伯格\n卡尔马的妓女\n\nsource-1036\n01:25:46.813 --> 01:25:49.608 align:middle line:100%,end position:50%,middle\n1954年被杀\n对应《利未记》20章18节\n\nsource-1037\n01:25:49.775 --> 01:25:52.444 align:middle line:100%,end position:50%,middle\n没错\n“妇人有月经 若与她同房\n\nsource-1038\n01:25:52.611 --> 01:25:55.322 align:middle line:100%,end position:50%,middle\n就是露了妇人的血源\n\nsource-1039\n01:25:55.489 --> 01:25:56.907 align:middle line:100%,end position:50%,middle\n妇人也露了自己的血源”\n\nsource-1040\n01:25:57.074 --> 01:26:00.619 align:middle line:100%,end position:50%,middle\n遭强暴与刺伤 死因是窒息\n喉咙塞了一块卫生棉\n\nsource-1041\n01:26:01.119 --> 01:26:03.997 align:middle line:100%,end position:50%,middle\n- 好\n- RL是拉凯儿·伦德 1957年\n\nsource-1042\n01:26:04.164 --> 01:26:06.667 align:middle line:100%,end position:50%,middle\n一名清洁妇 兼职看手相\n\nsource-1043\n01:26:06.834 --> 01:26:10.379 align:middle line:100%,end position:50%,middle\n被人用晒衣绳捆绑 嘴被封住\n遭强暴 头颅遭石块击碎\n\nsource-1044\n01:26:10.546 --> 01:26:12.005 align:middle line:100%,end position:50%,middle\n《利未记》20：27节\n\nsource-1045\n01:26:12.172 --> 01:26:14.049 align:middle line:100%,end position:50%,middle\n“女人若是灵媒或女巫\n\nsource-1046\n01:26:14.216 --> 01:26:16.426 align:middle line:100%,end position:50%,middle\n必用石头将之打死”\n\nsource-1047\n01:26:16.593 --> 01:26:20.556 align:middle line:100%,end position:50%,middle\n- 我一般在外面抽烟\n- 莎拉·维特，1964年\n\nsource-1048\n01:26:20.722 --> 01:26:22.599 align:middle line:100%,end position:50%,middle\n牧师的女儿 被绑在自己床上\n\nsource-1049\n01:26:22.766 --> 01:26:25.435 align:middle line:100%,end position:50%,middle\n遭强暴 房子被放火 尸体焦黑\n\nsource-1050\n01:26:25.602 --> 01:26:26.854 align:middle line:100%,end position:50%,middle\n《利未记》21：9\n\nsource-1051\n01:26:27.020 --> 01:26:30.357 align:middle line:100%,end position:50%,middle\n“祭司的女儿若行淫辱没自己\n\nsource-1052\n01:26:30.524 --> 01:26:33.026 align:middle line:100%,end position:50%,middle\n就辱没了父亲 必用火将她焚烧”\n\nsource-1053\n01:26:33.193 --> 01:26:34.987 align:middle line:100%,end position:50%,middle\n玛妲·洛维萨·舍贝里，1960年\n\nsource-1054\n01:26:35.153 --> 01:26:37.573 align:middle line:100%,end position:50%,middle\n陈尸畜棚 被农具刺伤并强暴\n\nsource-1055\n01:26:37.739 --> 01:26:39.867 align:middle line:100%,end position:50%,middle\n旁边牛栏的母牛被割喉\n\nsource-1056\n01:26:40.033 --> 01:26:42.119 align:middle line:100%,end position:50%,middle\n血喷到她身上\n她的血也溅到它\n\nsource-1057\n01:26:42.286 --> 01:26:44.746 align:middle line:100%,end position:50%,middle\n《利未记》20：16\n“女人若与兽亲近 与它淫合\n\nsource-1058\n01:26:44.913 --> 01:26:48.333 align:middle line:100%,end position:50%,middle\n你要杀那女人和兽\n罪要归到他们身上”\n\nsource-1059\n01:26:48.500 --> 01:26:49.710 align:middle line:100%,end position:50%,middle\n莉亚·佩尔松 1962年\n\nsource-1060\n01:26:49.877 --> 01:26:52.838 align:middle line:100%,end position:50%,middle\n姐姐在她们的宠物店发现了她\n她遭到强奸、殴打\n\nsource-1061\n01:26:53.005 --> 01:26:55.591 align:middle line:100%,end position:50%,middle\n动物都被放出来 水族箱被砸烂\n\nsource-1062\n01:26:55.757 --> 01:26:57.551 align:middle line:100%,end position:50%,middle\n她体内被塞进了一只鹦鹉\n\nsource-1063\n01:26:58.051 --> 01:27:00.262 align:middle line:100%,end position:50%,middle\n接着是艾娃·古斯塔夫松 1960年\n\nsource-1064\n01:27:00.429 --> 01:27:04.725 align:middle line:100%,end position:50%,middle\n翘家女 被强暴后勒毙\n一只烧焦的鸽子绑在她脖子上\n\nsource-1065\n01:27:05.142 --> 01:27:09.104 align:middle line:100%,end position:50%,middle\n莉娜·安德松，1967年，学生\n遭强奸、刺伤、斩首…\n\nsource-1066\n01:27:09.271 --> 01:27:11.607 align:middle line:100%,end position:50%,middle\n- 够了\n- 我还没说完\n\nsource-1067\n01:27:11.773 --> 01:27:13.567 align:middle line:100%,end position:50%,middle\n我们在找一个连续杀人犯\n\nsource-1068\n01:27:13.734 --> 01:27:17.070 align:middle line:100%,end position:50%,middle\n可这和岛上一个少女\n有什么关系？\n\nsource-1069\n01:27:17.905 --> 01:27:20.073 align:middle line:100%,end position:50%,middle\n海莉也在找他\n\nsource-1070\n01:27:21.158 --> 01:27:22.534 align:middle line:100%,end position:50%,middle\n<i>强暴、虐待、焚烧</i>\n\nsource-1071\n01:27:22.701 --> 01:27:24.620 align:middle line:100%,end position:50%,middle\n动物、宗教\n\nsource-1072\n01:27:25.037 --> 01:27:27.039 align:middle line:100%,end position:50%,middle\n- 有遗漏什么吗？\n- 受害者名字\n\nsource-1073\n01:27:28.373 --> 01:27:29.625 align:middle line:100%,end position:50%,middle\n全是《圣经》中的名字\n\nsource-1074\n01:27:29.791 --> 01:27:32.252 align:middle line:100%,end position:50%,middle\n第一个女人、妓女、圣母玛利亚\n\nsource-1075\n01:27:32.419 --> 01:27:36.131 align:middle line:100%,end position:50%,middle\n蕾贝卡、莎拉 都来自《旧约全书》\n\nsource-1076\n01:27:36.298 --> 01:27:38.342 align:middle line:100%,end position:50%,middle\n这代表她们都是犹太人\n\nsource-1077\n01:27:40.219 --> 01:27:44.640 align:middle line:100%,end position:50%,middle\n范耶尔家族里\n有太多反犹太份子\n\nsource-1078\n01:27:47.226 --> 01:27:49.937 align:middle line:100%,end position:50%,middle\n那里就有一位\n\nsource-1079\n01:27:52.773 --> 01:27:54.858 align:middle line:100%,end position:50%,middle\n我可以睡沙发\n\nsource-1080\n01:27:55.651 --> 01:27:57.319 align:middle line:100%,end position:50%,middle\n那好\n\nsource-1081\n01:27:58.070 --> 01:27:59.112 align:middle line:100%,end position:50%,middle\n就这样吧\n\nsource-1082\n01:27:59.863 --> 01:28:03.617 align:middle line:100%,end position:50%,middle\n对了，这里可能有只猫\n\nsource-1083\n01:28:03.784 --> 01:28:05.244 align:middle line:100%,end position:50%,middle\n- 晚安\n- 晚安\n\nsource-1084\n01:28:05.410 --> 01:28:07.663 align:middle line:100%,end position:50%,middle\n海莉的名字不是…\n\nsource-1085\n01:28:09.289 --> 01:28:10.415 align:middle line:100%,end position:50%,middle\n不是什么？\n\nsource-1086\n01:28:11.416 --> 01:28:14.419 align:middle line:100%,end position:50%,middle\n- 犹太名字\n- 不是\n\nsource-1087\n01:28:42.406 --> 01:28:44.324 align:middle line:100%,end position:50%,middle\n- 你在干嘛？\n- 看你的笔记\n\nsource-1088\n01:28:44.491 --> 01:28:45.993 align:middle line:100%,end position:50%,middle\n这些笔记都加了密\n\nsource-1089\n01:28:46.159 --> 01:28:48.912 align:middle line:100%,end position:50%,middle\n少来，喝点咖啡吧\n\nsource-1090\n01:28:49.079 --> 01:28:50.163 align:middle line:100%,end position:50%,middle\n好\n\nsource-1091\n01:28:51.331 --> 01:28:53.750 align:middle line:100%,end position:50%,middle\n我们得好好谈谈\n\nsource-1092\n01:28:53.917 --> 01:28:56.170 align:middle line:100%,end position:50%,middle\n什么是你的 什么是我的\n\nsource-1093\n01:28:57.045 --> 01:28:59.715 align:middle line:100%,end position:50%,middle\n你在游行照片的发现很惊人\n\nsource-1094\n01:28:59.882 --> 01:29:01.550 align:middle line:100%,end position:50%,middle\n谢谢\n\nsource-1095\n01:29:02.176 --> 01:29:05.554 align:middle line:100%,end position:50%,middle\n- 可惜你没有她拍的照片\n- 谁？\n\nsource-1096\n01:29:06.597 --> 01:29:07.639 align:middle line:100%,end position:50%,middle\n她\n\nsource-1097\n01:29:11.852 --> 01:29:13.979 align:middle line:100%,end position:50%,middle\n我看一下？抱歉\n\nsource-1098\n01:29:15.022 --> 01:29:16.231 align:middle line:100%,end position:50%,middle\n好了\n\nsource-1099\n01:29:16.398 --> 01:29:17.816 align:middle line:100%,end position:50%,middle\n关起来\n\nsource-1100\n01:29:17.983 --> 01:29:19.276 align:middle line:100%,end position:50%,middle\n别关\n\nsource-1101\n01:29:20.194 --> 01:29:22.279 align:middle line:100%,end position:50%,middle\n就是这个\n\nsource-1102\n01:29:22.446 --> 01:29:27.034 align:middle line:100%,end position:50%,middle\n该死 跑哪去了？下面\n再来是…对\n\nsource-1103\n01:29:27.201 --> 01:29:28.869 align:middle line:100%,end position:50%,middle\n再来…\n\nsource-1104\n01:29:30.913 --> 01:29:33.081 align:middle line:100%,end position:50%,middle\n那写什么？\n\nsource-1105\n01:29:33.582 --> 01:29:36.919 align:middle line:100%,end position:50%,middle\n- N什么R-S-J\n- 是“诺斯约”\n\nsource-1106\n01:29:37.085 --> 01:29:40.255 align:middle line:100%,end position:50%,middle\n然后是个“K”\n再后面是“R-I-F”\n\nsource-1107\n01:29:40.422 --> 01:29:42.382 align:middle line:100%,end position:50%,middle\n木工\n\nsource-1108\n01:29:42.549 --> 01:29:45.302 align:middle line:100%,end position:50%,middle\n看来我们得找个木匠\n\nsource-1109\n01:29:47.763 --> 01:29:48.972 align:middle line:100%,end position:50%,middle\n操！\n\nsource-1110\n01:30:43.777 --> 01:30:47.155 align:middle line:100%,end position:50%,middle\n那家木工店不在了\n我不知道他是否在那工作过\n\nsource-1111\n01:30:47.322 --> 01:30:50.450 align:middle line:100%,end position:50%,middle\n但如果是的话\n也许他来买过五金用具\n\nsource-1112\n01:30:50.617 --> 01:30:52.744 align:middle line:100%,end position:50%,middle\n我不认得 抱歉\n\nsource-1113\n01:30:52.911 --> 01:30:55.581 align:middle line:100%,end position:50%,middle\n没关系 我总得从某地方着手\n\nsource-1114\n01:30:56.039 --> 01:31:01.587 align:middle line:100%,end position:50%,middle\n我不是探员 但1966年\n我会从养老院着手\n\nsource-1115\n01:31:08.468 --> 01:31:10.095 align:middle line:100%,end position:50%,middle\n这是布兰伦的孩子\n\nsource-1116\n01:31:10.262 --> 01:31:12.472 align:middle line:100%,end position:50%,middle\n知道哪里能找到他儿子吗？\n\nsource-1117\n01:31:12.639 --> 01:31:15.058 align:middle line:100%,end position:50%,middle\n他爸的墓地旁\n\nsource-1118\n01:31:15.225 --> 01:31:19.479 align:middle line:100%,end position:50%,middle\n他多年前在一场施工事故中丧生\n\nsource-1119\n01:31:21.231 --> 01:31:22.816 align:middle line:100%,end position:50%,middle\n但是…\n\nsource-1120\n01:31:24.526 --> 01:31:26.820 align:middle line:100%,end position:50%,middle\n遗孀可能还活着\n\nsource-1121\n01:31:27.613 --> 01:31:29.907 align:middle line:100%,end position:50%,middle\n你知道怎么找她吗？\n\nsource-1122\n01:31:37.956 --> 01:31:39.833 align:middle line:100%,end position:50%,middle\n<i>请开往标示道路</i>\n\nsource-1123\n01:31:40.751 --> 01:31:45.380 align:middle line:100%,end position:50%,middle\n1966年，你和丈夫在赫德史塔\n\nsource-1124\n01:31:46.882 --> 01:31:48.550 align:middle line:100%,end position:50%,middle\n这谁拍的？\n\nNATIVE-023\n01:31:48.717 --> 01:31:51.970 align:middle line:100%,end position:50%,middle\n当地一位摄影师\n你那天也拍了照片\n\nsource-1127\n01:31:52.137 --> 01:31:55.224 align:middle line:100%,end position:50%,middle\n若你还留着\n我想看看那些相片\n\nsource-1128\n01:31:55.390 --> 01:31:57.768 align:middle line:100%,end position:50%,middle\n我确实留着 当时我们在度蜜月\n\nsource-1129\n01:31:57.935 --> 01:31:59.645 align:middle line:100%,end position:50%,middle\n怎么了？\n\nsource-1130\n01:31:59.811 --> 01:32:04.107 align:middle line:100%,end position:50%,middle\n这个女孩\n放大照片就看得更清楚\n\nsource-1131\n01:32:04.274 --> 01:32:06.735 align:middle line:100%,end position:50%,middle\n看，这里是你\n这张照片拍下后不久\n\nsource-1132\n01:32:06.902 --> 01:32:10.489 align:middle line:100%,end position:50%,middle\n她在街对面看到了什么\n随后就遇害了\n\nsource-1133\n01:32:12.199 --> 01:32:14.409 align:middle line:100%,end position:50%,middle\n真可怕\n\nsource-1134\n01:32:24.711 --> 01:32:26.880 align:middle line:100%,end position:50%,middle\n- 就是这些\n- 谢谢\n\nNATIVE-024\n01:32:45.983 --> 01:32:48.861 align:middle line:100%,end position:50%,middle\n- 介意我复印一份吗？\n- 不介意\n\nsource-1137\n01:32:50.279 --> 01:32:53.907 align:middle line:100%,end position:50%,middle\n没有阿曼斯基先生的授权\n我不能给你任何东西\n\nsource-1138\n01:32:54.074 --> 01:32:55.742 align:middle line:100%,end position:50%,middle\n那就打给他\n\nsource-1139\n01:33:04.042 --> 01:33:06.753 align:middle line:100%,end position:50%,middle\n下次请填好正式表格\n\nsource-1140\n01:33:17.931 --> 01:33:19.224 align:middle line:100%,end position:50%,middle\n哪一个是你？\n\nsource-1141\n01:33:34.072 --> 01:33:35.741 align:middle line:100%,end position:50%,middle\n下楼\n\nsource-1142\n01:33:42.414 --> 01:33:44.458 align:middle line:100%,end position:50%,middle\n你的性生活还好吗？\n\nsource-1143\n01:33:46.084 --> 01:33:48.128 align:middle line:100%,end position:50%,middle\n我不太喜欢你上次的报告\n\nsource-1144\n01:33:48.295 --> 01:33:51.215 align:middle line:100%,end position:50%,middle\n写得很草率 没有用心\n\nsource-1145\n01:33:51.381 --> 01:33:54.510 align:middle line:100%,end position:50%,middle\n下月的报告要更热情一些\n多说说我的康复情况\n\nsource-1146\n01:33:54.676 --> 01:33:57.304 align:middle line:100%,end position:50%,middle\n别开口 我不想听到你的声音\n点头就行\n\nsource-1147\n01:33:57.471 --> 01:33:59.515 align:middle line:100%,end position:50%,middle\n去找个能贿赂的精神科医生\n\nsource-1148\n01:33:59.681 --> 01:34:03.519 align:middle line:100%,end position:50%,middle\n宣誓说我完全正常\n\nsource-1149\n01:34:03.685 --> 01:34:05.812 align:middle line:100%,end position:50%,middle\n别再浏览洗纹身的网站\n\nsource-1150\n01:34:06.188 --> 01:34:07.606 align:middle line:100%,end position:50%,middle\n否则我会再刺一次\n\nsource-1151\n01:34:09.149 --> 01:34:10.901 align:middle line:100%,end position:50%,middle\n在这里\n\nsource-1152\n01:34:36.588 --> 01:34:39.521 align:middle line:100%,end position:50%,middle\n（戈弗里范耶尔）\n\nsource-1153\n01:35:27.436 --> 01:35:29.595 align:middle line:100%,end position:50%,middle\n（海莉范耶尔）\n\nsource-1154\n01:36:58.902 --> 01:37:01.488 align:middle line:100%,end position:50%,middle\n- 那是牙线吗？\n- 对\n\nsource-1155\n01:37:05.033 --> 01:37:07.119 align:middle line:100%,end position:50%,middle\n你会消毒吧？\n\nsource-1156\n01:37:10.664 --> 01:37:13.000 align:middle line:100%,end position:50%,middle\n胶带或其他东西不行吗？\n\nsource-1157\n01:37:13.166 --> 01:37:14.543 align:middle line:100%,end position:50%,middle\n不行\n\nsource-1158\n01:37:15.878 --> 01:37:17.004 align:middle line:100%,end position:50%,middle\n什么？\n\nsource-1159\n01:37:19.798 --> 01:37:22.259 align:middle line:100%,end position:50%,middle\n谢谢\n天哪！\n\nsource-1160\n01:37:22.426 --> 01:37:25.053 align:middle line:100%,end position:50%,middle\n- 喝\n- 好\n\nsource-1161\n01:37:27.222 --> 01:37:28.932 align:middle line:100%,end position:50%,middle\n小心点 我的眼睛\n\nsource-1162\n01:37:29.099 --> 01:37:31.894 align:middle line:100%,end position:50%,middle\n- 别动\n- 你不是医生\n\nsource-1163\n01:37:45.824 --> 01:37:48.368 align:middle line:100%,end position:50%,middle\n- 脱掉湿衣服\n- 什么？\n\nsource-1164\n01:37:49.036 --> 01:37:51.705 align:middle line:100%,end position:50%,middle\n好 谢谢\n\nsource-1165\n01:37:53.749 --> 01:37:56.793 align:middle line:100%,end position:50%,middle\n我想它止血了\n\nsource-1166\n01:37:56.960 --> 01:37:59.671 align:middle line:100%,end position:50%,middle\n虽然还是他妈的很痛\n\nsource-1167\n01:38:04.176 --> 01:38:05.260 align:middle line:100%,end position:50%,middle\n这太疯狂了\n\nsource-1168\n01:38:13.227 --> 01:38:16.313 align:middle line:100%,end position:50%,middle\n这一切都他妈的太疯狂了\n\nsource-1169\n01:38:18.440 --> 01:38:21.693 align:middle line:100%,end position:50%,middle\n没事了，你没事了，没事了\n\nsource-1170\n01:38:25.531 --> 01:38:28.200 align:middle line:100%,end position:50%,middle\n痛 该死！\n\nsource-1171\n01:38:34.248 --> 01:38:37.793 align:middle line:100%,end position:50%,middle\n这太疯狂了，我是说那些人…\n\nsource-1172\n01:38:38.252 --> 01:38:41.505 align:middle line:100%,end position:50%,middle\n有人向我开枪 这并非意外\n\nsource-1173\n01:38:41.672 --> 01:38:43.632 align:middle line:100%,end position:50%,middle\n现在没人向你开枪\n\nsource-1174\n01:38:47.052 --> 01:38:49.137 align:middle line:100%,end position:50%,middle\n这不是好主意\n\nsource-1175\n01:38:49.304 --> 01:38:50.389 align:middle line:100%,end position:50%,middle\n为什么？\n\nsource-1176\n01:38:50.556 --> 01:38:52.599 align:middle line:100%,end position:50%,middle\n我年纪大，我们还一起工作…\n\nsource-1177\n01:38:52.766 --> 01:38:55.060 align:middle line:100%,end position:50%,middle\n你也和那女人一起工作\n不也相处得挺好？\n\nsource-1178\n01:38:55.227 --> 01:38:58.522 align:middle line:100%,end position:50%,middle\n我还是有原则的\n随你信不信\n\nsource-1179\n01:38:59.314 --> 01:39:00.691 align:middle line:100%,end position:50%,middle\n你需要闭嘴\n\nsource-1180\n01:39:09.408 --> 01:39:11.118 align:middle line:100%,end position:50%,middle\n该死\n\nsource-1181\n01:39:44.985 --> 01:39:47.112 align:middle line:100%,end position:50%,middle\n要我把窗户打开吗？\n\nsource-1182\n01:40:13.805 --> 01:40:17.017 align:middle line:100%,end position:50%,middle\n- 我喜欢和你工作\n- 我也是\n\nsource-1183\n01:40:24.149 --> 01:40:26.777 align:middle line:100%,end position:50%,middle\n- 可能是流弹\n- 根纳不会打偏\n\nsource-1184\n01:40:26.944 --> 01:40:29.112 align:middle line:100%,end position:50%,middle\n若根纳真想打中你\n你就不会在这儿了\n\nsource-1185\n01:40:29.279 --> 01:40:32.199 align:middle line:100%,end position:50%,middle\n非法狩猎者看到会动的东西就射\n\nsource-1186\n01:40:32.366 --> 01:40:34.493 align:middle line:100%,end position:50%,middle\n或许他说得对，迪奇\n真有人要杀他呢？\n\nNATIVE-025\n01:40:35.077 --> 01:40:37.955 align:middle line:100%,end position:50%,middle\n- 这不能继续下去了\n- 你想停止调查，麦可？\n\nsource-1189\n01:40:38.121 --> 01:40:40.082 align:middle line:100%,end position:50%,middle\n我有警方报告和照片\n\nsource-1190\n01:40:40.249 --> 01:40:42.709 align:middle line:100%,end position:50%,middle\n亨利和我的笔记\n还有莉丝的调查资料\n\nsource-1191\n01:40:42.876 --> 01:40:46.839 align:middle line:100%,end position:50%,middle\n唯一缺的是范耶尔企业的档案\n\nsource-1192\n01:40:47.005 --> 01:40:49.716 align:middle line:100%,end position:50%,middle\n- 你要那个做什么？\n- 你可以授权吗？\n\nsource-1193\n01:40:49.883 --> 01:40:52.427 align:middle line:100%,end position:50%,middle\n公司内部档案吗？多久前的？\n\nsource-1194\n01:40:52.594 --> 01:40:55.722 align:middle line:100%,end position:50%,middle\n亨利说过我可以取得任何资料\n\nsource-1195\n01:40:55.889 --> 01:40:59.476 align:middle line:100%,end position:50%,middle\n- 他指的并非这部分\n- 如果需要 我可以签保密协议\n\nsource-1196\n01:40:59.643 --> 01:41:00.936 align:middle line:100%,end position:50%,middle\n你等一下\n\nsource-1197\n01:41:03.730 --> 01:41:05.232 align:middle line:100%,end position:50%,middle\n我想亨利会答应\n\nsource-1198\n01:41:05.399 --> 01:41:10.195 align:middle line:100%,end position:50%,middle\n所以他才找我\n免得他犯傻，这太疯狂了\n\nsource-1199\n01:41:10.362 --> 01:41:11.738 align:middle line:100%,end position:50%,middle\n我们有什么好隐瞒的？\n\nsource-1200\n01:41:11.905 --> 01:41:15.617 align:middle line:100%,end position:50%,middle\n一百二十年的公司\n要隐瞒的大概不少\n\nsource-1201\n01:41:15.784 --> 01:41:18.787 align:middle line:100%,end position:50%,middle\n如果他需要这些才能完成调查\n就该让他查\n\nsource-1202\n01:41:22.916 --> 01:41:24.918 align:middle line:100%,end position:50%,middle\n你要我找什么？\n\nsource-1203\n01:41:25.252 --> 01:41:27.588 align:middle line:100%,end position:50%,middle\n范耶尔企业\n\nsource-1204\n01:41:27.754 --> 01:41:30.507 align:middle line:100%,end position:50%,middle\n和这些女人遇害城镇的关联\n\nsource-1205\n01:41:30.799 --> 01:41:33.218 align:middle line:100%,end position:50%,middle\n还有佛洛德的一切\n\nsource-1206\n01:42:08.162 --> 01:42:09.289 align:middle line:100%,end position:50%,middle\n（哈洛德）\n\nsource-1207\n01:42:25.103 --> 01:42:28.899 align:middle line:100%,end position:50%,middle\n令尊那天拍过一些照片\n没人看过\n\nsource-1208\n01:42:29.066 --> 01:42:31.610 align:middle line:100%,end position:50%,middle\n- 我想看看\n- 那你得去问他\n\nsource-1209\n01:42:31.777 --> 01:42:34.738 align:middle line:100%,end position:50%,middle\n- 也许你可以帮我问\n- 你知道我们不说话\n\nsource-1210\n01:42:34.905 --> 01:42:36.740 align:middle line:100%,end position:50%,middle\n可以破例吗？\n\nsource-1211\n01:42:36.907 --> 01:42:39.326 align:middle line:100%,end position:50%,middle\n你是怕和他共处一室吗？\n\nsource-1212\n01:42:39.493 --> 01:42:41.453 align:middle line:100%,end position:50%,middle\n我可没说你不该害怕\n\nsource-1213\n01:42:41.745 --> 01:42:42.996 align:middle line:100%,end position:50%,middle\n所以你不帮我？\n\nsource-1214\n01:42:45.332 --> 01:42:46.917 align:middle line:100%,end position:50%,middle\n抱歉\n\nsource-1215\n01:42:51.839 --> 01:42:52.881 align:middle line:100%,end position:50%,middle\n拜托\n\nsource-1216\n01:42:54.633 --> 01:42:57.302 align:middle line:100%,end position:50%,middle\n- 好了吗？\n- 我要知道所有工厂\n\nsource-1217\n01:42:57.469 --> 01:43:00.639 align:middle line:100%,end position:50%,middle\n办公室和项目在1949至1966年\n分别位于哪里\n\nsource-1218\n01:43:00.806 --> 01:43:02.850 align:middle line:100%,end position:50%,middle\n- 所有资料都在这了\n- 并没有\n\nsource-1219\n01:43:03.016 --> 01:43:06.228 align:middle line:100%,end position:50%,middle\n没有子公司、合伙企业\n或供应商的资料\n\nsource-1220\n01:43:06.395 --> 01:43:09.189 align:middle line:100%,end position:50%,middle\n- 那我也没办法\n- 佛洛德先生说\n\nsource-1221\n01:43:09.356 --> 01:43:12.442 align:middle line:100%,end position:50%,middle\n- 我可以看任何文件\n- 这一层楼而已\n\nsource-1222\n01:43:12.609 --> 01:43:13.652 align:middle line:100%,end position:50%,middle\n打给他\n\nsource-1223\n01:43:51.106 --> 01:43:52.274 align:middle line:100%,end position:50%,middle\n感谢你见我\n\nsource-1224\n01:43:55.194 --> 01:43:56.820 align:middle line:100%,end position:50%,middle\n进来吧\n\nsource-1225\n01:43:58.822 --> 01:44:00.699 align:middle line:100%,end position:50%,middle\n- 喝茶？\n- 麻烦你\n\nsource-1226\n01:44:08.707 --> 01:44:10.000 align:middle line:100%,end position:50%,middle\n斯文·奥洛夫·林德霍尔姆\n\nsource-1227\n01:44:10.459 --> 01:44:11.502 align:middle line:100%,end position:50%,middle\n我\n\nsource-1228\n01:44:12.211 --> 01:44:13.754 align:middle line:100%,end position:50%,middle\n很帅\n\nsource-1229\n01:44:14.379 --> 01:44:16.215 align:middle line:100%,end position:50%,middle\n毕耶·弗鲁戈德\n\nsource-1230\n01:44:16.381 --> 01:44:17.925 align:middle line:100%,end position:50%,middle\n我\n\nsource-1231\n01:44:18.634 --> 01:44:20.177 align:middle line:100%,end position:50%,middle\n佩尔·恩达尔\n\nsource-1232\n01:44:20.344 --> 01:44:24.640 align:middle line:100%,end position:50%,middle\n不过你想看的\n是我拍的那些生活照吧\n\nsource-1233\n01:44:24.806 --> 01:44:26.934 align:middle line:100%,end position:50%,middle\n我想看朋友、亲戚之类的照片\n\nsource-1234\n01:44:27.392 --> 01:44:29.102 align:middle line:100%,end position:50%,middle\n请\n\nNATIVE-027\n01:44:55.045 --> 01:44:58.882 align:middle line:100%,end position:50%,middle\n- 姓“布隆”还是“布鲁姆”？\n- 布隆维斯特\n\nsource-1237\n01:45:00.050 --> 01:45:02.678 align:middle line:100%,end position:50%,middle\n我并不孤僻\n\nsource-1238\n01:45:03.428 --> 01:45:05.681 align:middle line:100%,end position:50%,middle\n我欢迎任何人\n\nsource-1239\n01:45:05.848 --> 01:45:06.890 align:middle line:100%,end position:50%,middle\n谢谢你\n\nsource-1240\n01:45:07.057 --> 01:45:08.851 align:middle line:100%,end position:50%,middle\n是他们自己不来\n\nsource-1241\n01:45:09.268 --> 01:45:10.936 align:middle line:100%,end position:50%,middle\n或许…\n\nsource-1242\n01:45:11.770 --> 01:45:13.856 align:middle line:100%,end position:50%,middle\n你也许该换换布置\n\nsource-1243\n01:45:14.022 --> 01:45:16.775 align:middle line:100%,end position:50%,middle\n像其他人一样隐藏过去？\n\nsource-1244\n01:45:16.942 --> 01:45:18.986 align:middle line:100%,end position:50%,middle\n藏在薄薄一层亮光贴面下？\n\nsource-1245\n01:45:19.152 --> 01:45:20.445 align:middle line:100%,end position:50%,middle\n就像宜家家居卖的桌子？\n\nsource-1246\n01:45:21.029 --> 01:45:23.448 align:middle line:100%,end position:50%,middle\n我是所有人当中最诚实的\n\nsource-1247\n01:45:23.615 --> 01:45:25.909 align:middle line:100%,end position:50%,middle\n- 整个家族？\n- 整个瑞典\n\nsource-1248\n01:45:37.212 --> 01:45:39.381 align:middle line:100%,end position:50%,middle\n风景照？\n\nNATIVE-028\n01:45:39.965 --> 01:45:43.510 align:middle line:100%,end position:50%,middle\n- 风景照拍得不错？\n- 这是谁？\n\nsource-1251\n01:45:43.677 --> 01:45:45.554 align:middle line:100%,end position:50%,middle\n模糊的这个\n\nsource-1252\n01:45:45.721 --> 01:45:47.222 align:middle line:100%,end position:50%,middle\n我看不出来\n\nsource-1253\n01:45:48.182 --> 01:45:49.808 align:middle line:100%,end position:50%,middle\n戈弗里家的男孩\n\nsource-1254\n01:45:50.475 --> 01:45:51.810 align:middle line:100%,end position:50%,middle\n- 马丁\n- 对\n\nsource-1255\n01:45:51.977 --> 01:45:54.771 align:middle line:100%,end position:50%,middle\n像他父亲一样好看但没用\n\nsource-1256\n01:45:54.938 --> 01:45:55.981 align:middle line:100%,end position:50%,middle\n像他父亲一样\n\nsource-1257\n01:46:08.827 --> 01:46:10.787 align:middle line:100%,end position:50%,middle\n- 要关门了\n- 我还要很久\n\nsource-1258\n01:46:13.332 --> 01:46:15.918 align:middle line:100%,end position:50%,middle\n- 我无权留到很晚\n- 我有权限\n\nsource-1259\n01:46:16.084 --> 01:46:19.922 align:middle line:100%,end position:50%,middle\n还有我要看那些上锁资料\n\nsource-1260\n01:46:22.132 --> 01:46:23.592 align:middle line:100%,end position:50%,middle\n打给佛洛德\n\nsource-1261\n01:46:33.977 --> 01:46:35.521 align:middle line:100%,end position:50%,middle\n走的时候，把钥匙交给警卫\n\nsource-1262\n01:46:55.897 --> 01:46:58.693 align:middle line:100%,end position:50%,middle\n（范耶尔旗下的卡兰建设\n重建兰兹克鲁纳港口）\n\nsource-1263\n01:47:07.568 --> 01:47:10.535 align:middle line:100%,end position:50%,middle\n（受害者是卡兰建设的清洁员工）\n\nsource-1264\n01:47:12.904 --> 01:47:15.029 align:middle line:100%,end position:50%,middle\n（戈弗里与卡兰建设代表握手）\n\nsource-1265\n01:47:18.505 --> 01:47:20.233 align:middle line:100%,end position:50%,middle\n（戈弗里）\n\nsource-1266\n01:47:27.910 --> 01:47:30.502 align:middle line:100%,end position:50%,middle\n（范耶尔企业并购案）\n\nsource-1267\n01:47:32.878 --> 01:47:34.276 align:middle line:100%,end position:50%,middle\n（1954年10月28号\n地点卡尔马）\n\nsource-1268\n01:47:34.512 --> 01:47:36.672 align:middle line:100%,end position:50%,middle\n（玛丽 1954年10月26号 卡尔马\n戈弗里？）\n\nsource-1269\n01:47:42.816 --> 01:47:44.112 align:middle line:100%,end position:50%,middle\n（1960年4月13号\n地点卡斯塔）\n\nsource-1270\n01:47:47.584 --> 01:47:49.175 align:middle line:100%,end position:50%,middle\n（戈弗里？）\n\nsource-1271\n01:48:12.662 --> 01:48:14.026 align:middle line:100%,end position:50%,middle\n（范耶尔巡视工厂）\n\nsource-1272\n01:48:14.229 --> 01:48:15.786 align:middle line:100%,end position:50%,middle\n（范耶尔企业投资乌德瓦拉）\n\nsource-1273\n01:48:16.297 --> 01:48:17.695 align:middle line:100%,end position:50%,middle\n（莉亚遭人勒毙）\n\nsource-1274\n01:48:22.933 --> 01:48:25.058 align:middle line:100%,end position:50%,middle\n（凶手戈弗里？）\n\nsource-1275\n01:48:32.303 --> 01:48:34.998 align:middle line:100%,end position:50%,middle\n（莲娜）\n\nsource-1276\n01:49:00.448 --> 01:49:01.880 align:middle line:100%,end position:50%,middle\n（戈弗里范耶尔\n1927－1965年）\n\nsource-1277\n01:49:04.169 --> 01:49:05.963 align:middle line:100%,end position:50%,middle\n拜托快接电话\n\nsource-1278\n01:49:09.675 --> 01:49:11.426 align:middle line:100%,end position:50%,middle\n可恶！\n\nsource-1279\n01:49:23.878 --> 01:49:25.811 align:middle line:100%,end position:50%,middle\n（戈弗里范耶尔\n1927－1965年）\n\nsource-1280\n01:49:26.847 --> 01:49:28.507 align:middle line:100%,end position:50%,middle\n（1967年2月22号）\n\nsource-1281\n01:49:41.554 --> 01:49:46.512 align:middle line:100%,end position:50%,middle\n（莲娜死于1967年2月22号\n乌普沙拉）\n\nsource-1282\n01:50:47.314 --> 01:50:48.357 align:middle line:100%,end position:50%,middle\n马丁？\n\nsource-1283\n01:54:06.513 --> 01:54:07.556 align:middle line:100%,end position:50%,middle\n麦可\n\nsource-1284\n01:54:11.310 --> 01:54:12.853 align:middle line:100%,end position:50%,middle\n嗨\n\nsource-1285\n01:54:13.353 --> 01:54:15.564 align:middle line:100%,end position:50%,middle\n晚上出来散步？\n\nsource-1286\n01:54:16.064 --> 01:54:18.108 align:middle line:100%,end position:50%,middle\n对…\n\nsource-1287\n01:54:20.402 --> 01:54:22.571 align:middle line:100%,end position:50%,middle\n- 你好吗？\n- 很好\n\nsource-1288\n01:54:23.906 --> 01:54:26.825 align:middle line:100%,end position:50%,middle\n我回家路上去了趟医院\n\nsource-1289\n01:54:26.992 --> 01:54:28.744 align:middle line:100%,end position:50%,middle\n亨利有事要我问你\n\nsource-1290\n01:54:29.494 --> 01:54:30.537 align:middle line:100%,end position:50%,middle\n什么事？\n\nsource-1291\n01:54:31.663 --> 01:54:34.666 align:middle line:100%,end position:50%,middle\n进来喝杯酒再说吧\n\nsource-1292\n01:54:42.958 --> 01:54:46.052 align:middle line:100%,end position:50%,middle\n（赫德史塔、蕾贝卡\n乌普沙拉、莲娜）\n\nsource-1293\n01:54:57.174 --> 01:54:58.300 align:middle line:100%,end position:50%,middle\n（范耶尔公司聚餐）\n\nsource-1294\n01:54:58.508 --> 01:55:01.341 align:middle line:100%,end position:50%,middle\n（最右马丁 就读于乌普沙拉）\n\nsource-1295\n01:55:22.840 --> 01:55:24.258 align:middle line:100%,end position:50%,middle\n你好 马丁\n\nsource-1296\n01:55:25.801 --> 01:55:28.512 align:middle line:100%,end position:50%,middle\n门关上 风很大\n\nsource-1297\n01:55:33.517 --> 01:55:35.477 align:middle line:100%,end position:50%,middle\n- 你怎么了？\n- 什么时候？\n\nsource-1298\n01:55:35.644 --> 01:55:36.895 align:middle line:100%,end position:50%,middle\n刚刚\n\nsource-1299\n01:55:37.062 --> 01:55:39.356 align:middle line:100%,end position:50%,middle\n刚摸黑跌了一跤\n\nsource-1300\n01:55:39.523 --> 01:55:42.192 align:middle line:100%,end position:50%,middle\n没带手电筒？我给你拿一个\n\nsource-1301\n01:55:42.359 --> 01:55:45.112 align:middle line:100%,end position:50%,middle\n一时不小心 没事\n\nsource-1302\n01:55:51.535 --> 01:55:53.912 align:middle line:100%,end position:50%,middle\n调查进行得如何？\n\nsource-1303\n01:55:54.371 --> 01:55:56.832 align:middle line:100%,end position:50%,middle\n- 没有进展\n- 是吗？\n\nsource-1304\n01:55:57.249 --> 01:56:01.461 align:middle line:100%,end position:50%,middle\n佛洛德说那个女孩很聪明\n\nNATIVE-029\n01:56:06.258 --> 01:56:09.219 align:middle line:100%,end position:50%,middle\n- 或许她能找到点什么\n- 也许\n\nsource-1307\n01:56:09.386 --> 01:56:11.096 align:middle line:100%,end position:50%,middle\n谢谢你的手电筒\n\nsource-1308\n01:56:17.060 --> 01:56:18.687 align:middle line:100%,end position:50%,middle\n- 亨利要问什么？\n- 什么？\n\nsource-1309\n01:56:18.854 --> 01:56:21.356 align:middle line:100%,end position:50%,middle\n你说亨利让你问我一件事\n\nsource-1310\n01:56:21.523 --> 01:56:23.525 align:middle line:100%,end position:50%,middle\n- 我刚问了\n- 有吗？\n\nsource-1311\n01:56:23.692 --> 01:56:26.195 align:middle line:100%,end position:50%,middle\n- 调查进展如何？\n- 对\n\nsource-1312\n01:56:26.361 --> 01:56:28.280 align:middle line:100%,end position:50%,middle\n那就是他的问题\n\nsource-1313\n01:56:34.912 --> 01:56:35.954 align:middle line:100%,end position:50%,middle\n你打猎吗？\n\nNATIVE-030\n01:56:37.873 --> 01:56:40.918 align:middle line:100%,end position:50%,middle\n- 改天我们一起去吧\n- 好\n\nsource-1316\n01:56:43.754 --> 01:56:47.424 align:middle line:100%,end position:50%,middle\n真的毫无进展？\n\nsource-1317\n01:56:47.591 --> 01:56:48.675 align:middle line:100%,end position:50%,middle\n对\n\nsource-1318\n01:56:49.635 --> 01:56:51.637 align:middle line:100%,end position:50%,middle\n- 你怎么一副着急的样子？\n- 我没有\n\nsource-1319\n01:56:51.803 --> 01:56:54.056 align:middle line:100%,end position:50%,middle\n我是说你急着回家\n\nsource-1320\n01:56:54.223 --> 01:56:56.183 align:middle line:100%,end position:50%,middle\n我想是\n\nsource-1321\n01:56:56.350 --> 01:56:58.685 align:middle line:100%,end position:50%,middle\n要和女友吃晚餐\n\nsource-1322\n01:56:58.852 --> 01:57:00.062 align:middle line:100%,end position:50%,middle\n助理\n\nsource-1323\n01:57:03.857 --> 01:57:05.734 align:middle line:100%,end position:50%,middle\n用枪，我们的运气会更好\n\nsource-1324\n01:57:05.901 --> 01:57:08.695 align:middle line:100%,end position:50%,middle\n- 抱歉？\n- 打猎的时候\n\nsource-1325\n01:57:09.613 --> 01:57:12.491 align:middle line:100%,end position:50%,middle\n枪比刀好用\n\nsource-1326\n01:57:16.578 --> 01:57:18.372 align:middle line:100%,end position:50%,middle\n给你看样东西\n\nsource-1327\n01:57:19.665 --> 01:57:20.916 align:middle line:100%,end position:50%,middle\n酒带着\n\nsource-1328\n01:57:21.083 --> 01:57:22.751 align:middle line:100%,end position:50%,middle\n我的刀就放下吧\n\nsource-1329\n01:57:39.017 --> 01:57:40.769 align:middle line:100%,end position:50%,middle\n右边\n\nsource-1330\n01:57:45.023 --> 01:57:46.567 align:middle line:100%,end position:50%,middle\n<i>请留言，我会回…</i>\n\nsource-1331\n01:57:46.733 --> 01:57:49.570 align:middle line:100%,end position:50%,middle\n你知道什么比射死一个人难吗？\n\nsource-1332\n01:57:49.736 --> 01:57:50.988 align:middle line:100%,end position:50%,middle\n“差一点”射死他\n\nsource-1333\n01:57:51.864 --> 01:57:54.283 align:middle line:100%,end position:50%,middle\n木屋那一枪，我打得很准\n\nsource-1334\n01:57:54.449 --> 01:57:56.994 align:middle line:100%,end position:50%,middle\n没用，我还在这里\n\nsource-1335\n01:57:57.160 --> 01:58:00.455 align:middle line:100%,end position:50%,middle\n麦可，那有用，你就在这里\n\nsource-1336\n01:58:33.363 --> 01:58:34.907 align:middle line:100%,end position:50%,middle\n进去\n\nsource-1337\n01:59:14.071 --> 01:59:16.031 align:middle line:100%,end position:50%,middle\n你把酒洒了\n\nsource-1338\n01:59:27.501 --> 01:59:29.670 align:middle line:100%,end position:50%,middle\n你何不直接回家去？\n\nsource-1339\n01:59:29.837 --> 01:59:31.004 align:middle line:100%,end position:50%,middle\n我可以吗？\n\nsource-1340\n01:59:36.885 --> 01:59:38.846 align:middle line:100%,end position:50%,middle\n怎么查到的？\n\nsource-1341\n01:59:40.138 --> 01:59:41.473 align:middle line:100%,end position:50%,middle\n发现了什么？\n\nsource-1342\n01:59:45.143 --> 01:59:47.396 align:middle line:100%,end position:50%,middle\n要么谈谈\n要么直接开始\n\nsource-1343\n01:59:48.146 --> 01:59:50.482 align:middle line:100%,end position:50%,middle\n我发现了一张…\n\nsource-1344\n01:59:50.941 --> 01:59:52.484 align:middle line:100%,end position:50%,middle\n没人看过的照片\n\nsource-1345\n01:59:52.651 --> 01:59:53.777 align:middle line:100%,end position:50%,middle\n- 谁的？\n- 你的\n\nsource-1346\n01:59:54.403 --> 01:59:56.363 align:middle line:100%,end position:50%,middle\n穿着乌普沙拉学校制服\n\nNATIVE-031\n01:59:56.530 --> 02:00:00.367 align:middle line:100%,end position:50%,middle\n- 那能证明什么？\n- 你谎报了那天所在的地点\n\nsource-1349\n02:00:00.534 --> 02:00:02.619 align:middle line:100%,end position:50%,middle\n- 是吗？\n- 更确切说，是时间\n\nsource-1350\n02:00:03.328 --> 02:00:05.747 align:middle line:100%,end position:50%,middle\n那又怎样？大家都说谎\n\nsource-1351\n02:00:05.914 --> 02:00:09.459 align:middle line:100%,end position:50%,middle\n还证明你和莲娜·安德松\n是同学\n\nsource-1352\n02:00:09.626 --> 02:00:11.336 align:middle line:100%,end position:50%,middle\n莲娜…\n\nsource-1353\n02:00:12.337 --> 02:00:14.715 align:middle line:100%,end position:50%,middle\n好久以前了\n\nsource-1354\n02:00:15.883 --> 02:00:19.011 align:middle line:100%,end position:50%,middle\n照片在你桌上那堆垃圾里？\n\nsource-1355\n02:00:19.178 --> 02:00:21.680 align:middle line:100%,end position:50%,middle\n我电脑有备份 还有…\n\nsource-1356\n02:00:21.847 --> 02:00:24.516 align:middle line:100%,end position:50%,middle\n- 加密网页也有\n- 加密网页\n\nsource-1357\n02:00:24.975 --> 02:00:26.685 align:middle line:100%,end position:50%,middle\n你骗人\n\nsource-1358\n02:00:28.187 --> 02:00:29.855 align:middle line:100%,end position:50%,middle\n那女的知道多少？\n\nsource-1359\n02:00:31.064 --> 02:00:32.858 align:middle line:100%,end position:50%,middle\n希望和你一样多\n\nsource-1360\n02:00:33.025 --> 02:00:34.943 align:middle line:100%,end position:50%,middle\n到时才有趣\n\nsource-1361\n02:00:35.819 --> 02:00:36.945 align:middle line:100%,end position:50%,middle\n她人呢？\n\nsource-1362\n02:00:37.112 --> 02:00:39.239 align:middle line:100%,end position:50%,middle\n斯德哥尔摩 早上去的\n\nsource-1363\n02:00:39.406 --> 02:00:40.866 align:middle line:100%,end position:50%,middle\n还骗\n\nsource-1364\n02:00:41.033 --> 02:00:44.077 align:middle line:100%,end position:50%,middle\n她在公司档案室看另一堆垃圾\n\nsource-1365\n02:00:44.244 --> 02:00:46.371 align:middle line:100%,end position:50%,middle\n经理打电话给我\n\nsource-1366\n02:00:46.538 --> 02:00:49.625 align:middle line:100%,end position:50%,middle\n说她快被莉丝烦死了\n\nsource-1367\n02:00:49.791 --> 02:00:51.418 align:middle line:100%,end position:50%,middle\n我喜欢她的名字\n\nsource-1368\n02:00:51.585 --> 02:00:53.378 align:middle line:100%,end position:50%,middle\n莉丝\n\nsource-1369\n02:00:53.879 --> 02:00:57.925 align:middle line:100%,end position:50%,middle\n莉丝离开时 警卫会通知我\n\nsource-1370\n02:00:58.091 --> 02:01:01.345 align:middle line:100%,end position:50%,middle\n这样我就能到你的小屋迎接她\n\nsource-1371\n02:01:02.971 --> 02:01:06.350 align:middle line:100%,end position:50%,middle\n真是感谢你把她引到这来\n\nsource-1372\n02:01:06.808 --> 02:01:08.393 align:middle line:100%,end position:50%,middle\n嘿\n\nsource-1373\n02:01:34.795 --> 02:01:37.089 align:middle line:100%,end position:50%,middle\n你想知道什么？\n\nsource-1374\n02:01:39.591 --> 02:01:41.927 align:middle line:100%,end position:50%,middle\n你是记者 发问吧\n\nNATIVE-032\n02:01:47.099 --> 02:01:50.269 align:middle line:100%,end position:50%,middle\n我对那些女孩做了什么？\n这问题问得好\n\nsource-1377\n02:01:51.186 --> 02:01:53.146 align:middle line:100%,end position:50%,middle\n在我对你做同样的事之前\n\nNATIVE-033\n02:01:53.313 --> 02:01:56.817 align:middle line:100%,end position:50%,middle\n坐下，放松，喝杯酒\n我很喜欢这一段\n\nsource-1380\n02:01:56.984 --> 02:02:00.612 align:middle line:100%,end position:50%,middle\n和一个知道自己就快死的人聊天\n这部分我挺爱\n\nsource-1381\n02:02:01.572 --> 02:02:05.325 align:middle line:100%,end position:50%,middle\n接着把尸体丢到大海 永远摆脱\n\nsource-1382\n02:02:05.492 --> 02:02:08.036 align:middle line:100%,end position:50%,middle\n不像我父亲\n让受害者遍布瑞典\n\nsource-1383\n02:02:08.203 --> 02:02:11.707 align:middle line:100%,end position:50%,middle\n四处都是，像奖杯一样\n要我说，那可不聪明\n\nsource-1384\n02:02:12.416 --> 02:02:14.251 align:middle line:100%,end position:50%,middle\n他是个张扬又俗气的人\n\nsource-1385\n02:02:15.169 --> 02:02:17.504 align:middle line:100%,end position:50%,middle\n老实说我觉得他死了活该\n\nsource-1386\n02:02:18.255 --> 02:02:20.799 align:middle line:100%,end position:50%,middle\n他太粗心\n\nsource-1387\n02:02:20.966 --> 02:02:23.343 align:middle line:100%,end position:50%,middle\n喝酒毫无节制\n\nsource-1388\n02:02:23.510 --> 02:02:24.928 align:middle line:100%,end position:50%,middle\n计划过程需要纪律\n\nsource-1389\n02:02:25.554 --> 02:02:28.056 align:middle line:100%,end position:50%,middle\n像科学一样讲究无数细节\n\nsource-1390\n02:02:28.223 --> 02:02:31.018 align:middle line:100%,end position:50%,middle\n计划到执行\n\nsource-1391\n02:02:31.185 --> 02:02:33.145 align:middle line:100%,end position:50%,middle\n还有清理现场\n\nsource-1392\n02:02:33.604 --> 02:02:35.314 align:middle line:100%,end position:50%,middle\n我猜你用不着知道\n\nsource-1393\n02:02:35.480 --> 02:02:38.692 align:middle line:100%,end position:50%,middle\n但你会把这里弄得一团糟\n\nsource-1394\n02:02:41.403 --> 02:02:43.322 align:middle line:100%,end position:50%,middle\n我问你\n\nsource-1395\n02:02:43.488 --> 02:02:46.450 align:middle line:100%,end position:50%,middle\n人为什么不相信自己的直觉？\n\nsource-1396\n02:02:46.950 --> 02:02:48.493 align:middle line:100%,end position:50%,middle\n明明感到事情不对劲\n\nsource-1397\n02:02:48.660 --> 02:02:51.205 align:middle line:100%,end position:50%,middle\n有人紧紧跟在他们身后\n\nsource-1398\n02:02:51.622 --> 02:02:53.790 align:middle line:100%,end position:50%,middle\n你知道状况不妙\n\nNATIVE-034\n02:02:53.957 --> 02:02:59.588 align:middle line:100%,end position:50%,middle\n但你还是回来了\n我逼你了吗，拖你了吗？没有\n\nsource-1401\n02:02:59.922 --> 02:03:03.425 align:middle line:100%,end position:50%,middle\n我只需要请你喝一杯\n\nsource-1402\n02:03:04.051 --> 02:03:06.428 align:middle line:100%,end position:50%,middle\n很难相信，怕冒犯别人\n\nsource-1403\n02:03:06.595 --> 02:03:11.558 align:middle line:100%,end position:50%,middle\n竟能胜过对疼痛的恐惧\n但事实就是如此\n\nsource-1404\n02:03:13.185 --> 02:03:15.103 align:middle line:100%,end position:50%,middle\n她们也都是自愿来\n\nsource-1405\n02:03:15.270 --> 02:03:16.772 align:middle line:100%,end position:50%,middle\n然后坐在那里\n\nsource-1406\n02:03:16.939 --> 02:03:19.441 align:middle line:100%,end position:50%,middle\n知道玩完了 就像你现在一样\n\nsource-1407\n02:03:19.608 --> 02:03:22.569 align:middle line:100%,end position:50%,middle\n但她们还以为有机会\n\nsource-1408\n02:03:22.736 --> 02:03:24.655 align:middle line:100%,end position:50%,middle\n“也许我说对了话…\n\nsource-1409\n02:03:24.821 --> 02:03:26.615 align:middle line:100%,end position:50%,middle\n表现得有礼貌…\n\nsource-1410\n02:03:26.782 --> 02:03:29.076 align:middle line:100%,end position:50%,middle\n或哭泣、乞求就能活命”\n\nsource-1411\n02:03:29.493 --> 02:03:32.037 align:middle line:100%,end position:50%,middle\n看着希望从她们脸上消失\n\nsource-1412\n02:03:32.204 --> 02:03:34.831 align:middle line:100%,end position:50%,middle\n就像你现在一样\n\nsource-1413\n02:03:34.998 --> 02:03:36.750 align:middle line:100%,end position:50%,middle\n我感觉自己…\n\nsource-1414\n02:03:37.084 --> 02:03:38.377 align:middle line:100%,end position:50%,middle\n硬了起来\n\nsource-1415\n02:03:39.795 --> 02:03:44.341 align:middle line:100%,end position:50%,middle\n你我没那么不同\n都有自己的欲望\n\nsource-1416\n02:03:44.508 --> 02:03:46.468 align:middle line:100%,end position:50%,middle\n只是满足我的欲望…\n\nsource-1417\n02:03:46.635 --> 02:03:48.762 align:middle line:100%,end position:50%,middle\n需要比较多毛巾\n\nsource-1418\n02:04:10.701 --> 02:04:12.536 align:middle line:100%,end position:50%,middle\n你大概也有兴趣知道\n\nsource-1419\n02:04:12.911 --> 02:04:17.499 align:middle line:100%,end position:50%,middle\n我们和小丽在楼上吃麋鹿排那天\n\nsource-1420\n02:04:18.083 --> 02:04:22.254 align:middle line:100%,end position:50%,middle\n小丽觉得我很保守又普通\n\nsource-1421\n02:04:23.172 --> 02:04:25.716 align:middle line:100%,end position:50%,middle\n伊琳娜就在那笼子里\n\nsource-1422\n02:04:25.883 --> 02:04:28.260 align:middle line:100%,end position:50%,middle\n你大概会问伊琳娜是谁？\n\nsource-1423\n02:04:28.427 --> 02:04:30.220 align:middle line:100%,end position:50%,middle\n不过又是另一个女孩\n\nsource-1424\n02:04:30.721 --> 02:04:33.849 align:middle line:100%,end position:50%,middle\n又一个移民妓女\n\nsource-1425\n02:04:34.474 --> 02:04:36.351 align:middle line:100%,end position:50%,middle\n- 谁会想念她们？\n- 你妹妹不是\n\nsource-1426\n02:04:36.935 --> 02:04:38.187 align:middle line:100%,end position:50%,middle\n什么？\n\nsource-1427\n02:04:38.353 --> 02:04:42.774 align:middle line:100%,end position:50%,middle\n海莉不只是另一个女孩\n\nsource-1428\n02:04:42.941 --> 02:04:44.776 align:middle line:100%,end position:50%,middle\n你找到她？\n\nsource-1429\n02:04:46.695 --> 02:04:48.405 align:middle line:100%,end position:50%,middle\n她怎么了？\n\nsource-1430\n02:04:50.199 --> 02:04:52.826 align:middle line:100%,end position:50%,middle\n你杀了她\n\nsource-1431\n02:04:57.164 --> 02:05:00.542 align:middle line:100%,end position:50%,middle\n你这个没用的混蛋侦探\n\nsource-1432\n02:05:04.963 --> 02:05:09.259 align:middle line:100%,end position:50%,middle\n勒得你说不出话？正好\n我也说累了\n\nsource-1433\n02:05:46.421 --> 02:05:48.549 align:middle line:100%,end position:50%,middle\n我没带男人来过这儿\n\nNATIVE-035\n02:05:54.680 --> 02:05:58.767 align:middle line:100%,end position:50%,middle\n其实我从没碰过男人\n除了我父亲\n\nsource-1436\n02:06:00.185 --> 02:06:02.312 align:middle line:100%,end position:50%,middle\n那是“我们的责任”\n\nsource-1437\n02:06:03.522 --> 02:06:05.649 align:middle line:100%,end position:50%,middle\n海莉和我\n\nsource-1438\n02:06:19.413 --> 02:06:20.747 align:middle line:100%,end position:50%,middle\n嘿\n\nsource-1439\n02:06:36.889 --> 02:06:39.600 align:middle line:100%,end position:50%,middle\n电视上面有枪\n\nsource-1440\n02:06:46.690 --> 02:06:48.650 align:middle line:100%,end position:50%,middle\n- 可以杀了他吗？\n- 可以\n\nsource-1441\n02:09:57.881 --> 02:10:00.968 align:middle line:100%,end position:50%,middle\n一个二十三岁的人\n\nsource-1442\n02:10:01.134 --> 02:10:03.846 align:middle line:100%,end position:50%,middle\n被政府监护？\n\nsource-1443\n02:10:07.057 --> 02:10:11.270 align:middle line:100%,end position:50%,middle\n我精神失能 无法自理日常生活\n\nsource-1444\n02:10:13.647 --> 02:10:16.316 align:middle line:100%,end position:50%,middle\n他们什么时候开始这样说的？\n\nsource-1445\n02:10:16.483 --> 02:10:19.194 align:middle line:100%,end position:50%,middle\n我十二岁那年\n\nsource-1446\n02:10:20.654 --> 02:10:22.489 align:middle line:100%,end position:50%,middle\n你十二岁那年发生了什么？\n\nsource-1447\n02:10:26.410 --> 02:10:30.205 align:middle line:100%,end position:50%,middle\n抱歉 不关我的事\n\nsource-1448\n02:10:32.708 --> 02:10:34.459 align:middle line:100%,end position:50%,middle\n我试图杀我爸\n\nsource-1449\n02:10:36.670 --> 02:10:38.672 align:middle line:100%,end position:50%,middle\n放火烧他\n\nsource-1450\n02:10:39.298 --> 02:10:43.302 align:middle line:100%,end position:50%,middle\n他全身百分之八十烧伤\n\nsource-1451\n02:10:50.058 --> 02:10:51.977 align:middle line:100%,end position:50%,middle\n我煮了咖啡\n\nsource-1452\n02:10:56.148 --> 02:10:59.026 align:middle line:100%,end position:50%,middle\n- 那是谁？\n- 海莉\n\nsource-1453\n02:10:59.193 --> 02:11:02.863 align:middle line:100%,end position:50%,middle\n在马丁地下室\n那些纪念品里找到的\n\nsource-1454\n02:11:03.030 --> 02:11:06.200 align:middle line:100%,end position:50%,middle\n不对 马丁没否认杀人\n\nsource-1455\n02:11:07.242 --> 02:11:10.662 align:middle line:100%,end position:50%,middle\n但我提到海莉时\n他一脸困惑\n\nsource-1456\n02:11:10.829 --> 02:11:15.250 align:middle line:100%,end position:50%,middle\n还气我没查出她下落\n\nsource-1457\n02:11:15.417 --> 02:11:17.085 align:middle line:100%,end position:50%,middle\n他没杀她\n\nsource-1458\n02:11:17.920 --> 02:11:22.007 align:middle line:100%,end position:50%,middle\n也不是他爸 他爸前一年就死了\n\nsource-1459\n02:11:23.050 --> 02:11:27.137 align:middle line:100%,end position:50%,middle\n如果她利用某种方法逃走呢？\n\nsource-1460\n02:11:27.304 --> 02:11:28.847 align:middle line:100%,end position:50%,middle\n我是说 假如…\n\nsource-1461\n02:11:30.432 --> 02:11:32.809 align:middle line:100%,end position:50%,middle\n她还没死\n\nsource-1462\n02:11:34.102 --> 02:11:38.315 align:middle line:100%,end position:50%,middle\n那家里只有一个人\n会知道她在哪\n\nsource-1463\n02:12:06.468 --> 02:12:07.719 align:middle line:100%,end position:50%,middle\n我操，我操，我操\n\nsource-1464\n02:12:28.031 --> 02:12:29.616 align:middle line:100%,end position:50%,middle\n该你上场\n\nsource-1465\n02:12:30.117 --> 02:12:31.577 align:middle line:100%,end position:50%,middle\n没错\n\nsource-1466\n02:12:32.411 --> 02:12:33.787 align:middle line:100%,end position:50%,middle\n拿去\n\nNATIVE-036\n02:12:51.096 --> 02:12:55.017 align:middle line:100%,end position:50%,middle\n- 你好，抱歉打扰\n- 什么事？\n\nsource-1469\n02:12:55.184 --> 02:12:57.019 align:middle line:100%,end position:50%,middle\n- 有人通知你吗？\n- 通知什么？\n\nsource-1470\n02:12:57.436 --> 02:12:58.979 align:middle line:100%,end position:50%,middle\n你表哥马丁\n\nsource-1471\n02:13:00.564 --> 02:13:03.775 align:middle line:100%,end position:50%,middle\n- 他怎么了？\n- 他出了车祸\n\nsource-1472\n02:13:03.942 --> 02:13:06.778 align:middle line:100%,end position:50%,middle\n上周四去世了\n赫德史塔会举行追悼会\n\nsource-1473\n02:13:06.945 --> 02:13:09.573 align:middle line:100%,end position:50%,middle\n我没兴趣去参加丧礼\n\nsource-1474\n02:13:09.783 --> 02:13:12.048 align:middle line:100%,end position:50%,middle\n- 我了解\n- 了解什么？\n\nsource-1475\n02:13:12.258 --> 02:13:14.928 align:middle line:100%,end position:50%,middle\n你不关心家族的事\n\nsource-1476\n02:13:15.120 --> 02:13:18.373 align:middle line:100%,end position:50%,middle\n- 我只是认为该让你知道\n- 我知道了\n\nsource-1477\n02:13:28.342 --> 02:13:29.718 align:middle line:100%,end position:50%,middle\n怎么样？\n\nsource-1478\n02:13:29.885 --> 02:13:31.803 align:middle line:100%,end position:50%,middle\n还可以吧\n\nsource-1479\n02:13:31.970 --> 02:13:33.222 align:middle line:100%,end position:50%,middle\n她上线了\n\nsource-1480\n02:13:41.104 --> 02:13:43.106 align:middle line:100%,end position:50%,middle\n上购物网\n\nsource-1481\n02:13:53.075 --> 02:13:55.285 align:middle line:100%,end position:50%,middle\n她还在玩接龙？\n\nsource-1482\n02:13:55.452 --> 02:13:57.621 align:middle line:100%,end position:50%,middle\n- 还没打给任何人吗？\n- 没有\n\nsource-1483\n02:13:57.788 --> 02:13:59.998 align:middle line:100%,end position:50%,middle\n手机也窃听了？\n\nsource-1484\n02:14:01.416 --> 02:14:03.627 align:middle line:100%,end position:50%,middle\n我原以为她会带我们找到海莉\n\nsource-1485\n02:14:03.794 --> 02:14:06.296 align:middle line:100%,end position:50%,middle\n把手伸回我的衬衫里\n\nsource-1486\n02:14:09.132 --> 02:14:11.552 align:middle line:100%,end position:50%,middle\n她没打给海莉只有一个原因\n\nsource-1487\n02:14:11.718 --> 02:14:15.180 align:middle line:100%,end position:50%,middle\n因为她死了 没办法打\n\nsource-1488\n02:14:16.890 --> 02:14:18.475 align:middle line:100%,end position:50%,middle\n我只是在想…\n\nsource-1489\n02:14:18.642 --> 02:14:20.727 align:middle line:100%,end position:50%,middle\n- 等一下\n- 好\n\nsource-1490\n02:14:34.533 --> 02:14:36.618 align:middle line:100%,end position:50%,middle\n你刚刚要说什么？\n\nsource-1491\n02:14:37.119 --> 02:14:40.622 align:middle line:100%,end position:50%,middle\n我在想另一个可能性\n\nsource-1492\n02:14:47.671 --> 02:14:49.006 align:middle line:100%,end position:50%,middle\n我们绝对可以\n\nsource-1493\n02:14:51.341 --> 02:14:52.551 align:middle line:100%,end position:50%,middle\n你又来干嘛？\n\nsource-1494\n02:14:52.718 --> 02:14:55.387 align:middle line:100%,end position:50%,middle\n死前，你哥哥把我吊在钩子上\n\nsource-1495\n02:14:57.931 --> 02:14:59.391 align:middle line:100%,end position:50%,middle\n海莉\n\nsource-1496\n02:15:02.394 --> 02:15:04.104 align:middle line:100%,end position:50%,middle\n所以压花是你送的？\n\nsource-1497\n02:15:04.271 --> 02:15:06.315 align:middle line:100%,end position:50%,middle\n对 是我\n\nsource-1498\n02:15:06.481 --> 02:15:10.194 align:middle line:100%,end position:50%,middle\n我们查瑞典家庭登记时\n发现阿妮塔结过婚\n\nsource-1499\n02:15:10.360 --> 02:15:13.405 align:middle line:100%,end position:50%,middle\n- 但是整个家族没人知道\n- 对\n\nsource-1500\n02:15:13.572 --> 02:15:17.034 align:middle line:100%,end position:50%,middle\n所以我猜她用婚后姓氏的护照\n来到这里\n\nsource-1501\n02:15:17.201 --> 02:15:19.453 align:middle line:100%,end position:50%,middle\n而你用她婚前姓氏的护照跟来\n\nsource-1502\n02:15:19.620 --> 02:15:22.039 align:middle line:100%,end position:50%,middle\n刚好相反\n\nsource-1503\n02:15:22.206 --> 02:15:26.335 align:middle line:100%,end position:50%,middle\n她觉得让我和斯宾塞一起走\n会更安全\n\nsource-1504\n02:15:26.502 --> 02:15:28.879 align:middle line:100%,end position:50%,middle\n他怎么想？\n\nsource-1505\n02:15:29.046 --> 02:15:31.965 align:middle line:100%,end position:50%,middle\n他没多想，只是爱她\n\nsource-1506\n02:15:32.591 --> 02:15:36.595 align:middle line:100%,end position:50%,middle\n她说“爱我就照作 别问为什么”\n\nsource-1507\n02:15:36.762 --> 02:15:38.430 align:middle line:100%,end position:50%,middle\n他也从来没问\n\nNATIVE-037\n02:15:38.597 --> 02:15:41.600 align:middle line:100%,end position:50%,middle\n- 他们二十年前都去世了\n- 车祸\n\nsource-1510\n02:15:41.767 --> 02:15:44.186 align:middle line:100%,end position:50%,middle\n你连这也查到了\n\nsource-1511\n02:15:49.274 --> 02:15:50.901 align:middle line:100%,end position:50%,middle\n这是你吗？\n\nsource-1512\n02:15:57.699 --> 02:16:01.411 align:middle line:100%,end position:50%,middle\n我十四岁时他第一次强暴我\n\nsource-1513\n02:16:01.578 --> 02:16:02.663 align:middle line:100%,end position:50%,middle\n马丁\n\nsource-1514\n02:16:02.829 --> 02:16:04.456 align:middle line:100%,end position:50%,middle\n不 我父亲\n\nsource-1515\n02:16:04.915 --> 02:16:09.086 align:middle line:100%,end position:50%,middle\n马丁在父亲死后接手\n\nsource-1516\n02:16:09.253 --> 02:16:13.131 align:middle line:100%,end position:50%,middle\n- 为什么不告诉别人？\n- 我告诉了我母亲\n\nsource-1517\n02:16:13.298 --> 02:16:16.426 align:middle line:100%,end position:50%,middle\n- 亨利一定可以帮你的\n- 我几乎就要说出口\n\nsource-1518\n02:16:16.593 --> 02:16:18.887 align:middle line:100%,end position:50%,middle\n但我害怕\n因为我做过的事\n\nNATIVE-038\n02:16:19.638 --> 02:16:23.725 align:middle line:100%,end position:50%,middle\n- 我…\n- 你还是不明白，对吗？\n\nsource-1520\n02:16:24.309 --> 02:16:26.979 align:middle line:100%,end position:50%,middle\n第一次的事过了一年\n\nsource-1521\n02:16:27.145 --> 02:16:31.650 align:middle line:100%,end position:50%,middle\n接下来那年又发生好几次\n\nsource-1522\n02:16:32.441 --> 02:16:36.154 align:middle line:100%,end position:50%,middle\n有一晚 他喝得比平常醉\n\nsource-1523\n02:16:37.030 --> 02:16:42.995 align:middle line:100%,end position:50%,middle\n他开始夸耀是如何杀死那些女人\n\nsource-1524\n02:16:43.161 --> 02:16:46.373 align:middle line:100%,end position:50%,middle\n接着撕我衣服\n还引述《圣经》\n\nsource-1525\n02:16:47.040 --> 02:16:49.834 align:middle line:100%,end position:50%,middle\n<i>用皮带缠住我脖子</i>\n\nsource-1526\n02:16:50.002 --> 02:16:52.337 align:middle line:100%,end position:50%,middle\n想勒死我\n\nsource-1527\n02:16:54.255 --> 02:16:56.549 align:middle line:100%,end position:50%,middle\n我逃出小屋\n\nsource-1528\n02:16:57.342 --> 02:16:58.968 align:middle line:100%,end position:50%,middle\n<i>跑到船坞上</i>\n\nsource-1529\n02:16:59.261 --> 02:17:02.181 align:middle line:100%,end position:50%,middle\n他跌跌撞撞从后面追来\n\nsource-1530\n02:17:03.682 --> 02:17:05.976 align:middle line:100%,end position:50%,middle\n在屋里我可能无法抵抗他\n\nsource-1531\n02:17:06.434 --> 02:17:09.062 align:middle line:100%,end position:50%,middle\n<i>但在屋外…</i>\n\nsource-1532\n02:17:09.563 --> 02:17:12.523 align:middle line:100%,end position:50%,middle\n我的力气足够对付一个醉鬼\n\nsource-1533\n02:17:16.111 --> 02:17:18.280 align:middle line:100%,end position:50%,middle\n一切结束之后\n\nsource-1534\n02:17:19.531 --> 02:17:24.286 align:middle line:100%,end position:50%,middle\n<i>我看到马丁站在那瞪着我</i>\n\nsource-1535\n02:17:24.912 --> 02:17:29.958 align:middle line:100%,end position:50%,middle\n结果我不过是\n用一个施害者换了另一个\n\nsource-1536\n02:17:32.585 --> 02:17:37.216 align:middle line:100%,end position:50%,middle\n<i>两个月后\n亨利送他去乌普沙拉读书</i>\n\nsource-1537\n02:17:37.382 --> 02:17:42.513 align:middle line:100%,end position:50%,middle\n我以为噩梦结束了\n\nsource-1538\n02:17:43.847 --> 02:17:47.308 align:middle line:100%,end position:50%,middle\n<i>没想到游行那天我看到他</i>\n\nsource-1539\n02:17:47.726 --> 02:17:50.020 align:middle line:100%,end position:50%,middle\n<i>就站在对街</i>\n\nsource-1540\n02:17:50.353 --> 02:17:54.858 align:middle line:100%,end position:50%,middle\n<i>然后我就知道\n事情永远不会结束</i>\n\nsource-1541\n02:17:55.400 --> 02:17:56.817 align:middle line:100%,end position:50%,middle\n你怎么逃跑的？\n\nsource-1542\n02:17:56.985 --> 02:17:59.404 align:middle line:100%,end position:50%,middle\n是阿妮塔\n\nsource-1543\n02:17:59.947 --> 02:18:02.657 align:middle line:100%,end position:50%,middle\n她坚持我什么都不能带\n\nsource-1544\n02:18:03.367 --> 02:18:07.745 align:middle line:100%,end position:50%,middle\n否则警察会认为我还活着\n\nsource-1545\n02:18:08.496 --> 02:18:13.709 align:middle line:100%,end position:50%,middle\n<i>其实晚餐时\n我就在二十米外的地方</i>\n\nsource-1546\n02:18:14.670 --> 02:18:18.382 align:middle line:100%,end position:50%,middle\n<i>在那待了一晚\n他们正在搜索我</i>\n\nsource-1547\n02:18:19.049 --> 02:18:21.677 align:middle line:100%,end position:50%,middle\n<i>第二天早上，她来接我</i>\n\nsource-1548\n02:18:23.053 --> 02:18:26.598 align:middle line:100%,end position:50%,middle\n<i>那座桥陪我长大 像和家的连结</i>\n\nsource-1549\n02:18:27.307 --> 02:18:28.767 align:middle line:100%,end position:50%,middle\n<i>但我一心只想着</i>\n\nsource-1550\n02:18:29.977 --> 02:18:32.228 align:middle line:100%,end position:50%,middle\n只要能远离他们\n\nsource-1551\n02:18:33.772 --> 02:18:35.983 align:middle line:100%,end position:50%,middle\n<i>只要躲过警察</i>\n\nsource-1552\n02:18:36.483 --> 02:18:38.568 align:middle line:100%,end position:50%,middle\n<i>我就安全了</i>\n\nsource-1553\n02:18:41.655 --> 02:18:42.990 align:middle line:100%,end position:50%,middle\n<i>我是很安全</i>\n\nsource-1554\n02:18:44.156 --> 02:18:46.034 align:middle line:100%,end position:50%,middle\n直到你出现\n\nsource-1555\n02:18:47.451 --> 02:18:48.870 align:middle line:100%,end position:50%,middle\n你现在很安全\n\nsource-1556\n02:18:51.623 --> 02:18:53.291 align:middle line:100%,end position:50%,middle\n你怎么逃出来的？\n\nsource-1557\n02:18:55.043 --> 02:18:57.212 align:middle line:100%,end position:50%,middle\n也有人救了我\n\nsource-1558\n02:19:10.100 --> 02:19:11.559 align:middle line:100%,end position:50%,middle\n- 身体怎么样？\n- 很好\n\nsource-1559\n02:19:11.727 --> 02:19:13.270 align:middle line:100%,end position:50%,middle\n谢谢你\n\nsource-1560\n02:19:14.730 --> 02:19:17.858 align:middle line:100%,end position:50%,middle\n我向你保证过\n\nsource-1561\n02:19:19.151 --> 02:19:22.571 align:middle line:100%,end position:50%,middle\n不管调查有没有结果\n\nsource-1562\n02:19:22.757 --> 02:19:25.032 align:middle line:100%,end position:50%,middle\n（温纳斯壮）\n\nsource-1563\n02:19:26.366 --> 02:19:28.994 align:middle line:100%,end position:50%,middle\n你要告诉我什么？\n\nsource-1564\n02:19:40.672 --> 02:19:42.382 align:middle line:100%,end position:50%,middle\n这是？\n\nsource-1565\n02:19:59.650 --> 02:20:01.735 align:middle line:100%,end position:50%,middle\n哈啰 亨利\n\nsource-1566\n02:20:20.629 --> 02:20:24.049 align:middle line:100%,end position:50%,middle\n我连温纳斯壮曾在这里工作\n都快忘了 更别说被开除\n\nsource-1567\n02:20:24.216 --> 02:20:26.343 align:middle line:100%,end position:50%,middle\n你当然记不清了\n毕竟过去那么久了\n\nsource-1568\n02:20:26.510 --> 02:20:30.055 align:middle line:100%,end position:50%,middle\n这比他挪用你钱的事更关键\n\nsource-1569\n02:20:30.222 --> 02:20:32.641 align:middle line:100%,end position:50%,middle\n你指的是追诉时效\n\nsource-1570\n02:20:32.808 --> 02:20:35.853 align:middle line:100%,end position:50%,middle\n我不知道这是亨利答应你的\n\nsource-1571\n02:20:36.019 --> 02:20:38.730 align:middle line:100%,end position:50%,middle\n早知道，我绝不会让他\n把你请到这里来\n\nsource-1572\n02:20:38.897 --> 02:20:40.482 align:middle line:100%,end position:50%,middle\n他不是故意骗你\n\nsource-1573\n02:20:40.649 --> 02:20:43.318 align:middle line:100%,end position:50%,middle\n他知道事情过了35年\n就不能起诉了\n\nsource-1574\n02:20:43.485 --> 02:20:46.989 align:middle line:100%,end position:50%,middle\n- 我喜欢亨利，但他知道这点\n- 一个人的名誉很重要\n\nsource-1575\n02:20:47.155 --> 02:20:50.117 align:middle line:100%,end position:50%,middle\n他相信这一点，他以为你能毁掉\n\nsource-1576\n02:20:50.284 --> 02:20:53.412 align:middle line:100%,end position:50%,middle\n- 温纳斯壮的公众声誉\n- 公众舆论\n\nsource-1577\n02:20:53.579 --> 02:20:56.498 align:middle line:100%,end position:50%,middle\n- 就喜欢人们干的坏事\n- 他毕竟年纪大了\n\nsource-1578\n02:20:56.665 --> 02:20:59.209 align:middle line:100%,end position:50%,middle\n他答应把温纳斯壮的尸体\n端上盘子交给我\n\nsource-1579\n02:20:59.376 --> 02:21:01.336 align:middle line:100%,end position:50%,middle\n这连盘子都算不上\n\nsource-1580\n02:21:01.503 --> 02:21:04.798 align:middle line:100%,end position:50%,middle\n- 这些资料根本没用\n- 当然了\n\nNATIVE-039\n02:21:08.093 --> 02:21:12.097 align:middle line:100%,end position:50%,middle\n温纳斯壮那件事是怎么回事？\n他怎么让你栽了跟头？\n\nsource-1583\n02:21:12.681 --> 02:21:17.436 align:middle line:100%,end position:50%,middle\n我太蠢，听信了一些话\n消息来自匿名人士\n\nsource-1584\n02:21:17.603 --> 02:21:20.731 align:middle line:100%,end position:50%,middle\n我确定那是他的人 我被设计了\n\nsource-1585\n02:21:22.107 --> 02:21:23.483 align:middle line:100%,end position:50%,middle\n那些是假资料\n\nsource-1586\n02:21:23.650 --> 02:21:26.111 align:middle line:100%,end position:50%,middle\n他在法庭上轻松反驳\n\nsource-1587\n02:21:26.278 --> 02:21:29.031 align:middle line:100%,end position:50%,middle\n你强调我调查你的方式\n\nsource-1588\n02:21:29.198 --> 02:21:32.451 align:middle line:100%,end position:50%,middle\n既违法又不道德\n对温纳斯壮你也这么想吗？\n\nsource-1589\n02:21:32.618 --> 02:21:35.454 align:middle line:100%,end position:50%,middle\n- 说下去\n- 我自己调查过他\n\nsource-1590\n02:21:35.621 --> 02:21:38.207 align:middle line:100%,end position:50%,middle\n在你雇我之前\n不过我还没看完\n\nNATIVE-040\n02:21:38.373 --> 02:21:41.752 align:middle line:100%,end position:50%,middle\n因为你和那个该死的海莉·范耶尔\n让我忙得没空\n\nsource-1593\n02:21:43.629 --> 02:21:45.172 align:middle line:100%,end position:50%,middle\n我可能查到了证据\n\nsource-1594\n02:21:45.589 --> 02:21:47.299 align:middle line:100%,end position:50%,middle\n你有证据？\n\nsource-1595\n02:21:48.634 --> 02:21:49.801 align:middle line:100%,end position:50%,middle\n应该\n\nsource-1596\n02:21:49.968 --> 02:21:52.137 align:middle line:100%,end position:50%,middle\n他们把军火和毒品的收入拿来洗钱\n\nsource-1597\n02:21:52.304 --> 02:21:54.139 align:middle line:100%,end position:50%,middle\n还有俄罗斯犯罪集团的黑钱\n\nsource-1598\n02:21:54.306 --> 02:21:57.476 align:middle line:100%,end position:50%,middle\n这些黑钱占他资产的九成五\n\nsource-1599\n02:21:57.643 --> 02:22:00.062 align:middle line:100%,end position:50%,middle\n其余的钱进了开曼群岛的账户\n\nsource-1600\n02:22:00.229 --> 02:22:03.232 align:middle line:100%,end position:50%,middle\n- 你怎么知道这些？\n- 这次你不会想知道\n\nsource-1601\n02:22:03.398 --> 02:22:05.484 align:middle line:100%,end position:50%,middle\n这次我才想知道\n\nsource-1602\n02:22:06.109 --> 02:22:07.986 align:middle line:100%,end position:50%,middle\n我能访问他的电脑\n\nNATIVE-041\n02:22:08.153 --> 02:22:11.406 align:middle line:100%,end position:50%,middle\n- 还有会计师和律师的电脑\n- 你怎么访问的？\n\nsource-1604\n02:22:11.519 --> 02:22:13.307 align:middle line:100%,end position:50%,middle\n你可以说是内部人士提供的\n\nNATIVE-042\n02:22:13.575 --> 02:22:15.410 align:middle line:100%,end position:50%,middle\n- 可事实不是\n- 你对外就这么说\n\nNATIVE-043\n02:22:15.577 --> 02:22:19.498 align:middle line:100%,end position:50%,middle\n- 那你对我怎么说？\n- 看你是不是真想知道\n\nsource-1608\n02:22:19.665 --> 02:22:22.668 align:middle line:100%,end position:50%,middle\n我想知道\n麦可，你怎么取得访问权限的？\n\nsource-1609\n02:22:34.721 --> 02:22:36.849 align:middle line:100%,end position:50%,middle\n<i>财经记者布隆维斯特</i>\n\nsource-1610\n02:22:37.015 --> 02:22:39.518 align:middle line:100%,end position:50%,middle\n<i>去年此时，被判诽谤罪</i>\n\nsource-1611\n02:22:39.685 --> 02:22:41.144 align:middle line:100%,end position:50%,middle\n<i>就在斯德哥尔摩的法庭上</i>\n\nsource-1612\n02:22:41.311 --> 02:22:43.647 align:middle line:100%,end position:50%,middle\n<i>他没学到教训</i>\n\nsource-1613\n02:22:43.814 --> 02:22:45.399 align:middle line:100%,end position:50%,middle\n<i>或许他已经吸取了教训</i>\n\nsource-1614\n02:22:45.566 --> 02:22:48.694 align:middle line:100%,end position:50%,middle\n<i>在最新一期《千禧年》中\n他现在指控</i>\n\nsource-1615\n02:22:48.861 --> 02:22:51.530 align:middle line:100%,end position:50%,middle\n<i>曾起诉他的温纳斯壮集团</i>\n\nsource-1616\n02:22:51.697 --> 02:22:52.865 align:middle line:100%,end position:50%,middle\n这下可要闹大了\n\nsource-1617\n02:22:53.031 --> 02:22:55.909 align:middle line:100%,end position:50%,middle\n<i>从事国际犯罪</i>\n\nsource-1618\n02:22:56.076 --> 02:22:57.327 align:middle line:100%,end position:50%,middle\n现在呢？\n\nNATIVE-044\n02:22:57.494 --> 02:23:00.664 align:middle line:100%,end position:50%,middle\n他会说是私人报复，但这说不过去\n\nNATIVE-045\n02:23:00.831 --> 02:23:03.375 align:middle line:100%,end position:50%,middle\n警方和金融监管局都会调查\n\nsource-1621\n02:23:03.542 --> 02:23:05.961 align:middle line:100%,end position:50%,middle\n案件会上法庭\n也许他会坐牢\n\nsource-1622\n02:23:06.795 --> 02:23:08.505 align:middle line:100%,end position:50%,middle\n你这么认为？\n\nsource-1623\n02:23:08.672 --> 02:23:09.715 align:middle line:100%,end position:50%,middle\n大概很难\n\nsource-1624\n02:23:10.424 --> 02:23:12.342 align:middle line:100%,end position:50%,middle\n这些家伙从不坐牢\n\nsource-1625\n02:23:15.174 --> 02:23:17.073 align:middle line:100%,end position:50%,middle\n（财政黑手党？）\n\nsource-1626\n02:23:18.045 --> 02:23:19.946 align:middle line:100%,end position:50%,middle\n（温纳斯壮被指控多项罪名）\n\nF1501\n02:23:24.563 --> 02:23:26.690 align:middle line:100%,end position:50%,middle\n- 怎么了？\n- 很难启齿\n\nF1502\n02:23:26.857 --> 02:23:29.860 align:middle line:100%,end position:50%,middle\n- 说吧\n- 我需要借点钱\n\nsource-1630\n02:23:30.903 --> 02:23:32.362 align:middle line:100%,end position:50%,middle\n五万\n\nsource-1631\n02:23:34.489 --> 02:23:37.784 align:middle line:100%,end position:50%,middle\n我有个聪明又安全的投资机会\n\nsource-1632\n02:23:37.951 --> 02:23:41.246 align:middle line:100%,end position:50%,middle\n- 我不认为我有五万\n- 你有\n\nsource-1633\n02:23:41.413 --> 02:23:44.875 align:middle line:100%,end position:50%,middle\n你两个账户加起来有六万五\n\nsource-1634\n02:23:45.042 --> 02:23:47.169 align:middle line:100%,end position:50%,middle\n抱歉，我知道这些\n\nsource-1635\n02:23:48.712 --> 02:23:50.464 align:middle line:100%,end position:50%,middle\n保证还你\n\nsource-1636\n02:23:51.757 --> 02:23:52.799 align:middle line:100%,end position:50%,middle\n好\n\nsource-1637\n02:23:53.717 --> 02:23:55.093 align:middle line:100%,end position:50%,middle\n好\n\nsource-1638\n02:23:56.428 --> 02:23:58.347 align:middle line:100%,end position:50%,middle\n要咖啡吗？\n\nsource-1639\n02:24:01.808 --> 02:24:06.271 align:middle line:100%,end position:50%,middle\n<i>这所谓记者这次的指控\n和上次一样</i>\n\nsource-1640\n02:24:06.438 --> 02:24:08.357 align:middle line:100%,end position:50%,middle\n<i>既荒谬，又不属实</i>\n\nsource-1641\n02:24:08.524 --> 02:24:11.944 align:middle line:100%,end position:50%,middle\n<i>我期待再次与布隆维斯特\n在法庭上见面</i>\n\nNATIVE-046\n02:24:12.110 --> 02:24:15.697 align:middle line:100%,end position:50%,middle\n<i>- 那些文件证据呢？\n- 全是伪造的</i>\n\nsource-1644\n02:24:15.864 --> 02:24:19.868 align:middle line:100%,end position:50%,middle\n<i>证券欺诈调查局并没他那么肯定</i>\n\nsource-1645\n02:24:20.035 --> 02:24:23.038 align:middle line:100%,end position:50%,middle\n<i>若布隆维斯特指控的\n有一部分属实</i>\n\nsource-1646\n02:24:23.205 --> 02:24:25.832 align:middle line:100%,end position:50%,middle\n<i>不仅会调查证券欺诈</i>\n\nsource-1647\n02:24:25.999 --> 02:24:28.168 align:middle line:100%,end position:50%,middle\n<i>还会调查有组织犯罪</i>\n\nsource-1648\n02:24:28.335 --> 02:24:29.878 align:middle line:100%,end position:50%,middle\n<i>布隆维斯特没有透露消息来源</i>\n\nsource-1649\n02:24:30.045 --> 02:24:32.756 align:middle line:100%,end position:50%,middle\n<i>我们不能逼他说\n但可以自己去找</i>\n\nsource-1650\n02:24:32.923 --> 02:24:35.634 align:middle line:100%,end position:50%,middle\n<i>- 从哪查起？\n- 温纳斯壮身边的人</i>\n\nsource-1651\n02:24:35.801 --> 02:24:39.012 align:middle line:100%,end position:50%,middle\n<i>只有企业核心人士</i>\n\nsource-1652\n02:24:39.179 --> 02:24:41.056 align:middle line:100%,end position:50%,middle\n<i>才有办法知道这些内幕</i>\n\nsource-1653\n02:24:41.223 --> 02:24:43.559 align:middle line:0%,start position:50%,middle\n<i>温纳斯壮先生暂不回应</i>\n\nsource-1654\n02:24:43.725 --> 02:24:45.519 align:middle line:100%,end position:50%,middle\n<i>但我乐意回答各位问题</i>\n\nsource-1655\n02:24:45.686 --> 02:24:47.855 align:middle line:100%,end position:50%,middle\n<i>- 他本人呢？\n- 我想在家</i>\n\nsource-1656\n02:24:48.021 --> 02:24:50.274 align:middle line:100%,end position:50%,middle\n<i>并不在 已经出国了吗？</i>\n\nsource-1657\n02:24:50.440 --> 02:24:51.900 align:middle line:100%,end position:50%,middle\n<i>我想没有</i>\n\nsource-1658\n02:24:52.103 --> 02:24:53.499 align:middle line:100%,end position:50%,middle\n（苏黎世）\n\nsource-1659\n02:24:57.096 --> 02:24:58.060 align:middle line:100%,end position:50%,middle\n（伊琳奈瑟）\n\nsource-1660\n02:25:02.828 --> 02:25:04.705 align:middle line:100%,end position:50%,middle\n- 谢谢\n- 谢谢\n\nsource-1661\n02:25:13.422 --> 02:25:17.593 align:middle line:100%,end position:50%,middle\n欢迎来到多尔德大酒店\n请出示护照\n\nsource-1662\n02:25:44.494 --> 02:25:45.871 align:middle line:100%,end position:50%,middle\n<i>由于温纳斯壮未能出席</i>\n\nsource-1663\n02:25:46.038 --> 02:25:48.332 align:middle line:100%,end position:50%,middle\n<i>证券交易委员会的听证会</i>\n\nsource-1664\n02:25:48.498 --> 02:25:51.919 align:middle line:100%,end position:50%,middle\n<i>警方已发出逮捕令</i>\n\nsource-1665\n02:25:52.085 --> 02:25:54.046 align:middle line:100%,end position:50%,middle\n<i>我能确认他离开了瑞典</i>\n\nsource-1666\n02:25:54.213 --> 02:25:56.882 align:middle line:100%,end position:50%,middle\n<i>搭私人飞机，上周在巴黎降落</i>\n\nsource-1667\n02:25:58.133 --> 02:26:01.094 align:middle line:0%,start position:50%,middle\n<i>但他是否还在那里\n我们不知道</i>\n\nsource-1668\n02:26:01.261 --> 02:26:03.055 align:middle line:100%,end position:50%,middle\n<i>他可能在任何地方</i>\n\nsource-1669\n02:26:03.250 --> 02:26:04.554 align:middle line:100%,end position:50%,middle\n（转账中）\n\nsource-1670\n02:26:14.441 --> 02:26:15.943 align:middle line:100%,end position:50%,middle\n谢谢\n\nsource-1671\n02:26:17.653 --> 02:26:20.572 align:middle line:100%,end position:50%,middle\n我在开曼群岛的\n克罗嫩费尔德银行有几个账户\n\nsource-1672\n02:26:20.739 --> 02:26:22.908 align:middle line:100%,end position:50%,middle\n我想转出资金，再换成债券\n\nsource-1673\n02:26:23.075 --> 02:26:26.245 align:middle line:100%,end position:50%,middle\n- 您当然有清算代码吧？\n- 当然\n\nNATIVE-047\n02:26:27.412 --> 02:26:30.374 align:middle line:100%,end position:50%,middle\n- 要转出几个账户？\n- 三十个\n\nsource-1676\n02:26:32.292 --> 02:26:35.587 align:middle line:100%,end position:50%,middle\n- 这会花上一点时间\n- 给你百分之四手续费\n\nsource-1677\n02:26:36.380 --> 02:26:38.757 align:middle line:100%,end position:50%,middle\n- 没错\n- 那就不会白费你的时间\n\nsource-1678\n02:26:42.010 --> 02:26:44.054 align:middle line:100%,end position:50%,middle\n<i>一名在巴巴多斯度假的瑞典游客</i>\n\nsource-1679\n02:26:44.221 --> 02:26:48.141 align:middle line:100%,end position:50%,middle\n<i>称他知道在逃金融家\n汉斯·艾瑞克·温纳斯壮在哪</i>\n\nsource-1680\n02:26:48.308 --> 02:26:50.853 align:middle line:100%,end position:50%,middle\n<i>就在巴巴多斯首都布里奇敦</i>\n\nsource-1681\n02:26:51.019 --> 02:26:54.731 align:middle line:100%,end position:50%,middle\n<i>警方公布了这张照片\n认为此人正是那位落魄富豪</i>\n\nsource-1682\n02:27:10.163 --> 02:27:13.125 align:middle line:100%,end position:50%,middle\n其中多少要兑现存入账户？\n\nsource-1683\n02:27:13.292 --> 02:27:14.668 align:middle line:100%,end position:50%,middle\n全部50张，存进五个账户\n\nsource-1684\n02:27:29.558 --> 02:27:31.185 align:middle line:100%,end position:50%,middle\n数字正确\n\nsource-1685\n02:27:36.148 --> 02:27:37.308 align:middle line:100%,end position:50%,middle\n（转账中）\n\nsource-1686\n02:28:43.715 --> 02:28:47.010 align:middle line:100%,end position:50%,middle\n<i>如今人称瑞典庞氏的他</i>\n\nsource-1687\n02:28:47.177 --> 02:28:49.388 align:middle line:100%,end position:50%,middle\n<i>也许再没有国家能让他安身</i>\n\nsource-1688\n02:28:49.555 --> 02:28:51.515 align:middle line:100%,end position:50%,middle\n<i>他倒是有钱买下一个国家</i>\n\nsource-1689\n02:28:51.682 --> 02:28:54.059 align:middle line:100%,end position:50%,middle\n<i>据国际银行委员会</i>\n\nsource-1690\n02:28:54.226 --> 02:28:57.145 align:middle line:100%,end position:50%,middle\n<i>温纳斯壮在《千禧年》的报道</i>\n\nsource-1691\n02:28:57.312 --> 02:28:59.898 align:middle line:100%,end position:50%,middle\n<i>刊出一周后，开始清空</i>\n\nsource-1692\n02:29:00.065 --> 02:29:02.693 align:middle line:100%,end position:50%,middle\n<i>开曼群岛克罗嫩费尔德银行的账户</i>\n\nsource-1693\n02:29:02.860 --> 02:29:05.571 align:middle line:0%,start position:50%,middle\n<i>总额约二十亿欧元</i>\n\nsource-1694\n02:29:05.737 --> 02:29:08.240 align:middle line:100%,end position:50%,middle\n<i>随后被分散存入多个账户</i>\n\nsource-1695\n02:29:08.407 --> 02:29:11.368 align:middle line:0%,start position:50%,middle\n<i>由这名在苏黎世现身的同伙协助</i>\n\nsource-1696\n02:29:15.747 --> 02:29:17.374 align:middle line:100%,end position:50%,middle\n- 嘿\n- 嘿\n\nsource-1697\n02:29:17.541 --> 02:29:19.668 align:middle line:100%,end position:50%,middle\n- 钱还你\n- 这么快\n\nsource-1698\n02:29:21.879 --> 02:29:22.921 align:middle line:100%,end position:50%,middle\n谢谢\n\nsource-1699\n02:29:23.088 --> 02:29:24.548 align:middle line:100%,end position:50%,middle\n我才该谢你\n\nsource-1700\n02:29:27.718 --> 02:29:28.802 align:middle line:100%,end position:50%,middle\n我戒了\n\nsource-1701\n02:29:30.762 --> 02:29:32.097 align:middle line:100%,end position:50%,middle\n投资不错？\n\nNATIVE-048\n02:29:33.098 --> 02:29:36.560 align:middle line:100%,end position:50%,middle\n还不错，你晚点做什么？\n\nsource-1704\n02:29:37.603 --> 02:29:39.229 align:middle line:100%,end position:50%,middle\n去看我女儿\n\nsource-1705\n02:29:39.396 --> 02:29:40.939 align:middle line:100%,end position:50%,middle\n好吧\n\nsource-1706\n02:29:42.441 --> 02:29:43.734 align:middle line:100%,end position:50%,middle\n你变漂亮了\n\nsource-1707\n02:29:46.069 --> 02:29:48.155 align:middle line:100%,end position:50%,middle\n又到了圣诞节\n\nsource-1708\n02:29:49.072 --> 02:29:50.866 align:middle line:100%,end position:50%,middle\n我们很快会再见\n\nNATIVE-049\n02:29:58.832 --> 02:30:03.128 align:middle line:100%,end position:50%,middle\n<i>- 温纳斯壮赢了诽谤官司…</i>\n- 你在办公室接了那通电话\n\nsource-1711\n02:30:15.724 --> 02:30:17.809 align:middle line:100%,end position:50%,middle\n我怀念我们从前的会面\n\nsource-1712\n02:30:19.019 --> 02:30:21.313 align:middle line:100%,end position:50%,middle\n我知道你不会\n毕竟有什么好怀念的？\n\nsource-1713\n02:30:21.480 --> 02:30:24.149 align:middle line:100%,end position:50%,middle\n因为我只会让你头疼\n\nsource-1714\n02:30:24.316 --> 02:30:27.778 align:middle line:100%,end position:50%,middle\n从来没有好消息 都是麻烦事\n\nsource-1715\n02:30:28.946 --> 02:30:30.239 align:middle line:100%,end position:50%,middle\n我现在有一个好消息\n\nsource-1716\n02:30:30.405 --> 02:30:32.199 align:middle line:100%,end position:50%,middle\n我交了一个朋友\n\nsource-1717\n02:30:33.158 --> 02:30:35.619 align:middle line:100%,end position:50%,middle\n我是说 你认可的那种\n\nsource-1718\n02:30:39.289 --> 02:30:40.832 align:middle line:100%,end position:50%,middle\n我很快乐\n\nsource-1719\n02:30:41.416 --> 02:30:44.336 align:middle line:100%,end position:50%,middle\n<i>马贝拉当局确认，此人是</i>\n\nsource-1720\n02:30:44.503 --> 02:30:48.882 align:middle line:100%,end position:50%,middle\n<i>在逃的汉斯·艾瑞克·温纳斯壮\n他头部中了三枪</i>\n\nsource-1721\n02:30:49.049 --> 02:30:51.802 align:middle line:100%,end position:50%,middle\n<i>警方研判他遭到黑道处决</i>\n\nsource-1722\n02:30:51.969 --> 02:30:54.012 align:middle line:100%,end position:50%,middle\n<i>对温纳斯壮与全球犯罪组织</i>\n\nsource-1723\n02:30:54.179 --> 02:30:58.559 align:middle line:0%,start position:50%,middle\n<i>之间联系的调查\n如今只能靠推测了</i>\n\nsource-1724\n02:30:58.725 --> 02:31:01.812 align:middle line:100%,end position:50%,middle\n<i>哪一伙人在瑞典当局之前\n找到了他？</i>\n\nsource-1725\n02:31:01.979 --> 02:31:05.357 align:middle line:100%,end position:50%,middle\n<i>温纳斯壮张扬一生的最后几天…</i>\n\nsource-1726\n02:31:16.159 --> 02:31:18.996 align:middle line:100%,end position:50%,middle\n- 很好\n- 你父亲？\n\nsource-1727\n02:31:19.162 --> 02:31:21.582 align:middle line:100%,end position:50%,middle\n- 一位朋友\n- 肯定是很好的朋友\n\nsource-1728\n02:31:40.900 --> 02:31:41.867 align:middle line:100%,end position:50%,middle\n（M）\n\nsource-1729\n02:32:04.249 --> 02:32:05.834 align:middle line:100%,end position:50%,middle\n- 我们迟到了\n- 现在流行迟到\n";
